BEGIN;
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c7e719f6-0661-57ad-a15b-9fb9d4459e89','Ess tracking','The detection and following of sibilant (ess) energy, the high-frequency bursts produced by /s/, /z/ and /sh/ sounds, in a voice so that it can be attenuated or ridden. A frequency-tracking de-esser, for example, follows the sibilant band and reduces only those moments rather than applying a fixed high-frequency cut.','The sharp ''s'' and ''sh'' sounds in speech are called esses. Ess tracking means following those hissy bursts and turning them down only when they happen. It stops harsh sibilance without dulling the rest of the voice.','It controls harsh sibilance while leaving the rest of the voice bright, because only the sibilant moments are targeted rather than the whole high-frequency range.','A mixer sets a de-esser to track the sibilant frequency of a specific voice, so it clamps down on harsh ''s'' and ''sh'' sounds without softening other consonants or overall clarity.','Dialogue Processing',ARRAY['Fricatives','Sibilance','De-esser','Dynamic-resonance control','Equalization']::text[],ARRAY['Setting the de-esser to a fixed band that does not match the voice, so it misses the sibilant frequency or clamps the wrong range.','Applying too much reduction, which produces a lisping, dulled voice instead of a natural one.','Treating sibilance with a broad treble cut instead of tracking only the ess bursts, which dulls all high-frequency detail.']::text[],ARRAY['De-essing a bright, close-mic''d voice-over.','Controlling harsh sibilance that appears after adding high-frequency EQ or compression.','Smoothing sibilance on a lavalier-recorded actor for a final mix.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c7e719f6-0661-57ad-a15b-9fb9d4459e89' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ess tracking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c7e719f6-0661-57ad-a15b-9fb9d4459e89','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c7e719f6-0661-57ad-a15b-9fb9d4459e89' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '17b47eee-e8a9-54bd-b7bc-61b9e6d5948c','Falsetto','A high vocal register produced when only the thin, ligamentous edges of the vocal folds vibrate while the main muscular body of the folds stays relatively relaxed, giving a light, flute-like tone above the modal range. Because the folds are stretched thin and make limited contact, falsetto carries fewer high harmonics and less power than modal voice.','Falsetto is the airy, high voice a person can make above their normal range. It is a separate vocal register, a distinct way the cords vibrate, not just a high note. Only the thin edges of the vocal cords vibrate, so the sound is light and soft.','It extends a voice above the modal register to reach higher pitches; recognizing it helps editors and mixers explain sudden shifts in a voice''s timbre and level.','A re-recording mixer may ease EQ or de-essing when a performer slips into falsetto, since the register is thinner and brighter, and ADR supervisors note it when matching replacement lines to an original performance.','Voice Production',ARRAY['Fundamental frequency of voice','Formants','Modal register','Head voice','Vibrato']::text[],ARRAY['Confusing falsetto with head voice; falsetto vibrates only the thin fold edges and sounds breathier, whereas head voice keeps more of the fold body engaged.','Treating falsetto as just a high note rather than a register, so editors miss that its timbre and level differ from the same pitch sung in modal voice.','Over-de-essing or heavily EQing falsetto lines, which are already thin and bright, thinning the voice further and making it sound unnatural.']::text[],ARRAY['Matching an ADR line to an original take where the actor briefly slipped into falsetto.','Balancing a musical number where a vocalist shifts between chest voice and falsetto.','Editing a performance in which a character''s voice cracks up into falsetto for comedic or emotional effect.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='17b47eee-e8a9-54bd-b7bc-61b9e6d5948c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Falsetto'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '17b47eee-e8a9-54bd-b7bc-61b9e6d5948c','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='17b47eee-e8a9-54bd-b7bc-61b9e6d5948c' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f06d430c-5de6-53c6-b71d-7fe2e00e9a49','Formants','Formants are the resonant frequency bands of the vocal tract that shape the spectrum of a voice, appearing as concentrations of acoustic energy (labelled F1, F2, F3 and higher) above the fundamental frequency. Their center frequencies, set by the size and shape of the throat, mouth, and lips, determine vowel identity and much of a voice''s individual timbre.','Formants are the boosted frequency bands the throat and mouth add to a voice. This pattern makes an ''ee'' sound different from an ''oo''. It also helps us tell one voice from another.','Formants let listeners distinguish vowels and recognize individual voices; understanding them tells a mixer which frequency regions carry speech identity and intelligibility.','When EQing dialogue a mixer protects the main formant regions in the low-kilohertz range so speech stays natural and intelligible, and avoids deep cuts that remove the frequencies carrying vowel information.','Speech Acoustics',ARRAY['Fundamental frequency of voice','Fricatives','Falsetto','Vowel','Timbre','Equalization']::text[],ARRAY['Confusing formants with the fundamental frequency; pitch can change while formants stay put, and formants can shift while pitch stays the same.','Cutting broad EQ dips in the 1 to 4 kHz region, which weakens formants and makes dialogue sound muffled or unintelligible.','Assuming pitch-shifting a voice also moves formants correctly; naive shifting drags formants along and gives a chipmunk effect unless formant-preserving tools are used.']::text[],ARRAY['Choosing EQ moves so a voice cuts through music and effects without sounding thin.','Using formant-preserving pitch correction on a spoken or sung line.','Diagnosing why a processed voice sounds unnatural after aggressive pitch shifting.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f06d430c-5de6-53c6-b71d-7fe2e00e9a49' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Formants'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f06d430c-5de6-53c6-b71d-7fe2e00e9a49','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f06d430c-5de6-53c6-b71d-7fe2e00e9a49' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'eda7ea7b-48b5-5a22-a72a-fd128a12c51a','Fricatives','Fricatives are consonant speech sounds produced by forcing air through a narrow constriction in the vocal tract, creating turbulent, noise-like energy concentrated in the higher frequencies. English examples include /f/, /v/, /s/, /z/, /sh/ and /th/; the high-energy sibilant fricatives /s/, /z/ and /sh/ are the main source of sibilance in recordings.','Fricatives are hissy consonant sounds like f, s, sh, and v. You make them by pushing air through a narrow gap in the mouth. The sharp ''s'' ones cause harsh sibilance.','Fricatives carry much of the crispness and intelligibility of speech, but their concentrated high-frequency energy is also what de-essers and mixers must tame to control sibilance.','A dialogue mixer identifies fricative energy, especially sibilants roughly in the 5 to 10 kHz range, to set de-essing and high-frequency EQ so consonants stay clear without becoming harsh.','Speech Acoustics',ARRAY['Sibilance','Formants','De-esser','Fundamental frequency of voice','Ess tracking']::text[],ARRAY['Assuming all fricatives are sibilant; only the high-energy sibilants like /s/, /z/ and /sh/ drive harsh ess problems, while /f/, /v/ and /th/ are much lower in energy.','Rolling off too much high frequency to fight sibilance, which dulls all fricatives and robs speech of clarity.','Confusing sibilance control with simply cutting treble; effective control targets only the narrow sibilant band, not the whole high end.']::text[],ARRAY['Setting up a de-esser on a sibilant voice actor.','Cleaning up close-mic''d dialogue where ''s'' and ''sh'' sounds are harsh.','Deciding EQ for consonant clarity on a mumbled or distant recording.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='eda7ea7b-48b5-5a22-a72a-fd128a12c51a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fricatives'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'eda7ea7b-48b5-5a22-a72a-fd128a12c51a','739bdba4-0fac-4455-9ee2-1a56096cab92',true
