INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9d4eb144-1a18-50e3-9034-b2af0c62a169','Fundamental frequency of voice','The fundamental frequency (F0) of the voice is the rate at which the vocal folds vibrate, perceived as the pitch of speech or singing and measured in hertz. Typical speaking values are roughly 100 to 150 Hz for adult men and 150 to 250 Hz for adult women, with children higher; the harmonics of the voice occur at whole-number multiples of F0.','The fundamental frequency is how fast the vocal cords open and close. We hear it as the pitch of a voice. It sits near 100 to 150 hertz for men and 150 to 250 hertz for women.','F0 sets the perceived pitch and melody of a voice and anchors its harmonic series; knowing a voice''s F0 range guides high-pass filtering and pitch processing without harming the voice.','A mixer uses F0 to set a safe high-pass filter that cuts rumble below the voice''s lowest fundamental, and to choose pitch-correction or pitch-shift settings that fit the performer''s range.','Speech Acoustics',ARRAY['Formants','Falsetto','Pitch','High-pass filter','Harmonics']::text[],ARRAY['Confusing fundamental frequency with formants; F0 is the pitch set by the vocal folds, while formants are separate vocal-tract resonances that shape timbre.','Setting a high-pass filter too high and cutting into a low male voice''s fundamental, making it sound thin and weak.','Assuming the loudest part of a voice''s spectrum is its fundamental; often a harmonic or a formant region is stronger than F0 itself.']::text[],ARRAY['Choosing a high-pass frequency to remove rumble without thinning a deep voice.','Setting the pitch range for pitch correction on dialogue or vocals.','Analyzing a voice to match a replacement performer or ADR line.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9d4eb144-1a18-50e3-9034-b2af0c62a169' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fundamental frequency of voice'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9d4eb144-1a18-50e3-9034-b2af0c62a169','739bdba4-0fac-4455-9ee2-1a56096cab92',true
