INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fef4faee-a7a4-5352-9029-e32178977fb8','Honk suppression','Honk suppression is the reduction of an unpleasant nasal or boxy midrange resonance - perceived as a ''honk'' - in a voice or instrument, typically by cutting the offending narrow band with fixed or dynamic equalization. It targets a resonant coloration that makes a source sound pinched or hooty, without materially lowering the source''s overall level.','Some voices or instruments have a harsh, nasal ''honk'' in the midrange. It sounds pinched, like talking through the nose. Honk suppression cuts that narrow band of sound. Engineers usually use an equalizer to dip it. The goal is a more natural tone without turning the whole voice down.','It removes a distracting resonant coloration so a voice sits more naturally in the mix, improving tone and clarity without dropping the source''s overall loudness.','A mixer sweeps a narrow equalizer boost to find the honky frequency, then cuts it, or sets a dynamic equalizer to duck that band only when it rings out.','Dialogue Processing',ARRAY['Equalization','Dynamic EQ','Nasal-formant control','Resonance','Intelligibility lift','De-essing']::text[],ARRAY['Cutting a wide band instead of a narrow notch, which thins the whole voice rather than just the honk.','Guessing the frequency instead of sweeping to locate the exact resonance.','UNSAFE: Turning up monitor level to chase a subtle honk instead of soloing and metering it, risking hearing fatigue and damage over a long session - keep to calibrated monitoring levels and observe OSHA hearing-exposure limits.']::text[],ARRAY['Taming a nasal, hooty quality on a lavalier-mic dialogue recording.','Reducing boxy midrange on a voice recorded in a small, reflective room.','Setting a dynamic equalizer to catch honk only on louder, projected lines.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fef4faee-a7a4-5352-9029-e32178977fb8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Honk suppression'),'[^a-z0-9]','','g'));
