WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fef4faee-a7a4-5352-9029-e32178977fb8' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b8a07fc-7dea-590d-916c-51d210500a21','Intelligibility lift','Intelligibility lift is the deliberate raising of dialogue intelligibility within a mix - making words easier to understand - through targeted equalization (often in the consonant/presence range), dynamic control, noise reduction, and by ducking or clearing competing music and effects, rather than by simply raising dialogue level. Speech intelligibility itself is quantified by measures such as the Speech Transmission Index (STI).','In a busy mix, words can get lost under music and effects. An intelligibility lift makes the dialogue easier to understand. Engineers boost the range that carries consonants and lower sounds that clash. They may also cut noise. The aim is clear speech, not just a louder track.','It ensures the audience can follow the dialogue - the primary carrier of story - even under dense music and effects, which is a core goal of the re-recording mix.','A re-recording mixer adds a presence-range equalizer boost, dips competing elements with side-chain ducking, and cleans noise so lines stay clear across cinema and small-speaker playback.','Dialogue Mixing',ARRAY['Speech Transmission Index','Equalization','Ducking','Dialogue stem','Noise reduction','Honk suppression']::text[],ARRAY['Only raising dialogue level, which fights the music instead of clearing space for the words.','Boosting broad low-mids that add mud rather than the higher range that carries consonant detail.','UNSAFE: Cranking monitor loudness to judge whether words are clear, instead of mixing at calibrated reference level, which risks noise-induced hearing loss - observe calibrated monitoring and OSHA hearing-exposure limits.']::text[],ARRAY['Keeping whispered dialogue intelligible under a loud action cue.','Ensuring lines survive on phone and TV speakers as well as in the cinema.','Clearing crowd walla so a foreground line reads clearly.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b8a07fc-7dea-590d-916c-51d210500a21' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Intelligibility lift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b8a07fc-7dea-590d-916c-51d210500a21','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b8a07fc-7dea-590d-916c-51d210500a21' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f9a1cf10-4579-52c5-bd0f-f0e980953e8f','Lip-synchrony loss','Lip-synchrony loss is a perceptible breakdown of the correspondence between the dialogue heard and the lip movements seen on screen, whether from audio/video timing drift, an edit, sample-rate or frame-rate conversion, or dubbed dialogue that does not match the original articulation. Beyond a small tolerance the mismatch becomes noticeable and distracting to the viewer.','Normally a character''s voice matches their moving lips. Lip-synchrony loss is when they stop lining up. The words may arrive too early or too late. It can come from timing errors, edits, or dubbing. Once the gap is big enough, viewers notice and get pulled out of the scene.','Naming this failure lets editors and mixers watch for and correct sync errors, because mismatched voice and lips break the illusion and reduce comprehension.','An editor nudges dialogue in frames or milliseconds against the picture to restore sync after conform, ADR, or dubbing, checking against the actor''s mouth on close-ups.','Sync and Alignment',ARRAY['Lip sync','ADR','Conform','Dubbing','Audio/video sync','SMPTE timecode']::text[],ARRAY['Correcting sync on a wide shot where the lips are unclear, then finding it wrong on the close-up.','Assuming a constant offset when the drift grows across the reel from a frame-rate mismatch.','Fixing the picture-to-sound offset by ear alone without confirming against a sync reference or slate.']::text[],ARRAY['Diagnosing a slow sync drift after a 24-to-25 frames-per-second conversion.','Re-aligning ADR lines that sit slightly ahead of the actor''s lips.','Checking a dubbed foreign-language track against the original mouth movements.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f9a1cf10-4579-52c5-bd0f-f0e980953e8f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lip-synchrony loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f9a1cf10-4579-52c5-bd0f-f0e980953e8f','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f9a1cf10-4579-52c5-bd0f-f0e980953e8f' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ceb0d33b-462e-5e6e-84a0-2df2727ee601','Microdynamic preservation','Microdynamic preservation is the practice of retaining the small, short-term dynamic variations and transient detail within a signal - the moment-to-moment level fluctuations of syllables, plosives, and attacks - rather than flattening them with heavy compression or limiting. It contrasts with macrodynamics, the long-term loud-to-soft structure of a program.','Sound has big loud-soft changes and tiny quick ones. The tiny fast changes are microdynamics - the punch of each word or hit. Heavy compression can squash them flat. Microdynamic preservation means keeping that fine detail alive. It keeps dialogue and music sounding natural and lively.','It keeps speech and music sounding natural, punchy, and lifelike by protecting transient detail that over-compression would flatten, which matters most where loudness targets tempt heavy processing.','A mixer uses gentle ratios, slower attack times, or parallel compression so dialogue meets loudness targets without losing the transient life of consonants and attacks.','Dynamics Processing',ARRAY['Compression','Limiting','Macrodynamics','Transient','Loudness normalization','Parallel compression']::text[],ARRAY['Over-compressing to hit a loudness target, which flattens transients and makes dialogue sound lifeless.','Using a fast attack that clamps every consonant, erasing the very detail that aids clarity.','Judging only the loudness meter and ignoring how squashed the microdynamics have become.']::text[],ARRAY['Meeting a loudness target such as EBU R128''s minus 23 LUFS without crushing dialogue punch.','Keeping the snap of foley footsteps after bus compression.','Choosing parallel over heavy serial compression to preserve detail.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ceb0d33b-462e-5e6e-84a0-2df2727ee601' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Microdynamic preservation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ceb0d33b-462e-5e6e-84a0-2df2727ee601','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ceb0d33b-462e-5e6e-84a0-2df2727ee601' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '52de435a-9d6d-58d5-bd41-fb1a85e2bd78','Nasal-formant control','Nasal-formant control is the shaping - by equalization or dynamic processing - of the nasal resonances and anti-resonances that a coupled nasal cavity adds to the voice, in order to increase or reduce perceived nasality. Nasal sounds introduce a low-frequency nasal murmur plus additional formants and spectral zeros (antiformants); managing these bands adjusts how nasal a voice reads.','When we make sounds like ''m'' or ''n'', the nose adds its own resonances to the voice. Too much can make speech sound nasal or blocked. Nasal-formant control uses an equalizer to raise or lower those bands. It can reduce a whiny, nasal tone. It can also add nasal character when a scene needs it.','It lets a mixer or editor correct or stylize the nasal quality of a voice - fixing a distracting timbre, matching a performance, or matching ADR to production dialogue.','A dialogue mixer dips the nasal resonance band to reduce a honky, nasal quality, or nudges it to match a re-voiced ADR line to the original recording.','Dialogue Processing',ARRAY['Formant','Glottal pulse','Honk suppression','Equalization','Antiformant','ADR']::text[],ARRAY['Confusing nasal formants (from the nasal cavity) with the oral vowel formants that define vowel identity.','Applying a broad cut that dulls the whole voice instead of targeting the nasal band.','Assuming all midrange nasal honk comes from the nose when room resonance can mimic it.']::text[],ARRAY['Reducing an overly nasal quality on a boom-recorded line.','Matching an ADR replacement''s nasality to the production take.','Adding slight nasality to a character voice for effect.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='52de435a-9d6d-58d5-bd41-fb1a85e2bd78' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nasal-formant control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '52de435a-9d6d-58d5-bd41-fb1a85e2bd78','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='52de435a-9d6d-58d5-bd41-fb1a85e2bd78' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '905d1fe9-db41-545e-8be3-e9405c1b51f5','Object dialogue','In object-based audio (such as Dolby Atmos), object dialogue is dialogue authored as one or more audio objects - audio elements carried with positional and other metadata and rendered to the playback layout at run time - rather than fixed into a channel bed. This keeps dialogue steerable and individually controllable and supports features such as dialogue enhancement or level personalization on playback.','Older surround mixes lock each sound to fixed speakers. Object-based audio instead sends a sound plus data saying where it should go. Object dialogue is speech handled this way. The playback system places it correctly for whatever speakers are present. It can also let viewers raise the dialogue on their own.','It lets dialogue be positioned and rendered accurately across many speaker layouts and enables per-listener control, such as raising dialogue relative to the rest of the mix.','An Atmos mixer assigns key lines to dialogue objects with position metadata, monitoring how the renderer places them on cinema, home, and headphone layouts.','Object-Based Audio',ARRAY['Audio object','Dolby Atmos','Bed','Renderer','Dialogue enhancement','Print master']::text[],ARRAY['Assuming an object is tied to a specific speaker, when the renderer places it from its metadata.','Panning dialogue objects hard off-center so lines pull away from the screen and lose focus.','Confusing objects (metadata-driven, rendered) with channel-bed dialogue (fixed to set channels).']::text[],ARRAY['Authoring a Dolby Atmos mix where featured lines are objects.','Checking how object dialogue renders on a 5.1 fold-down.','Enabling dialogue enhancement that raises the dialogue objects for the viewer.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='905d1fe9-db41-545e-8be3-e9405c1b51f5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Object dialogue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '905d1fe9-db41-545e-8be3-e9405c1b51f5','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='905d1fe9-db41-545e-8be3-e9405c1b51f5' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd6a20f27-1a1d-5c02-923d-61eab170c780','Off-screen source voice','An off-screen source voice is diegetic dialogue - speech belonging to the world of the scene - whose speaker is present in that world but not visible within the current frame. Because the source is unseen yet real to the scene, the voice is mixed with the scene''s perspective, spatial position, and acoustics, and may motivate a cut or pan toward the speaker.','Sometimes a character talks but we cannot see them in the shot. They are still part of the scene, just off the edge of the frame. That is an off-screen source voice. Mixers place it to the side or in the room''s echo. It makes the space feel real and can pull our attention that way.','It extends the scene beyond the frame, letting characters and events exist off-camera, and gives the mixer spatial cues that make the world feel continuous and three-dimensional.','A mixer pans and reverberates an unseen speaker to the correct side and distance, so the audience senses where the character is before or without a cut to them.','Dialogue Perspective',ARRAY['On-screen source voice','Diegetic sound','Perspective','Acousmatic sound','Voice-over','Panning']::text[],ARRAY['Confusing an off-screen source voice (diegetic, in the scene) with non-diegetic voice-over or narration.','Mixing it dead-center and dry, ignoring the cue that it comes from off to one side.','Over-reverberating it so a nearby unseen speaker sounds distant.']::text[],ARRAY['A character answers from another room just out of frame.','Placing an unseen speaker''s line to screen-left before a cut reveals them.','Keeping a crowd heckler''s voice off-camera but clearly in the space.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d6a20f27-1a1d-5c02-923d-61eab170c780' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Off-screen source voice'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd6a20f27-1a1d-5c02-923d-61eab170c780','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d6a20f27-1a1d-5c02-923d-61eab170c780' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a88494d3-e1d5-54be-9c51-2b29d940369b','On-screen source voice','An on-screen source voice is diegetic dialogue whose speaker is visible within the current frame, so the sound is expected to match the seen source in position, perspective, and lip movement. It is mixed to sit with the picture - usually near center for a framed speaker - with perspective and acoustics matching the shot''s distance and space.','This is when we can see the person who is talking, right there in the shot. Their voice should match their lips and their place in the frame. Mixers usually keep such dialogue near the center. The tone and echo are set to match how close the shot is. Seeing the speaker makes sync and placement matter most.','It anchors dialogue to a visible speaker so voice, lip movement, and screen position agree, which the audience reads as natural and which keeps focus on the speaker.','A mixer keeps a framed speaker''s line centered and in sync, adjusting equalization and reverb so a close-up sounds intimate and a wide shot sounds more distant.','Dialogue Perspective',ARRAY['Off-screen source voice','Diegetic sound','Perspective','Lip sync','Center channel','Dialogue stem']::text[],ARRAY['Panning a centered on-screen speaker off to a surround, pulling the voice away from the visible source.','Ignoring perspective so a distant wide-shot line sounds as close as a close-up.','Letting lip-sync drift on close-ups, where the mismatch is most visible.']::text[],ARRAY['Mixing a framed two-shot conversation to the center channel.','Matching a line''s closeness to a tight close-up versus a wide shot.','Keeping a visible singer''s voice locked to their lip movements.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a88494d3-e1d5-54be-9c51-2b29d940369b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('On-screen source voice'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a88494d3-e1d5-54be-9c51-2b29d940369b','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a88494d3-e1d5-54be-9c51-2b29d940369b' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '79b9e159-0a2a-57c4-a1a2-0a91dcda5b5b','Paralinguistic transfer','The carrying over of paralinguistic vocal features - intonation, tempo, loudness, breathiness, and non-lexical vocal cues - from an original spoken performance to a replacement or dubbed one, so the emotional and attitudinal content survives even when the words are re-recorded. Paralinguistic features sit alongside the lexical content and convey attitude, emotion, and emphasis.','When we speak, more than words carry meaning. Tone, pace, and breath show how we feel. Paralinguistic transfer means keeping those vocal clues when a line is re-recorded or dubbed. The new take should feel the same, even in a new voice.','It exists so re-recorded or translated dialogue keeps a performance''s emotional truth, not just its words, preserving the audience''s connection to the character.','An ADR mixer or dubbing director coaches the replacement performance to match the original''s pacing, stress, and breaths so the emotion carries across.','Dialogue & ADR',ARRAY['Prosody transfer','Phonetic paraphrasing','ADR (Automated Dialogue Replacement)','Perspective riding','Phonetic synchronization loss']::text[],ARRAY['Treating a line as correct because the words match, when the tone, pacing, and breaths do not, which loses the original emotion.','Confusing paralinguistic features (how something is said) with lexical content (the actual words), and only checking the words.','UNSAFE: Pushing dubbing-stage monitors to high levels to ''feel'' subtle vocal nuance; sustained loud monitoring risks noise-induced hearing loss, so mix at the room''s calibrated reference level and keep exposure within OSHA limits (85 dBA action level, 90 dBA 8-hour limit).']::text[],ARRAY['Directing an ADR session so a re-recorded line keeps the actor''s original emotional delivery.','Supervising a foreign-language dub where a new voice must match the original performance''s attitude.','Comparing a replacement take against the production guide track for matching tone and emphasis.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='79b9e159-0a2a-57c4-a1a2-0a91dcda5b5b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Paralinguistic transfer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '79b9e159-0a2a-57c4-a1a2-0a91dcda5b5b','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='79b9e159-0a2a-57c4-a1a2-0a91dcda5b5b' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b2a45229-e7fb-5ec5-a862-00fc1caedcb5','Perspective riding','The continuous manual adjustment of a dialogue element''s level - and often its EQ and reverb - during re-recording so that the voice''s apparent loudness and spatial character track the camera''s viewpoint, sitting closer in tight shots and more distant in wide shots. It keeps sonic perspective consistent with visual perspective.','In a film, a close-up should sound near. A wide shot should sound far away. Perspective riding is when the mixer moves the volume as the shots change. The voice gets softer and more roomy when the camera pulls back.','It maintains believable spatial continuity between image and sound, so changes in shot size do not break the illusion that the voice comes from the pictured space.','A re-recording mixer rides the dialogue fader, and may add room tone or reverb, shot by shot so a character sounds nearer in close-ups and farther in wide or exterior shots.','Re-Recording Mix',ARRAY['Phrase-level riding','Production-space emulation','Presence lift','Pre-compressor riding','Post-compressor riding']::text[],ARRAY['Overdoing perspective changes so level jumps between shots become distracting instead of natural.','Riding only level while ignoring EQ and reverb, so a ''distant'' shot is quieter but still sounds close and dry.','UNSAFE: Judging fine perspective moves by cranking the monitors; prolonged high sound-pressure levels risk permanent hearing damage, so work at the stage''s calibrated reference level and respect OSHA exposure limits (85 dBA action level, 90 dBA 8-hour limit).']::text[],ARRAY['Mixing a dialogue scene that intercuts close-ups with wide establishing shots.','Matching an ADR line''s perspective to the on-screen camera distance.','Following a character who walks from close to the camera into the far background.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b2a45229-e7fb-5ec5-a862-00fc1caedcb5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Perspective riding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b2a45229-e7fb-5ec5-a862-00fc1caedcb5','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b2a45229-e7fb-5ec5-a862-00fc1caedcb5' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1459fc9c-58da-599d-929a-a3dafd36dcbe','Phonetic paraphrasing','In dubbing, the rewording of translated dialogue so that its speech sounds - particularly the visible articulations at labial consonants and at the open and closed positions of the mouth - align with the on-screen actor''s lip movements, favoring phonetic and visual match over literal translation. It is one strategy for achieving lip synchrony.','When a film is dubbed into a new language, the words must fit the actor''s mouth. Phonetic paraphrasing means changing the wording so the sounds match the lips. The meaning stays close, but the sounds fit the picture better.','It exists to make dubbed dialogue look believable, choosing wordings whose visible mouth shapes match the picture so the audience does not notice the substitution.','A dubbing translator or adaptor swaps a literal phrase for one whose bilabial and open-mouth sounds land where the actor''s lips close and open on screen.','Dialogue & ADR',ARRAY['Phonetic synchronization loss','Prosody transfer','Paralinguistic transfer','ADR (Automated Dialogue Replacement)','Plosives']::text[],ARRAY['Translating literally without regard for lip shapes, so the dub looks out of sync on close-ups.','Changing so much for lip match that the line''s meaning or register drifts away from the original.','Ignoring where bilabial consonants (p, b, m) fall, since these closed-lip moments are the most visible sync points.']::text[],ARRAY['Adapting a translated script so labial sounds match an actor''s lip closures in close-up.','Reworking a dubbed line that reads correctly but looks out of sync on screen.','Prioritizing visual sync over word-for-word translation in a feature dub.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1459fc9c-58da-599d-929a-a3dafd36dcbe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phonetic paraphrasing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1459fc9c-58da-599d-929a-a3dafd36dcbe','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1459fc9c-58da-599d-929a-a3dafd36dcbe' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9207ed6b-2ab3-5a11-9b74-759a4d42ee7a','Phonetic synchronization loss','A breakdown in lip synchrony in which the speech sounds heard no longer match the visible articulations on screen - for example, a labial consonant is heard while the actor''s lips are open - even when the overall timing seems close. It describes mismatch at the level of individual speech sounds rather than gross timing offset.','Lip-sync can fail in a small way. The timing looks close, but the sounds do not match the mouth. You might hear a ''p'' while the lips are open. That small mismatch is phonetic synchronization loss.','Naming this failure helps editors and mixers diagnose why a dub or ADR line looks ''off'' even when its start and end line up, pointing them to the mismatched sounds.','A dialogue editor spots that a replacement line''s consonants do not land on the actor''s lip closures and nudges timing or requests a re-take or re-adaptation.','Dialogue & ADR',ARRAY['Phonetic paraphrasing','Plosives','Prosody transfer','Paralinguistic transfer','ADR (Automated Dialogue Replacement)']::text[],ARRAY['Assuming a line is in sync because its start and end match, while individual sounds drift against the lips.','Fixing sync by sliding the whole line when only certain consonants are misaligned.','Overlooking bilabial consonants (p, b, m), whose visible lip closures reveal phonetic sync errors most clearly.']::text[],ARRAY['Reviewing an ADR take that times out correctly but shows mismatched mouth shapes.','Quality-checking a dub for lip-sync on tight close-ups.','Deciding whether a slightly unsynced line needs re-recording or an editorial nudge.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9207ed6b-2ab3-5a11-9b74-759a4d42ee7a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phonetic synchronization loss'),'[^a-z0-9]','','g'));
