INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bc4d1987-6883-5a90-905f-077bb8af0b0b','Phrase-level riding','Manual level automation applied at the granularity of whole spoken phrases rather than individual words or syllables, smoothing a performance so each phrase sits at a consistent, intelligible level. It is a broader-stroke approach to dialogue balancing than word-by-word riding.','Actors say some phrases loud and others soft. Phrase-level riding means the mixer sets the volume phrase by phrase. Each chunk of speech is brought to a steady level. It keeps every line clear without chasing single words.','It evens out performance dynamics so dialogue stays intelligible and consistent, while keeping natural variation by not micro-managing every syllable.','A re-recording mixer writes fader automation for each phrase, lifting quiet phrases and easing loud ones so a scene reads at a uniform dialogue level.','Re-Recording Mix',ARRAY['Perspective riding','Pre-compressor riding','Post-compressor riding','Presence lift','Paralinguistic transfer']::text[],ARRAY['Riding every single word so the dialogue sounds unnatural and over-controlled.','Riding phrases so aggressively that natural emphasis and emotion are flattened out.','Leaning on the compressor to do all the leveling instead of first riding phrases into it.']::text[],ARRAY['Balancing a monologue where the actor''s projection varies from line to line.','Smoothing dialogue levels across a scene before applying compression.','Bringing a whispered phrase up to match the surrounding lines.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bc4d1987-6883-5a90-905f-077bb8af0b0b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phrase-level riding'),'[^a-z0-9]','','g'));
