INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '09f80d29-ec6c-51d8-8895-7d375c64ceae','Pitch shifting without formant correction','A pitch-transposition process that scales the entire spectrum, including the vocal-tract formants, along with the fundamental frequency, rather than holding the formants fixed. Because the resonances move with the pitch, upward shifts produce a thin ''chipmunk'' timbre and downward shifts a ''monster'' timbre, as the apparent size of the voice changes.','A voice has a pitch and a natural tone shape called formants. Simple pitch shifting moves both at once. Raise the pitch and the voice sounds thin, like a chipmunk. Lower it and it sounds huge and unnatural. Keeping the tone shape fixed avoids this.','Understanding it explains why naive pitch changes sound unnatural, and why formant-preserving tools exist to move pitch while keeping a voice''s natural size and character.','A mixer who transposes a line and hears a ''chipmunk'' effect switches to a formant-preserving mode so the corrected pitch keeps a natural vocal timbre.','Vocal Processing',ARRAY['Pitch versus formant','Formant','Pitch correction','Presence lift','Prosody transfer']::text[],ARRAY['Assuming any pitch shift preserves natural voice quality, when unshifted formants require a formant-correction mode.','Confusing pitch (fundamental frequency) with formants (vocal-tract resonances) and expecting them to move together naturally.','Applying large transpositions for disguise or effect and being surprised the voice no longer sounds human.']::text[],ARRAY['Transposing a sung or spoken line and hearing an unnatural chipmunk timbre.','Choosing between formant-preserving and non-preserving modes for a voice effect.','Creating a deliberately monstrous or cartoonish voice by shifting pitch without formant correction.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='09f80d29-ec6c-51d8-8895-7d375c64ceae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pitch shifting without formant correction'),'[^a-z0-9]','','g'));
