SELECT '09f80d29-ec6c-51d8-8895-7d375c64ceae','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='09f80d29-ec6c-51d8-8895-7d375c64ceae' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b38cdf1d-bcb5-5592-8404-982e900775d8','Pitch versus formant','The distinction between pitch - the fundamental frequency set by the rate of vocal-fold vibration - and formants - the resonant peaks of the vocal tract that shape timbre and vowel identity. In the source-filter model the two are largely independent: pitch is the source and formants are the filter, and either can change without the other.','Your voice has two separate parts. Pitch is how high or low the note is. Formants are the tone color that shapes vowels and your voice''s character. They work on their own. You can raise your pitch while your formants stay the same.','The concept underpins natural-sounding pitch and voice processing, telling engineers which control changes note height and which changes vocal character and apparent size.','A mixer uses this distinction to decide whether to move pitch, formants, or both when tuning a vocal or de-aging and disguising a voice.','Vocal Processing',ARRAY['Pitch shifting without formant correction','Formant','Pitch correction','Presence lift','Plosives']::text[],ARRAY['Thinking a higher-pitched voice must have higher formants, when the two are set by different mechanisms.','Trying to change a voice''s perceived size or gender by pitch alone, ignoring the formants that carry that cue.','Assuming formants shift automatically and correctly whenever pitch is changed in software.']::text[],ARRAY['Explaining why formant-preserving pitch correction sounds more natural.','Adjusting formants to shift a voice''s apparent age or size without changing the note.','Diagnosing why a transposed vocal sounds unnaturally thin or thick.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b38cdf1d-bcb5-5592-8404-982e900775d8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pitch versus formant'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b38cdf1d-bcb5-5592-8404-982e900775d8','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b38cdf1d-bcb5-5592-8404-982e900775d8' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bee9189a-feb0-588f-b838-3d70d2aa991c','Plosive control','The techniques used to prevent or reduce the low-frequency energy bursts (''pops'') that plosive consonants such as /p/ and /b/ produce when their release blast strikes a microphone. Methods include pop filters and mic placement at capture, and high-pass filtering, level automation, or specialized de-plosive processing during editing and mixing.','Sounds like ''p'' and ''b'' push out a burst of air. On a mic this makes a loud thump called a pop. Plosive control means stopping or fixing those pops. You can use a pop shield, move the mic, or filter the low thump later.','It protects dialogue from distracting low-frequency thumps that can overload a channel and pull focus, keeping the voice clean and consistent.','An editor high-passes or manually reduces the low-frequency thump under a popped ''p'', or a recordist adds a pop filter and offsets the mic to prevent it at the source.','Dialogue & ADR',ARRAY['Plosives','Presence lift','Phrase-level riding','Pre-compressor riding','Production-space emulation']::text[],ARRAY['Fixing pops with a broad, high high-pass filter that thins the whole voice instead of targeting the brief low-frequency burst.','Pointing the microphone straight at the mouth with no pop filter or offset, which guarantees plosive pops.','Ignoring a plosive''s low-frequency energy, which can overload a preamp or trigger a compressor unnaturally.']::text[],ARRAY['Cleaning popped p''s and b''s in a close-mic''d ADR recording.','Setting up a mic with a pop filter for a voiceover session.','High-passing dialogue to remove plosive thumps without dulling the voice.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bee9189a-feb0-588f-b838-3d70d2aa991c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Plosive control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bee9189a-feb0-588f-b838-3d70d2aa991c','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bee9189a-feb0-588f-b838-3d70d2aa991c' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '14dc70be-dc0d-5f45-ad58-ec942da76ace','Plosives','Plosives (stop consonants) are speech sounds produced by fully blocking the airflow in the vocal tract, building up air pressure behind the closure, and then releasing it in a sudden burst - for example English /p/, /b/, /t/, /d/, /k/, and /g/. In audio, their release burst, especially for bilabial /p/ and /b/, carries brief low-frequency energy that can ''pop'' a microphone.','Plosives are sounds like p, b, t, d, k, and g. To make them, you block the air in your mouth, then let it burst out. That burst of air can hit a mic and make a popping thump. Sound crews plan for this when they record speech.','Recognizing plosives helps recordists and editors anticipate and manage the pops and bursts these consonants create, which matter for clean dialogue capture.','A boom operator or engineer positions the mic off-axis and uses a pop filter to tame the bursts from plosive consonants during dialogue recording.','Dialogue & ADR',ARRAY['Plosive control','Presence lift','Phonetic synchronization loss','Phonetic paraphrasing','Sibilance']::text[],ARRAY['Confusing plosives (burst stops like p and t) with sibilants (hissy sounds like s and sh), which need different treatment.','Assuming all plosives pop equally, when bilabial p and b produce the strongest low-frequency bursts.','Placing a microphone directly in the plosive airstream, inviting pops instead of angling it off-axis.']::text[],ARRAY['Anticipating pops when close-micing a voice heavy with p and b sounds.','Explaining why a voiceover needs a pop filter.','Marking plosive-heavy words as lip-sync reference points in dubbing.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='14dc70be-dc0d-5f45-ad58-ec942da76ace' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Plosives'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '14dc70be-dc0d-5f45-ad58-ec942da76ace','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='14dc70be-dc0d-5f45-ad58-ec942da76ace' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '54ca45e5-0203-5dc9-9936-60d577d598f5','Post-compressor riding','Manual level automation applied after the compressor in a signal chain, adjusting the already-compressed dialogue so its output sits at the desired balance without changing how much the compressor reacts. Because the ride follows the compression, it sets final level rather than influencing gain reduction.','A compressor evens out loud and soft parts. Post-compressor riding means the mixer changes the volume after the compressor. It sets the final level of the smoothed signal. It does not change how hard the compressor squeezes.','It lets a mixer set final dialogue balance independently of the compressor''s behavior, since moves after compression do not alter the gain reduction itself.','A re-recording mixer rides the fader after a dialogue compressor to place lines in the final balance, knowing these moves will not retrigger or change the compression.','Re-Recording Mix',ARRAY['Pre-compressor riding','Phrase-level riding','Perspective riding','Presence lift','Paralinguistic transfer']::text[],ARRAY['Expecting post-compressor rides to change the amount of compression, when only pre-compressor level does that.','Riding hard after heavy compression, which exaggerates the noise floor the compressor has already lifted.','Confusing where the ride sits in the chain, so intended dynamics control is applied in the wrong place.']::text[],ARRAY['Setting final line-by-line dialogue balance after a compressor.','Making level moves that must not alter the compression character.','Placing compressed narration into a music-and-effects balance.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='54ca45e5-0203-5dc9-9936-60d577d598f5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-compressor riding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '54ca45e5-0203-5dc9-9936-60d577d598f5','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='54ca45e5-0203-5dc9-9936-60d577d598f5' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b4b3badf-9dc7-5d93-9148-23fd6ae715e3','Pre-compressor riding','Manual level automation applied before the compressor in a signal chain, so that evening out the dialogue changes how much the following compressor reacts. Feeding the compressor a more consistent input reduces the gain reduction it must apply, yielding a more natural, transparent result.','A compressor squeezes loud parts down. Pre-compressor riding means the mixer smooths the volume before it reaches the compressor. Because the signal is already even, the compressor has less work to do. The result sounds more natural.','It reduces how hard the compressor has to work by handing it a pre-smoothed signal, giving more natural, transparent dynamics control than compression alone.','A mixer rides quiet and loud lines toward a consistent level before the compressor, so the compressor only catches remaining peaks rather than pumping.','Re-Recording Mix',ARRAY['Post-compressor riding','Phrase-level riding','Perspective riding','Presence lift','Paralinguistic transfer']::text[],ARRAY['Skipping the ride and asking the compressor to do all the leveling, which causes audible pumping and a raised noise floor.','Confusing pre- and post-compressor rides, so leveling meant to ease the compressor is placed after it and has no such effect.','Riding so hard into the compressor that the intended dynamic contrast disappears.']::text[],ARRAY['Smoothing dialogue into a compressor for a natural, even result.','Taming a performance with wide level swings before gentle compression.','Preparing a voiceover so the compressor only trims peaks.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b4b3badf-9dc7-5d93-9148-23fd6ae715e3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-compressor riding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b4b3badf-9dc7-5d93-9148-23fd6ae715e3','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b4b3badf-9dc7-5d93-9148-23fd6ae715e3' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '217ce7f7-06da-5777-816a-91de7fe6ac82','Presence lift','A boost in the upper-midrange ''presence'' region - roughly 3 to 6 kHz - applied to dialogue to increase its clarity, articulation, and sense of forwardness so it stands out against music and effects. It emphasizes consonant detail and the frequencies the ear associates with a voice being close and present.','The presence range is a band of upper-middle sound. Boosting it makes a voice clearer and more up-front. This is a presence lift. Mixers use it so speech cuts through music and effects. Too much of it makes the voice harsh.','It improves dialogue intelligibility and forwardness in a busy mix by emphasizing the consonant-rich frequencies the ear uses to place a voice up close.','A re-recording mixer adds a gentle presence-region EQ boost so dialogue stays clear and forward over a dense music-and-effects bed.','Re-Recording Mix',ARRAY['Perspective riding','Phrase-level riding','Plosive control','Production-space emulation','Sibilance']::text[],ARRAY['Boosting presence too much, making dialogue harsh and edgy or exaggerating sibilance.','Using a presence lift to fix intelligibility that really comes from masking, when a move on the music would work better.','Applying the same presence boost to every voice regardless of the mic, actor, or existing tonal balance.']::text[],ARRAY['Helping dialogue cut through a loud action-scene mix.','Adding clarity to a dull or distant-sounding ADR line.','Matching the presence of a replacement line to the surrounding production dialogue.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='217ce7f7-06da-5777-816a-91de7fe6ac82' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Presence lift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '217ce7f7-06da-5777-816a-91de7fe6ac82','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='217ce7f7-06da-5777-816a-91de7fe6ac82' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9992252e-86ce-5508-b12f-857de7cb2c39','Production-space emulation','The use of reverb, ambience, EQ, and room tone to make dry, studio-recorded dialogue such as ADR sound as though it were recorded in the original on-set acoustic space, so it matches the surrounding production dialogue. It reconstructs the reflections and tonal character of the pictured environment.','Replacement lines are recorded in a dry, quiet booth. But the scene may happen in a tiled room or a big hall. Production-space emulation adds that room''s echo and tone to the dry line. Then the new line sounds like it belongs in the scene.','It makes replacement dialogue blend seamlessly with production recordings by giving booth-recorded lines the reverberation and tonal signature of the on-screen space.','A mixer applies matched reverb and EQ, and sometimes room tone, to an ADR line so it sits convincingly in the scene''s acoustic environment.','Dialogue & ADR',ARRAY['ADR (Automated Dialogue Replacement)','Perspective riding','Presence lift','Room tone','Convolution reverb']::text[],ARRAY['Leaving ADR dry so it sounds detached and obviously studio-recorded against the production dialogue.','Over-adding reverb so the line sounds washier and more distant than the original space.','Matching reverb but ignoring EQ and room tone, so the line''s timbre still betrays the booth.']::text[],ARRAY['Blending an ADR line into a scene shot in a reverberant stairwell.','Matching a looped line to production dialogue recorded on location.','Rebuilding the acoustic of a set for lines that had to be re-recorded.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9992252e-86ce-5508-b12f-857de7cb2c39' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Production-space emulation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9992252e-86ce-5508-b12f-857de7cb2c39','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9992252e-86ce-5508-b12f-857de7cb2c39' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4b983140-3ce5-5692-b449-75400b96b23f','Prosody transfer','The carrying over of prosodic features - intonation contour, stress, rhythm, and tempo - from an original spoken performance to a replacement, dubbed, or converted one, so that the melody and timing of the delivery are preserved even when the voice or words change. Prosody comprises the suprasegmental patterns layered over individual speech sounds.','Prosody is the melody and rhythm of speech. It is the rise and fall, the stress, and the pace. Prosody transfer means keeping that pattern when a line is re-recorded or dubbed. The new take should rise, fall, and pause like the first one.','It preserves the expressive shape and timing of a performance across re-recording, dubbing, or voice conversion, so meaning and emotion carried by delivery survive.','An ADR or dubbing director guides a performer to match the original line''s intonation, stress, and pacing so the replacement reads as the same delivery.','Dialogue & ADR',ARRAY['Paralinguistic transfer','Phonetic paraphrasing','Phonetic synchronization loss','ADR (Automated Dialogue Replacement)','Perspective riding']::text[],ARRAY['Matching the words and their timing but not the intonation, so the replacement sounds flat or differently emphasized.','Confusing prosody (intonation, stress, rhythm) with paralanguage broadly, or with the individual speech sounds themselves.','Forcing an exact prosodic copy in a dub so it fights the natural stress pattern of the target language.']::text[],ARRAY['Coaching an ADR performance to match the guide track''s intonation and pacing.','Directing a dub so the new language keeps the original''s emphasis and rhythm.','Evaluating a voice-conversion result for whether it preserved the original delivery.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4b983140-3ce5-5692-b449-75400b96b23f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prosody transfer'),'[^a-z0-9]','','g'));
