WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4b983140-3ce5-5692-b449-75400b96b23f' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2818e333-514e-51bd-ae4c-d2ff0455b626','Reamped dialogue','Reamped dialogue is a recorded dialogue signal played back through a loudspeaker into a physical acoustic space and re-recorded with a microphone, so the room''s reverberation, coloration, and character are captured onto the voice. In film post it is a form of "worldizing," used to place clean studio or ADR dialogue convincingly inside a real-sounding environment rather than relying solely on artificial reverb.','Reamped dialogue means playing a recorded voice out of a speaker in a real room. A microphone records it again. The room''s echo and tone stick to the voice. This helps clean studio lines sound like they belong in a real place. Sound editors call this "worldizing."','It imprints the real acoustic signature of an actual space onto dry dialogue, giving a natural, believable sense of place that digital reverb can struggle to match. It exists because audiences accept location sound more readily when the ambience was captured acoustically rather than synthesized.','A re-recording mixer or sound editor plays clean ADR through a speaker in a hallway, car, or stairwell and records it with a mic to match the on-screen location''s sound before folding it into the dialogue stem.','Dialogue Post',ARRAY['Worldizing','Room-print convolution','ADR','Room tone','Convolution reverb','Dialogue stem']::text[],ARRAY['Reamping through a low-quality speaker or microphone that adds distortion or noise, degrading the dialogue instead of only adding space.','Recording the reamp in a room whose acoustics do not match the on-screen location, so the voice sounds placed in the wrong space.','UNSAFE: driving the playback loudspeaker to high sound pressure levels for long worldizing sessions without limiting exposure time; sustained levels at or above OSHA''s 85 dBA action level (1910.95) risk permanent hearing damage.']::text[],ARRAY['Placing dry ADR into a tiled bathroom by reamping it through a speaker in a real tiled room.','Worldizing a radio or television voice by replaying it through a small speaker and re-recording it.','Matching a boom-mic location take by reamping studio dialogue in a similarly reverberant space.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2818e333-514e-51bd-ae4c-d2ff0455b626' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reamped dialogue'),'[^a-z0-9]','','g'));
