INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '341621ce-a6bc-583d-88cc-f6e146aafe85','Room fingerprint','A room fingerprint is the characteristic, repeatable spectral and noise signature of a specific recording space — the particular pattern of background noise, resonant peaks, and tonal coloration a microphone captures in that room. In dialogue post it is the reference profile that identifies a location''s sound, used to learn its steady-state noise for reduction or to match takes recorded in the same space.','Every room has its own background sound. It comes from air systems, hums, and the shape of the space. This steady pattern is the room''s fingerprint. Editors capture it to teach noise tools what to remove. They also use it to make different takes match.','It gives editors a stable reference of a room''s constant noise and tonal color so they can remove or match it, keeping dialogue from the same location consistent. It exists because location sound always carries an unavoidable, space-specific background that must be managed to sound seamless.','An editor captures a few seconds of a room''s fingerprint (its noise profile) so a spectral noise-reduction tool can learn and subtract that background, or so a later ADR line can be tuned to match the original location.','Dialogue Post',ARRAY['Room tone','Noise print','Room-tone continuity','Spectral de-noising','Dialogue editing','Room-print convolution']::text[],ARRAY['Confusing the room fingerprint with room tone: the fingerprint is the identifying noise and spectral signature, while room tone is the recorded ambience clip used to fill gaps.','Capturing the fingerprint with different mic placement or gain than the dialogue, so the profile no longer matches the material being cleaned.','Subtracting the learned fingerprint too aggressively, which pumps the noise floor or adds watery artifacts to the dialogue.']::text[],ARRAY['Learning a noise-reduction profile from a quiet section of a location recording.','Matching a re-recorded ADR line to the noise character of the original set.','Identifying which takes came from the same room by their shared background signature.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='341621ce-a6bc-583d-88cc-f6e146aafe85' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Room fingerprint'),'[^a-z0-9]','','g'));
