INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '95b4309f-4b2c-5a50-8659-03771a83f9fe','Room-print convolution','Room-print convolution is the process of applying a captured impulse response of a real space (its "room print") to a dry signal by mathematical convolution, so the target audio inherits that room''s reverberation, reflections, and frequency coloration. It is convolution reverb using a specific room''s measured acoustic signature rather than a synthetic algorithm.','You can capture how a room echoes by recording a test sound in it. That captured echo pattern is the room print. Convolution is math that stamps that echo onto a dry voice. The voice then sounds like it was recorded in that room. It is a very realistic kind of digital reverb.','It lets a mixer place dry dialogue into the exact acoustic of a real, measured space without physically re-recording there, giving highly realistic, location-specific reverberation. It exists because a measured impulse response reproduces a room''s behavior more faithfully than parametric reverb.','A re-recording mixer loads a room''s impulse response into a convolution reverb and processes ADR through it, so the replaced line matches the reverberation of the original on-set location.','Dialogue Post',ARRAY['Convolution reverb','Impulse response','Reamped dialogue','Worldizing','Room fingerprint','Reverberation']::text[],ARRAY['Assuming a single impulse response captures a room fully; it represents one source-and-mic geometry and may not match a different perspective.','Applying a fully wet convolution output instead of blending, which drowns the dialogue in reverb and hurts intelligibility.','Using an impulse response captured in an unrelated space or with mismatched gear, so the reverb tail does not fit the scene.']::text[],ARRAY['Matching ADR reverb to a cathedral by convolving it with an impulse response captured there.','Rebuilding the acoustic of a struck set from a stored impulse response.','Blending convolved room sound under production dialogue to smooth a cut between takes.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='95b4309f-4b2c-5a50-8659-03771a83f9fe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Room-print convolution'),'[^a-z0-9]','','g'));
