INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ae1a17d7-ad0b-5e0c-bcbb-abaa420c67e5','Room-tone continuity','Room-tone continuity is the practice of maintaining a consistent background ambience (room tone, or presence) throughout a scene so that edits, gaps between lines, and transitions between takes or between production sound and ADR do not produce audible jumps in the noise floor. It uses recorded room tone laid under and between dialogue to keep the space''s sound seamless across cuts.','Every location has a quiet background hum, called room tone. When lines are cut together, that background must not jump. Room-tone continuity keeps it smooth and steady. Editors fill the gaps with matching room tone. Then the scene sounds like one unbroken space.','It preserves the illusion of a single continuous acoustic space across edited dialogue, preventing the dead silences or level jumps that would reveal the cuts. It exists because dialogue editing removes and rearranges audio, breaking the natural continuity of location background.','A dialogue editor lays a bed of matching room tone under a scene and patches every gap and edit point so the background stays constant when lines from different takes are joined.','Dialogue Post',ARRAY['Room tone','Room fingerprint','Dialogue editing','Presence','ADR','Fill']::text[],ARRAY['Leaving true digital silence in gaps instead of room tone, so the background drops out and the cut becomes obvious.','Using room tone from a different location or take, whose noise floor or color does not match the scene.','Failing to record enough room tone on set, forcing editors to loop a short clip that becomes audibly repetitive.']::text[],ARRAY['Filling pauses between lines with matching room tone so the scene never goes dead.','Smoothing a cut between two takes that have different background levels.','Blending an ADR line into a location scene by matching its room tone.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ae1a17d7-ad0b-5e0c-bcbb-abaa420c67e5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Room-tone continuity'),'[^a-z0-9]','','g'));
