INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c17c8d6d-9fa2-5d59-aa53-46b4edf28a00','Shot-size perspective','Shot-size perspective is the convention of matching a sound''s audio perspective — its apparent distance, level, direct-to-reverberant ratio, and frequency balance — to the size and framing of the shot, so a close-up sounds close and intimate while a wide shot sounds more distant and roomy. It is the sound editor''s and mixer''s use of level, EQ, and reverberation to keep aural perspective consistent with visual perspective.','In a close-up, a voice should sound near and detailed. In a wide shot, it should sound farther away. Shot-size perspective matches the sound to how close the camera is. Mixers adjust volume, tone, and echo to do this. It keeps what we hear in step with what we see.','It aligns what the audience hears with what they see, reinforcing the sense of space and distance implied by the framing so the soundtrack feels natural. It exists because a mismatch between visual distance and audio perspective breaks believability.','A re-recording mixer keeps a close-up line dry and full, then adds a little distance, room, and reduced level when the same character is shown in a wide establishing shot.','Mix Perspective',ARRAY['Perspective','Reamped dialogue','Room-print convolution','Reverberation','Dialogue stem','Room tone']::text[],ARRAY['Keeping every line at the same close, dry perspective regardless of framing, which flattens the sense of space.','Overdoing perspective changes so dialogue level swings distractingly between shots and hurts intelligibility.','Confusing perspective (distance and space) with simple panning (left-right position), which are separate cues.']::text[],ARRAY['Pulling a character''s voice back and adding room as the cut moves from close-up to a wide shot.','Keeping an intimate, whispered line dry and forward in a tight close-up.','Matching off-screen dialogue perspective to a character''s implied distance from camera.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c17c8d6d-9fa2-5d59-aa53-46b4edf28a00' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Shot-size perspective'),'[^a-z0-9]','','g'));
