INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0f881427-6ff3-5e82-bc16-faef34379ca6','Sibilant spray','Sibilant spray is the harsh, splashy, air-like quality of over-emphasized sibilant consonants (chiefly /s/, /z/, and /ʃ/), in which strong high-frequency energy roughly in the 5–10 kHz region is perceived as a spitty, spraying burst on the voice. It is a common dialogue and vocal recording artifact caused by close miking, bright microphones, or exaggerated high-frequency response.','Some voices have very strong "ess" and "sh" sounds. When these are too loud, they splash out as a hissy, spitty burst. That harsh, airy effect is called sibilant spray. It sits high in the sound, around 5 to 10 kilohertz. Engineers tame it with de-essing.','Naming this artifact lets editors identify and target excess high-frequency sibilant energy so speech stays crisp without becoming harsh or fatiguing. Recognizing it guides choices in microphone selection, placement, and de-essing.','An engineer hearing sibilant spray reduces it with a de-esser targeting the offending 5–10 kHz band, changes the mic angle, or picks a less bright microphone.','Sibilance',ARRAY['Sibilance','Spectral de-essing','De-esser','Spitty voice','Sibilant whistling','Plosive']::text[],ARRAY['Treating all bright high end as sibilant spray and dulling the whole track, when only the sibilant bursts need control.','Fixing spray only with a static high-cut EQ, which darkens the entire voice instead of acting on the ess sounds.','UNSAFE: monitoring and soloing harsh sibilant bursts at high level for long stretches; prolonged loud high-frequency exposure contributes to hearing damage under OSHA 1910.95.']::text[],ARRAY['Taming spitty esses on a close-miked voiceover.','Reducing splashy sibilance on a bright lavalier dialogue track.','Choosing a smoother microphone to avoid spray on a naturally sibilant speaker.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0f881427-6ff3-5e82-bc16-faef34379ca6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sibilant spray'),'[^a-z0-9]','','g'));
