INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f8fa0023-327d-5040-90e2-d983d867bb24','Sibilant whistling','Sibilant whistling is a tonal, whistle-like resonance heard on sibilant consonants (especially /s/), in which the sibilant energy contains a narrow, pitched peak rather than broadband hiss. In speech it can arise from dental anatomy, dentures, or orthodontics, and in audio it can be introduced or exaggerated by resonant microphones, narrow EQ boosts, or artifacts of de-essing and low-bitrate codecs.','Normally an "ess" sound is a broad hiss. Sometimes it turns into a thin, pitched whistle instead. That is sibilant whistling. It can come from a speaker''s teeth or from gear and processing. It stands out and sounds unnatural, so engineers work to reduce it.','Identifying sibilant whistling lets editors tell a narrow tonal resonance apart from ordinary broadband sibilance, because the two need different fixes. Recognizing it prevents treating a pitched peak with tools meant for broadband hiss.','An engineer hearing a whistling ess uses a narrow notch or dynamic EQ tuned to the whistle''s frequency, rather than a broadband de-esser, and may re-record or edit the affected syllables.','Sibilance',ARRAY['Sibilance','Spectral de-essing','Sibilant spray','Dynamic EQ','Notch filter','De-esser']::text[],ARRAY['Using a broadband de-esser on a narrow whistle, which dulls the whole voice while barely touching the pitched tone.','Assuming whistling is always a recording fault, when it can originate in the talker''s own speech.','Pushing de-essing so hard that it adds its own artifacts, sometimes making the whistle worse.']::text[],ARRAY['Notching out a pitched whistle on a narrator''s ess sounds.','Diagnosing whistling introduced by a low-bitrate delivery codec.','Treating a denture-related whistle on an interview subject''s dialogue.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f8fa0023-327d-5040-90e2-d983d867bb24' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sibilant whistling'),'[^a-z0-9]','','g'));
