INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '513bcf9a-f9b7-5874-b6c9-98a4adf020ac','Source-filter theory','Source-filter theory is the acoustic model of speech production in which a sound source — the quasi-periodic pulses of the vibrating vocal folds for voiced sounds, or turbulent noise excitation for unvoiced sounds — is independently shaped by a linear filter, the vocal tract, whose resonances (formants) selectively amplify certain frequencies. The source spectrum and the tract''s transfer function are treated as separable, so vocal-fold vibration (pitch) and articulation (vowel and formant shape) are modeled independently.','Speech has two parts working together. The voice box makes a buzzing or hissing sound. That is the source. The throat, mouth, and lips reshape it like a filter. Their resonant peaks are called formants and they set the vowel. This source-and-filter idea explains how we make different speech sounds.','It provides the foundational framework for understanding, analyzing, and synthesizing speech by separating pitch (the source) from timbre and vowel identity (the filter). It underlies speech analysis, vocoders, formant synthesis, and pitch- and formant-editing tools.','A dialogue or voice editor relies on this separation when using tools that shift pitch without changing formants (or the reverse), keeping a voice natural while tuning delivery, gender, or character.','Speech Acoustics',ARRAY['Formant','Vocal tract','Fundamental frequency','Vocoder','Spectral de-essing','Speaker similarity']::text[],ARRAY['Assuming source and filter are fully independent in reality; the model is an idealization and the two interact somewhat in actual speech.','Confusing fundamental frequency (pitch, from the source) with formants (resonances, from the filter).','Thinking shifting pitch automatically shifts formants; good tools separate them, and ignoring this yields the ''chipmunk'' effect.']::text[],ARRAY['Explaining why pitch-shifting a voice without formant correction sounds unnatural.','Designing or using a vocoder that imposes speech formants onto another sound.','Analyzing formants to identify vowels in speech processing.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='513bcf9a-f9b7-5874-b6c9-98a4adf020ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Source-filter theory'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '513bcf9a-f9b7-5874-b6c9-98a4adf020ac','739bdba4-0fac-4455-9ee2-1a56096cab92',true
