INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c3495ef5-8b91-51f9-b70c-ee0e144c5407','Speaker similarity','Speaker similarity is the degree to which two speech signals are perceived or measured to originate from the same talker, based on voice-identity characteristics such as fundamental-frequency range, formant structure, and timbre rather than on the words spoken. It is used as an evaluation criterion in voice conversion, text-to-speech, and speaker verification, and as a practical goal when replacement or synthetic dialogue must match an original performer''s voice.','Speaker similarity means how much two recordings sound like the same person. It looks at the voice itself, not the words. A high result means the voices seem to share one identity. Engineers use it to check that a replaced or cloned voice matches the original actor. It can be judged by ear or measured by software.','It gives a way to judge whether a converted, synthesized, or replacement voice keeps the original speaker''s identity, which matters whenever dialogue must sound like the same performer. It exists because matching voice identity is a distinct goal from matching words or intelligibility.','A post team evaluating an AI voice double or a matched ADR performer checks speaker similarity — by ear and sometimes with speaker-embedding measures — to confirm the new voice reads as the same character.','Voice Identity',ARRAY['Speaker-preserving translation','Source-filter theory','ADR','Voice conversion','Formant','Timbre']::text[],ARRAY['Judging similarity from only a few words; short samples can mislead because voice identity varies with content and emotion.','Assuming high intelligibility means high speaker similarity; a clear voice can still sound like the wrong person.','Relying on a single automatic score without careful listening, since metrics do not fully capture perceived identity.']::text[],ARRAY['Checking that an AI-generated voice double matches the original actor.','Casting and evaluating an ADR voice-match performer.','Comparing voice-conversion outputs for how well they preserve a target speaker.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c3495ef5-8b91-51f9-b70c-ee0e144c5407' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Speaker similarity'),'[^a-z0-9]','','g'));
