INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9621cdbf-01a1-5ecf-9fdf-ccda2b9dd54a','Speaker-preserving translation','Speaker-preserving translation is speech-to-speech (or speech-to-speech via text) translation in which spoken content is translated from one language to another while retaining the original speaker''s vocal identity — timbre, and often prosody — so the translated speech still sounds like the same person. It combines translation with voice preservation, as opposed to replacing the speaker''s voice with a generic synthetic one.','This turns a person''s speech into another language. But it keeps their own voice. The translated words still sound like the same speaker. Newer AI dubbing systems can do this. It makes translated dialogue feel more personal and natural.','It lets translated or dubbed speech keep the source performer''s recognizable voice, improving continuity of character and personal identity across languages. It exists to avoid the mismatch of hearing a translated line in a completely different, generic voice.','A localization team uses a speaker-preserving translation system to produce foreign-language dialogue that keeps a presenter''s or actor''s original voice quality, reducing the need to cast a separate dubbing artist for timbre.','Voice Identity',ARRAY['Speaker similarity','Voice conversion','Dubbing','ADR','Source-filter theory','Text-to-speech']::text[],ARRAY['Assuming voice preservation also guarantees accurate lip-sync; matching timing and mouth shapes is a separate problem.','Expecting perfect emotional prosody; preserved timbre can still miss the original performance''s nuance.','Overlooking consent and rights issues in reusing a performer''s voice identity across languages.']::text[],ARRAY['Localizing a documentary so a narrator keeps their own voice in another language.','Dubbing a film while retaining the lead actor''s vocal timbre.','Translating a speech or interview while preserving the speaker''s recognizable voice.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9621cdbf-01a1-5ecf-9fdf-ccda2b9dd54a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Speaker-preserving translation'),'[^a-z0-9]','','g'));
