INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0c6513d4-481d-5990-a185-404c761119f5','Spectral de-essing','Spectral de-essing is a form of de-essing that attenuates sibilant energy selectively within the frequency spectrum — reducing gain only in the offending high-frequency bands (typically around 4–10 kHz) during sibilant events — rather than turning down the whole signal with a broadband compressor. Implemented with dynamic EQ, split-band, or spectral-processing tools, it lowers harsh /s/ and /ʃ/ content while leaving the rest of the voice untouched.','De-essing tames harsh "ess" sounds in a voice. Spectral de-essing only turns down the high frequencies where the hiss lives. The rest of the voice stays full and clear. It reacts just when a sibilant hits. This is gentler than lowering the whole sound.','It controls sibilance transparently by acting only on the narrow high-frequency range, and only when sibilants occur, preserving the voice''s body and brightness. It exists because broadband de-essing can dull or pump the whole voice when it clamps down on an ess.','An engineer sets a spectral or dynamic-EQ de-esser to detect sibilants and reduce gain in roughly the 5–8 kHz region on those moments, cleaning harsh esses without darkening the overall dialogue.','Sibilance',ARRAY['De-esser','Sibilance','Dynamic EQ','Spectral ducking','Sibilant spray','Multiband compression','Split-band de-essing','Wideband de-essing']::text[],ARRAY['Setting the threshold too low so the de-esser acts on non-sibilant sounds and lisps the voice.','Targeting too wide a band, which dulls consonant clarity along with the harsh sibilance.','UNSAFE: repeatedly soloing sibilant peaks at high monitor levels while tuning the de-esser; prolonged loud high-frequency listening risks hearing damage under OSHA 1910.95.']::text[],ARRAY['Cleaning harsh esses on a voiceover while keeping it bright.','De-essing dialogue with a dynamic EQ that only dips 6–8 kHz on sibilants.','Reducing sibilance introduced by heavy high-frequency boosting.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0c6513d4-481d-5990-a185-404c761119f5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral de-essing'),'[^a-z0-9]','','g'));
