INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '292c6abf-c7d5-5e25-a80b-b26924711260','Spectral ducking','Spectral ducking is frequency-selective sidechain ducking in which one signal reduces the level of another only in the specific frequency bands where they overlap, rather than ducking the full-band level. Implemented with dynamic EQ or multiband/spectral sidechain processing, it lets a trigger (such as dialogue) carve room for itself in a competing signal (such as music) only in the shared frequency regions, preserving the rest of that signal.','Ducking lowers one sound when another plays, like music dipping under speech. Spectral ducking only dips the frequencies that clash. The parts that do not overlap stay at full level. So music keeps its low end and air while making room for the voice. It is a cleaner, more surgical kind of ducking.','It resolves frequency masking between competing signals by lowering only the conflicting bands, keeping dialogue clear while the music keeps more of its fullness than broadband ducking allows. It exists because full-band ducking can pump and audibly dip a whole element when only part of its spectrum masks the voice.','A mixer sidechains music to dialogue with a dynamic EQ so the music dips only in the vocal midrange when someone speaks, then returns to full level in the gaps.','Mix Processing',ARRAY['Ducking','Sidechain compression','Dynamic EQ','Frequency masking','Spectral de-essing','Multiband compression']::text[],ARRAY['Using broadband ducking where spectral ducking is needed, which audibly pumps the whole music bed.','Setting the reacting bands too wide, so more of the music dips than necessary.','Ducking too deeply or too slowly, causing obvious level changes instead of transparent space for the voice.']::text[],ARRAY['Making music give way to narration only in the vocal frequencies.','Cleaning up masking between a bass-heavy synth and a kick drum in the shared low band.','Keeping a podcast''s music bed full while ducking just the midrange under speech.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='292c6abf-c7d5-5e25-a80b-b26924711260' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral ducking'),'[^a-z0-9]','','g'));
