INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '073c2500-b40c-5a8b-9eea-e8fff5d22e23','Spitty voice','"Spitty voice" is an informal engineering description of a vocal recording marred by audible mouth noises — saliva clicks, lip smacks, and tongue- and plosive-driven bursts of air — that read as small wet or crackly sounds between and during words. It typically results from close miking, a dry mouth or dehydration, and the absence of a pop filter, and is treated in dialogue post as an intelligibility and cleanliness problem.','A spitty voice is a recording full of little mouth sounds. You hear clicks, lip smacks, and puffs of air. These come from saliva and close mic work. They make speech sound wet and messy. Engineers reduce them with mic technique, pop filters, and editing.','The label flags a specific class of mouth-noise artifacts so editors know to reduce them for clean, professional dialogue. It matters because these small wet sounds distract listeners and undermine intelligibility.','An editor cleans a spitty voice with de-click and mouth-de-noise tools and manual editing of saliva clicks, and advises better mic distance, a pop filter, and hydration at the source.','Voice Artifact',ARRAY['Mouth noise','Plosive','De-click','Pop filter','Sibilant spray','Dialogue editing']::text[],ARRAY['Trying to remove every mouth click with heavy processing, which can leave gaps or artifacts in the dialogue.','Blaming the microphone alone when hydration and mic distance at the source are the real fix.','UNSAFE: soloing and boosting faint mouth noises at high monitor levels for long periods while editing; sustained loud listening risks hearing damage under OSHA 1910.95.']::text[],ARRAY['Cleaning saliva clicks from a close-miked voiceover.','Reducing lip smacks on an audiobook or ADR performance.','Advising talent to drink water and back off the mic to cut mouth noise.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='073c2500-b40c-5a8b-9eea-e8fff5d22e23' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spitty voice'),'[^a-z0-9]','','g'));
