INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '986b2105-304f-5dc0-b8e5-bc3d4d929095','Split-band de-essing','A de-essing technique in which the signal is divided into frequency bands and gain reduction is applied only within the band containing sibilant energy (typically the upper-mid to high frequencies, roughly 5-10 kHz), leaving the rest of the spectrum unattenuated. It contrasts with wideband (broadband) de-essing, which reduces the level of the whole signal whenever sibilance is detected.','The letter ''s'' can sound harsh and piercing on a recording. A de-esser turns those harsh sounds down. Split-band de-essing lowers only the high ''s'' range. The rest of the voice stays at full volume. This tames the hiss while the voice still sounds natural.','It removes harsh sibilance from vocals or dialogue while preserving the body of the voice, because only the offending high-frequency band is attenuated rather than the entire signal.','A re-recording or vocal mixer inserts a split-band de-esser on a dialogue or vocal track, tunes the detection band to the sibilant region, and sets a threshold so only loud ''s'' and ''sh'' sounds are reduced.','Dialogue Processing',ARRAY['Sibilance','De-esser','Multiband compression','Dialogue editing','Timbre preservation','Vocal harmonics']::text[],ARRAY['Setting the detection band too low or too wide, which dulls the voice by pulling down non-sibilant frequencies along with the ''s'' sounds.','Applying heavy de-essing to mask a harsh microphone or room instead of fixing the recording source, producing an unnatural lisping quality.','Confusing split-band de-essing with wideband de-essing and expecting the whole signal to duck on every sibilant.','UNSAFE: Cranking the monitors up to hear subtle sibilance for long stretches; sustained exposure above about 85 dBA can damage hearing, so audition at the calibrated reference level and take breaks.']::text[],ARRAY['Cleaning up harsh ''s'' sounds on a lavalier-recorded actor before the final dialogue mix.','Taming sibilance on a bright voice-over without dulling its high-frequency clarity.','Preparing a dialogue stem so sibilance stays controlled after final loudness normalization.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='986b2105-304f-5dc0-b8e5-bc3d4d929095' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Split-band de-essing'),'[^a-z0-9]','','g'));
