SELECT '986b2105-304f-5dc0-b8e5-bc3d4d929095','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='986b2105-304f-5dc0-b8e5-bc3d4d929095' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a68b42bb-3099-5eb0-b892-fc3f45f35e41','Syllabic riding','The practice of manually riding (continuously adjusting) the gain or fader of a dialogue or vocal track at the level of individual syllables, lifting quieter syllables and restraining louder ones to even out perceived level and maintain intelligibility. It is a fine-grained form of manual gain riding done by ear, often alongside or ahead of automatic compression.','When people speak, some syllables are loud and some are quiet. A mixer can move the volume fader up and down as the words go by. Syllabic riding means making these tiny moves for each syllable. It lifts weak syllables so every word can be heard. It smooths the speech without squashing it like a compressor.','It keeps every word clear and at a consistent level despite the natural loud-soft swing of speech, giving smoother, more intelligible dialogue than compression alone while preserving natural dynamics.','A re-recording mixer writes fader automation or rides the fader in real time on a dialogue track, nudging low syllables up and peaks down so lines sit evenly against music and effects.','Dialogue Mixing',ARRAY['Gain riding','Vocal dynamic range','Dialogue editing','Automation','Compression','Fader']::text[],ARRAY['Relying only on a compressor and skipping manual riding, so weak syllables still drop below the music and effects.','Over-riding until all natural dynamic variation is gone, making the dialogue sound flat and unnatural.','Riding by watching the meters instead of listening, which corrects levels that measure high but already sound fine.','UNSAFE: Raising the monitor level far above the calibrated reference to catch quiet syllables; prolonged exposure above about 85 dBA risks hearing loss, so ride at reference level and rest your ears.']::text[],ARRAY['Evening out an actor''s mumbled line so it stays intelligible under a music cue.','Preparing a dialogue premix where compression alone leaves some syllables buried.','Balancing a whispered and a shouted line in the same scene for consistent loudness.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a68b42bb-3099-5eb0-b892-fc3f45f35e41' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Syllabic riding'),'[^a-z0-9]','','g'));
