INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a5848ac7-1f3f-526f-9bef-9aeb643e7793','Sync-naturalness tradeoff','In dubbing and audiovisual translation, the compromise between meeting on-screen synchrony constraints (isochrony and lip/phonetic synchrony) and keeping the translated dialogue sounding natural and idiomatic. Tightening synchronization to match mouth movements and line length often forces less natural wording, while prioritizing natural phrasing can loosen the visible sync.','In dubbing, the new voice must match the actor''s mouth on screen. It also must sound like normal speech. These two goals often fight each other. Matching the lips can force odd word choices. Sounding natural can break the lip match. Dubbing teams balance the two.','It names the core creative constraint of dubbing, guiding writers and mixers on when to favor a tight lip match and when to favor a believable, natural-sounding line.','A dubbing dialogue writer reworks a translated line so its stressed syllables land on the actor''s mouth movements, accepting slightly freer wording to keep the delivery natural.','Dubbing & Localization',ARRAY['Isochrony','Lip synchrony','Synchronization-aware translation','Translation-naturalness tradeoff','Viseme-aware translation','ADR']::text[],ARRAY['Forcing a word-for-word literal translation into the mouth movements, producing stilted, unnatural dialogue.','Chasing a perfect lip match on wide or off-screen shots where the audience cannot see the mouth anyway.','Treating synchrony and naturalness as one problem instead of a balance that shifts shot by shot.']::text[],ARRAY['Adapting a translated feature so close-up lines match the actor''s lips without sounding wooden.','Deciding to relax lip-sync on an off-screen line to keep the phrasing natural.','Briefing voice actors on where sync matters most in a scene.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a5848ac7-1f3f-526f-9bef-9aeb643e7793' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync-naturalness tradeoff'),'[^a-z0-9]','','g'));
