INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b5442838-35b6-5d00-9f4e-6426f7394484','Synchronization-aware translation','An approach to translating audiovisual dialogue in which the target-language text is shaped to respect synchronization constraints, matching the source line''s duration (isochrony), pause structure, and where possible the visible articulation, rather than translating for meaning alone. In automatic dubbing it is implemented by length- or timing-constrained machine translation, such as isometric translation and prosodic alignment.','A normal translation only cares about meaning. In dubbing, the words must also fit the time the actor''s mouth moves. Synchronization-aware translation picks wording that fits that timing. The line is made to start, pause, and end like the original. This helps the dub match the picture.','It produces translations that can be spoken in sync with the picture, reducing the rewriting needed later and improving lip and timing match in dubbed content.','A localization team or an automatic-dubbing system generates target lines constrained to the source line''s length and timing, so the dub fits each shot with minimal manual adaptation.','Dubbing & Localization',ARRAY['Isochrony','Sync-naturalness tradeoff','Viseme-aware translation','Lip synchrony','Translation-naturalness tradeoff','Dubbing']::text[],ARRAY['Assuming matching syllable counts guarantees good sync, ignoring stress placement and pauses.','Optimizing only for timing and losing the meaning or tone of the original line.','Skipping human review of machine-generated synced translations, which can produce awkward or wrong wording.']::text[],ARRAY['Generating first-pass dubbing scripts that already fit each line''s on-screen duration.','Localizing a streaming series into many languages under tight timing constraints.','Feeding timing-constrained translations to voice actors to speed up the dubbing session.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b5442838-35b6-5d00-9f4e-6426f7394484' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Synchronization-aware translation'),'[^a-z0-9]','','g'));
