INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '344f2e6b-6939-57e5-8ed3-778c3509fe0f','Throat resonance','The acoustic resonance of the pharyngeal and laryngeal cavities of the vocal tract, which shapes the voice''s timbre by reinforcing certain frequency regions (formants) in the sound produced at the glottis. It is one component of the vocal-tract filtering described by the source-filter model of voice production.','The voice starts as a buzz at the vocal cords. That buzz then travels up through the throat and mouth. The throat acts like a tube that boosts some pitches. This shaping is throat resonance. It helps give each person their own tone of voice.','It explains part of how the vocal tract colors the raw glottal sound into a full, characteristic voice, and why changes in throat shape (tension or openness) alter vocal tone.','A dialogue or vocal mixer recognizes throat resonance when using equalization to add warmth or to reduce a boxy, constricted quality in a recorded voice.','Voice Acoustics',ARRAY['Formant','Vocal harmonics','Source-filter model','Timbre preservation','Resonance','Equalization']::text[],ARRAY['Confusing throat (pharyngeal) resonance with ''chest resonance,'' which is a felt vibration, not the main acoustic filter of the voice.','Assuming equalization changes the throat resonance itself, when it only reshapes the recorded result.','Thinking resonance adds brand-new frequencies, when it reinforces frequencies already present in the glottal source.']::text[],ARRAY['Using EQ to open up a constricted, throaty-sounding dialogue recording.','Diagnosing why two actors with similar pitch have very different vocal tone.','Matching ADR timbre to production dialogue by adjusting resonant regions.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='344f2e6b-6939-57e5-8ed3-778c3509fe0f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Throat resonance'),'[^a-z0-9]','','g'));
