SELECT '344f2e6b-6939-57e5-8ed3-778c3509fe0f','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='344f2e6b-6939-57e5-8ed3-778c3509fe0f' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2f6d16f6-50da-53a4-941d-32dab7900142','Timbre preservation','The goal, during processing or transformation of a signal, of maintaining the original tone color (spectral balance and harmonic character) of a voice or instrument so that changes in dynamics, pitch, level, or format do not audibly alter its identity. It is a design and operating criterion for tools such as compressors, pitch and time processors, de-essers, and codecs.','Every voice or instrument has its own tone color, called timbre. Processing like pitch shifting or heavy compression can change that color. Timbre preservation means keeping the original tone intact. The sound gets adjusted, but it still sounds like itself. This keeps voices recognizable and natural.','It ensures that necessary processing, such as leveling, pitch or time correction, or noise reduction, does not make a voice or instrument sound artificial, protecting the natural character the audience expects.','An engineer chooses gentler settings or formant-preserving pitch tools so correcting a vocal''s pitch or level does not give it a chipmunk-like or lifeless, over-processed tone.','Dialogue Processing',ARRAY['Timbre','Formant','Vocal harmonics','Pitch correction','Split-band de-essing','Throat resonance']::text[],ARRAY['Applying large pitch shifts without formant correction, which distorts the timbre and creates an unnatural voice.','Over-compressing or over-de-essing until the natural tone color is dulled or hollowed out.','Assuming louder or ''cleaner'' automatically means better, and sacrificing the original character in the process.']::text[],ARRAY['Pitch-correcting a line reading while keeping the actor''s natural vocal character.','Choosing a codec or noise-reduction setting that does not smear a singer''s tone.','Matching processed ADR to the timbre of the original production sound.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2f6d16f6-50da-53a4-941d-32dab7900142' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timbre preservation'),'[^a-z0-9]','','g'));
