WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2f6d16f6-50da-53a4-941d-32dab7900142' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4c6c2b0c-21a7-50b8-bfc9-eaa8b09d99b8','Translation-naturalness tradeoff','In translation and localization, the tension between fidelity to the exact meaning and form of the source text and the fluency or idiomatic naturalness of the target-language output. Maximizing literal accuracy can yield stilted phrasing, while maximizing naturalness may loosen strict correspondence to the source.','A translation can be very exact or very natural. An exact, word-for-word version can sound clumsy. A smooth, natural version may drift from the exact words. These two goals pull against each other. Translators pick a balance for each line.','It frames a central decision in translation and dubbing, helping writers judge when to stay literal for accuracy and when to adapt for a natural, believable target line.','A dubbing or subtitle writer rephrases a literal translation into idiomatic target-language dialogue, accepting small shifts in wording to make the line sound like real speech.','Dubbing & Localization',ARRAY['Sync-naturalness tradeoff','Synchronization-aware translation','Localization','Subtitling','Viseme-aware translation','Dubbing']::text[],ARRAY['Translating word for word and producing dialogue no native speaker would actually say.','Adapting so freely for naturalness that the meaning or intent of the original is lost.','Ignoring that the right balance depends on genre, register, and audience.']::text[],ARRAY['Localizing an idiom or joke that has no direct equivalent in the target language.','Deciding how literal to keep a legally or plot-critical line in a dub.','Reworking a subtitle so it reads naturally within its character limit.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4c6c2b0c-21a7-50b8-bfc9-eaa8b09d99b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Translation-naturalness tradeoff'),'[^a-z0-9]','','g'));
