INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '82f065fc-dc01-55e1-a5d2-33fec9e2ceea','Viseme-aware translation','A form of synchronization-aware audiovisual translation in which target-language wording is chosen so that its visemes, the visually distinct mouth shapes of speech sounds (especially the bilabial closures for /p/, /b/, and /m/), align with the actor''s visible articulation on screen. It targets phonetic or lip synchrony at the level of what the viewer can actually see rather than exact phoneme matching.','A viseme is the shape your mouth makes for a sound. Some sounds look the same on the lips. Viseme-aware translation picks words whose mouth shapes match the actor on screen. It focuses on clearly visible shapes, like closed lips for ''b'' or ''m''. This makes the dub look better synced.','It improves visible lip-sync in dubbing by matching mouth shapes at moments the audience can see clearly, rather than spending effort on sounds that look alike or happen off screen.','A dubbing writer or automatic-dubbing tool selects target words that place a closed-lip sound where the on-screen actor closes their lips, tightening the apparent lip match.','Dubbing & Localization',ARRAY['Viseme','Lip synchrony','Synchronization-aware translation','Sync-naturalness tradeoff','Isochrony','Dubbing']::text[],ARRAY['Trying to match every phoneme instead of just the visually distinct mouth shapes, which is unnecessary and over-constraining.','Ignoring that many different sounds share the same viseme, so exact phonetic matching is not required.','Applying viseme matching to shots where the mouth is not visible, wasting adaptation effort.']::text[],ARRAY['Adapting a close-up line so a lip closure lands where the actor''s lips close.','Improving apparent lip-sync in a high-value dubbed feature.','Guiding an automatic-dubbing system to favor viseme matches on visible articulation.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='82f065fc-dc01-55e1-a5d2-33fec9e2ceea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Viseme-aware translation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '82f065fc-dc01-55e1-a5d2-33fec9e2ceea','739bdba4-0fac-4455-9ee2-1a56096cab92',true
