INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '96038125-91f1-5e75-ac06-138f7793f03d','Vocal density','An informal descriptor for the perceived thickness or fullness of a vocal or dialogue element in a mix, arising from factors such as the number of layered voices, harmonic and spectral content, dynamic-range control, and reverberation. Higher vocal density reads as a fuller, more continuous vocal texture; lower density as sparser and more transparent.','Vocal density is how thick or full the voices sound in a mix. Many stacked voices sound dense. A single dry voice sounds thin and open. Compression and reverb can also add thickness. Mixers adjust density so voices sit right in the scene.','It gives mixers a way to describe and manage how full or sparse the vocal texture should feel, so voices carry the right weight without crowding the rest of the mix.','A mixer adds layering, compression, or reverb to thicken a lead vocal, or strips them back to keep sparse dialogue clear and intimate.','Dialogue Mixing',ARRAY['Vocal dynamic range','Timbre preservation','Reverberation','Compression','Layering','Vocal harmonics']::text[],ARRAY['Adding layers or reverb for density until the lead voice loses clarity and intelligibility.','Confusing loudness with density; a loud voice can still sound thin, and a quiet one full.','Piling on processing to build density instead of capturing a fuller performance at the source.']::text[],ARRAY['Thickening a lead vocal in a music mix with doubles and harmonies.','Keeping intimate dialogue sparse so it feels close and clear.','Balancing a dense crowd-walla bed against featured dialogue.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='96038125-91f1-5e75-ac06-138f7793f03d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal density'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '96038125-91f1-5e75-ac06-138f7793f03d','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='96038125-91f1-5e75-ac06-138f7793f03d' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3c22b0ae-f0c4-5f27-bf5a-954f3f9939c0','Vocal dynamic range','The span between the quietest and loudest levels a voice produces, from soft or whispered passages to shouted or belted peaks, typically expressed in decibels. In production it also refers to that range as captured and managed on a recorded vocal or dialogue track before and after level processing.','A voice can go from a soft whisper to a loud shout. Vocal dynamic range is the gap between the quietest and loudest parts. A big gap sounds expressive but is hard to mix. A small gap is even but can feel flat. Mixers manage this gap so every word is heard.','It describes how much a voice''s level varies, which drives choices about microphone gain, compression, and fader riding to keep the voice both natural and consistently audible.','An engineer sets gain and compression to fit a singer''s or actor''s dynamic range within the recording and mix headroom, taming shouts and lifting whispers.','Dialogue Mixing',ARRAY['Dynamic range','Syllabic riding','Compression','Headroom','Vocal density','Gain staging']::text[],ARRAY['Setting record gain for the quiet passages and then clipping when the performer suddenly shouts.','Compressing so hard that all dynamic expression is removed, leaving a lifeless, flat vocal.','Assuming a compressor alone can handle a very wide range without any manual riding.','UNSAFE: Turning the monitors up to hear quiet passages and leaving them loud through the shouts; sustained levels above about 85 dBA can harm hearing, so mix at the calibrated reference level.']::text[],ARRAY['Recording a scene that swings from whispers to screaming without clipping.','Fitting a dynamic vocal performance under a busy music bed.','Setting compression on dialogue so quiet and loud lines both stay intelligible.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3c22b0ae-f0c4-5f27-bf5a-954f3f9939c0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal dynamic range'),'[^a-z0-9]','','g'));
