SELECT '3c22b0ae-f0c4-5f27-bf5a-954f3f9939c0','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3c22b0ae-f0c4-5f27-bf5a-954f3f9939c0' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '994759cf-44a0-5c68-b5a9-de8236512e91','Vocal fry','The lowest vocal register, produced when the vocal folds are short, slack, and loosely closed so that air escapes in slow, irregular glottal pulses, giving a low-pitched creaky, popping, or rattling quality. Also called the pulse or glottal-fry register, it lies below the modal (normal speaking) register.','Vocal fry is a low, creaky, crackly way of speaking. It happens when the vocal cords are loose and floppy. Air bubbles through them slowly and unevenly. This makes a rattling, popping sound at a very low pitch. You often hear it at the end of a tired sentence.','As a named vocal register, it lets voice professionals and engineers identify and describe a distinct creaky mode of phonation that behaves differently from normal (modal) speech in pitch, level, and texture.','A dialogue editor or mixer recognizes vocal fry as low, irregular creak that can be hard to level or de-noise, and edits or gently processes it rather than fighting it as a fault.','Voice Acoustics',ARRAY['Modal register','Vocal folds','Glottal pulse','Vocal harmonics','Vocal dynamic range','Timbre preservation']::text[],ARRAY['Mistaking vocal fry for a technical fault or recording problem rather than a natural vocal register.','Trying to gate or compress away creaky fry and instead chopping the ends off words.','Assuming fry has a clear, steady pitch, when its glottal pulses are slow and irregular.']::text[],ARRAY['Editing creaky sentence endings in a narration or podcast.','Leveling dialogue where an actor drops into fry on quiet lines.','Identifying fry when diagnosing an uneven or crackly vocal take.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='994759cf-44a0-5c68-b5a9-de8236512e91' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal fry'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '994759cf-44a0-5c68-b5a9-de8236512e91','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='994759cf-44a0-5c68-b5a9-de8236512e91' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '17e0d417-89a1-528b-9b9a-a6727e301e7c','Vocal harmonics','The series of frequency components in a voiced sound occurring at integer multiples of the fundamental (glottal) frequency, generated by the periodic vibration of the vocal folds. Their relative amplitudes, as shaped by vocal-tract resonances (formants), determine the voice''s timbre.','When the vocal cords buzz, they make a lowest pitch called the fundamental. They also make higher tones stacked above it at whole-number multiples. These extra tones are the vocal harmonics. The mix of them gives a voice its tone. The throat and mouth then boost some of them.','Harmonics are what make a voice rich and give it its characteristic tone; understanding them explains how equalization and resonance shape vocal color.','An engineer boosts or cuts harmonic regions with equalization to add presence or warmth, or to reduce harshness, on a recorded voice.','Voice Acoustics',ARRAY['Fundamental frequency','Formant','Timbre','Throat resonance','Overtone','Equalization']::text[],ARRAY['Confusing harmonics (integer multiples of the fundamental) with formants (vocal-tract resonance peaks).','Believing equalization creates harmonics, when it only reshapes harmonics the voice already produces.','Assuming a higher fundamental means fewer harmonics matter, and neglecting the upper vocal spectrum.']::text[],ARRAY['Using EQ to add presence to a dull voice by lifting upper harmonic regions.','Reducing harshness by taming a specific harmonic band.','Explaining why two voices at the same pitch sound different.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='17e0d417-89a1-528b-9b9a-a6727e301e7c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal harmonics'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '17e0d417-89a1-528b-9b9a-a6727e301e7c','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='17e0d417-89a1-528b-9b9a-a6727e301e7c' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '530b559c-9a78-5644-a4d9-1a664ec02970','Vocal proximity effect','The rise in low-frequency response that occurs when a directional (pressure-gradient) microphone is placed close to a sound source such as a singer or speaker, reinforcing bass frequencies as the mic-to-source distance decreases. It results from the pressure-gradient operating principle of directional microphones and does not occur with omnidirectional pressure microphones.','Get close to a directional microphone and the bass gets stronger. This bass boost is the proximity effect. Radio voices sound deep and warm because of it. Move away and the boost fades. Singers use it on purpose, but it can also make a voice boomy.','It lets performers and engineers add warmth and body to a voice by working the mic close, but it must be managed to avoid a muddy, bass-heavy sound.','A vocalist works close to a cardioid mic for a fuller tone, while the engineer uses a high-pass filter or EQ to control the excess low end from the proximity effect.','Microphone Technique',ARRAY['Directional microphone','Cardioid','Pressure-gradient microphone','High-pass filter','Omnidirectional microphone','Bass rolloff']::text[],ARRAY['Expecting proximity effect from an omnidirectional mic, which does not exhibit it.','Letting a close-worked voice turn boomy instead of applying a high-pass filter or backing off slightly.','Confusing proximity bass boost with a microphone fault or a room resonance.']::text[],ARRAY['A voice-over artist working close to a cardioid mic for a warm, intimate tone.','Controlling boominess when an actor leans into a directional mic.','Choosing an omnidirectional lav to avoid proximity buildup when a mic sits close to the chest.']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='530b559c-9a78-5644-a4d9-1a664ec02970' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal proximity effect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '530b559c-9a78-5644-a4d9-1a664ec02970','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='530b559c-9a78-5644-a4d9-1a664ec02970' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '679a80fb-3d3e-52e9-8a26-9f7655426cc6','Vocal-fold vibration','The oscillation of the vocal folds within the larynx, driven by the myoelastic-aerodynamic interaction of subglottal airflow with the folds'' tissue elasticity, which chops the airstream into a periodic train of pulses that forms the voiced glottal sound source. The rate of this vibration sets the fundamental frequency, heard as vocal pitch.','The vocal folds are two small flaps in the voice box. Breath from the lungs makes them open and close very fast. This chopping of the air makes the buzz of your voice. How fast they move sets the pitch.','It generates the raw voiced sound source that the vocal tract then shapes into speech, and its rate determines vocal pitch. It is the primary mechanism of phonation for all voiced sounds.','A dialogue editor hears vocal-fold vibration as the pitched, periodic core of a voice; recognizing it helps separate voiced speech from unvoiced, breathy, or noisy portions when cutting and processing lines.','Voice production',ARRAY['Fundamental frequency','Voiced versus unvoiced speech','Vocal-tract resonances','Voice onset','Vowel formation','Phonation']::text[],ARRAY['Confusing the vibration rate (fundamental frequency, or pitch) with the vocal-tract formants that shape timbre','Assuming all speech is voiced, when sounds like /s/, /f/, and /t/ have no vocal-fold vibration','Thinking louder speech simply means faster vibration, when loudness and pitch are controlled separately']::text[],ARRAY['Explaining why a pitch-correction tool tracks only the periodic voiced portions of a line','Identifying the voiced core of a word when editing around breaths and sibilants','Diagnosing why a strained or creaky voice reads differently in a dialogue recording']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='679a80fb-3d3e-52e9-8a26-9f7655426cc6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal-fold vibration'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '679a80fb-3d3e-52e9-8a26-9f7655426cc6','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='679a80fb-3d3e-52e9-8a26-9f7655426cc6' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ffcfd89a-5e03-564c-b138-c787d8d77f20','Vocal-tract resonances','The natural resonant frequencies of the air column of the vocal tract above the larynx, which act as an acoustic filter that reinforces certain frequencies of the glottal source. These resonances are called formants, and the pattern of the lowest two or three defines the identity and timbre of vowels and voiced sounds; this is the filter side of the source-filter theory of speech production.','Above the voice box, the throat and mouth form a tube of air. That tube boosts some frequencies in the voice, like blowing across a bottle. These boosted peaks are called formants. Their pattern makes an "ee" sound different from an "ah".','They shape the flat buzz of the vocal folds into recognizable vowels and give each voice its characteristic tone. They exist because any air cavity resonates, and the changing tract shape tunes those resonances.','When an editor or mixer equalizes dialogue, they are adjusting energy around these formant regions; understanding them helps target intelligibility and presence without making a voice thin or boxy.','Speech acoustics',ARRAY['Formant','Vowel formation','Vocal-fold vibration','Source-filter theory','Equalization','Timbre']::text[],ARRAY['Confusing formants (resonances set by tract shape) with the fundamental frequency (pitch), which moves independently','Cutting broad EQ across formant regions and dulling intelligibility','Assuming formants shift with pitch, when they are set by tract shape rather than vibration rate']::text[],ARRAY['Choosing EQ bands to lift dialogue presence and intelligibility','Understanding why formant-preserving pitch shift keeps a voice natural','Explaining why two people singing the same note still sound different']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ffcfd89a-5e03-564c-b138-c787d8d77f20' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal-tract resonances'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ffcfd89a-5e03-564c-b138-c787d8d77f20','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ffcfd89a-5e03-564c-b138-c787d8d77f20' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5edd57e0-0ea9-56bf-87d5-aa29b609722d','Voice onset','In phonetics, voice onset time (VOT) is the interval between the release of a stop consonant and the start of vocal-fold vibration for the following voiced sound; it is the primary acoustic cue distinguishing voiced stops such as /b, d, g/ from voiceless ones such as /p, t, k/. Positive VOT means voicing begins after the release, while negative VOT means voicing leads the release.','When you say a "p" or a "b", there is a tiny gap before your voice buzz starts. Voice onset is the length of that gap. A long gap sounds like "p"; almost no gap sounds like "b". It is measured in milliseconds.','It explains and measures how listeners tell similar consonants apart, and it marks where the voiced part of a sound truly begins. It provides a precise, measurable point of reference for the start of phonation.','When trimming the head of a word, an editor must respect voice onset so the edit does not clip the consonant''s release or expose an unnatural start to the voicing.','Speech acoustics',ARRAY['Voiced versus unvoiced speech','Vocal-fold vibration','Word-front clipping','Plosive','Phonation']::text[],ARRAY['Placing an edit point inside the onset, so the word begins mid-voicing and sounds clipped','Confusing voice onset time with the total duration of the consonant','Assuming every language marks voiced versus voiceless sounds with the same onset timing']::text[],ARRAY['Trimming the head of a word without clipping its consonant onset','Explaining why a hard gate can chop the start of plosive-led words','Analyzing why a replaced ADR word''s attack feels unnatural']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5edd57e0-0ea9-56bf-87d5-aa29b609722d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice onset'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5edd57e0-0ea9-56bf-87d5-aa29b609722d','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5edd57e0-0ea9-56bf-87d5-aa29b609722d' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69e488a6-0ece-528d-b064-8fd72f956a3c','Voice perspective','The impression of a voice''s distance and spatial placement, conveyed through its ratio of direct to reflected sound, its level, and its tonal balance, made to correspond with the on-screen framing and position of the speaker. Matching voice perspective keeps the sound of dialogue consistent with what the picture shows.','Voice perspective is how near or far a voice sounds. A close-up should sound close and clear. Someone far away in a wide shot should sound more distant and roomy. The mix matches the voice to what you see.','It preserves the audience''s sense of space and realism by tying how a voice sounds to where the character appears on screen. It exists so dialogue supports, rather than contradicts, the visual staging.','The re-recording mixer adjusts level, EQ, and reverb so a line matches its shot, pulling a voice back for a wide shot and bringing it forward and drier for a close-up.','Dialogue perspective',ARRAY['Wide-shot relief','Vowel-distance matching','Reverberation','Room tone','Worldized dialogue','Dialogue premix']::text[],ARRAY['Keeping every line at the same close, dry perspective regardless of shot size','Adding so much reverb for distance that dialogue loses intelligibility','UNSAFE: Judging perspective by repeatedly cranking dubbing-stage monitoring to loud levels, which can exceed OSHA 29 CFR 1910.95 noise-exposure limits; work at calibrated reference level and limit exposure time']::text[],ARRAY['Matching a line''s sound to a wide establishing shot versus a close-up','Deciding how dry or roomy an off-screen voice should sound','Keeping perspective consistent when intercutting production and ADR takes']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69e488a6-0ece-528d-b064-8fd72f956a3c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice perspective'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69e488a6-0ece-528d-b064-8fd72f956a3c','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69e488a6-0ece-528d-b064-8fd72f956a3c' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e4c533ec-81a7-5d81-814d-928a15645f23','Voiced versus unvoiced speech','A fundamental phonetic distinction between speech sounds produced with vocal-fold vibration (voiced sounds, such as all vowels and consonants like /b, d, g, v, z, m, n/) and those produced without it, using turbulent airflow or a burst alone (unvoiced or voiceless sounds, such as /p, t, k, f, s/). Voiced sounds carry periodic pitched energy; unvoiced sounds are aperiodic noise.','Some speech sounds use the voice box buzzing, like vowels and "z". These are voiced. Others use only air hiss or a puff, like "s" and "t". These are unvoiced. Put a hand on your throat: voiced sounds make it buzz.','It underlies how sounds are categorized, how pitch is carried, and how tools treat pitched versus noise-like parts of speech. It is the basic on-or-off state of phonation in speech.','An editor uses the distinction constantly: voiced portions can be pitch-shifted or crossfaded cleanly, while unvoiced sibilants and plosives need different handling, such as de-essing.','Speech acoustics',ARRAY['Vocal-fold vibration','Voice onset','Sibilance','Wideband de-essing','Fundamental frequency','Plosive']::text[],ARRAY['Trying to pitch-correct unvoiced sounds, which have no fundamental to track','Crossfading across an unvoiced consonant as if it were pitched, causing artifacts','Assuming a written letter is always voiced or unvoiced, when it depends on the actual sound and context']::text[],ARRAY['Choosing an edit point on a voiced vowel rather than a noisy consonant','Explaining why a de-esser targets unvoiced sibilants','Setting a pitch tool to ignore unvoiced sounds']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e4c533ec-81a7-5d81-814d-928a15645f23' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voiced versus unvoiced speech'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
