INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd8dc08b2-8c35-520c-b119-f3d58a457024','Vowel formation','The production of vowel sounds by voicing the airstream at the vocal folds while shaping the open vocal tract with the tongue, jaw, and lips. The tongue''s height and front-back position, together with lip rounding, tune the tract''s resonances (formants), especially the first two, which determine which vowel is heard; vowels are typically voiced, continuous, open-tract sounds.','Vowels are the open sounds like "a", "e", "i", "o", and "u". You make them by buzzing your voice and shaping your mouth. Moving your tongue and lips changes the sound. That is how "ee" becomes "oo" at the same pitch.','It explains how one voiced source becomes many distinct, recognizable vowels, which carry much of speech''s loudness and intelligibility. It is the articulatory basis of the vowel system.','Because vowels hold the sustained energy and pitch of speech, editors place cuts and crossfades on them, and mixers rely on them when balancing dialogue loudness.','Speech acoustics',ARRAY['Vocal-tract resonances','Formant','Vowel-body management','Vocal-fold vibration','Voiced versus unvoiced speech']::text[],ARRAY['Confusing vowel identity (set by formants) with pitch (set by vocal-fold rate)','Assuming written vowels map one-to-one to spoken vowel sounds','Editing across a changing vowel, such as a diphthong, as if its tone were steady']::text[],ARRAY['Placing a dialogue crossfade on a sustained vowel','Explaining why formant shifting changes a perceived vowel','Balancing dialogue loudness around vowel energy']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d8dc08b2-8c35-520c-b119-f3d58a457024' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vowel formation'),'[^a-z0-9]','','g'));
