INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da895656-0ef0-5d82-ba00-97806769f26b','Vowel-body management','In dialogue post-production, the control of the sustained voiced core (the "body") of vowels, which is the loudest and most resonant part of speech, so that its level and tonal weight stay consistent and balanced across a scene, typically through leveling, EQ, and gain automation.','The middle of a vowel is the loudest, richest part of a word. Vowel-body management means keeping that part even and controlled. Editors and mixers smooth its level and tone. This keeps dialogue steady and easy to hear.','It keeps dialogue loudness and warmth consistent by taming the parts of speech that carry the most energy, so vowels do not boom or mask consonants. It exists because uneven vowel energy makes dialogue feel lumpy or muddy.','A mixer rides levels or uses a leveler and EQ so strong vowels do not spike or overpower the clarity-carrying consonants, keeping a line smooth and intelligible.','Dialogue processing',ARRAY['Vowel formation','Vocal-tract resonances','Dialogue leveling','Equalization','Wideband de-essing','Voice perspective']::text[],ARRAY['Over-compressing vowel bodies until dialogue sounds flat and lifeless','Boosting low-mid EQ on vowels and making a voice boxy or muddy','Focusing on vowel level while ignoring the consonants that carry intelligibility']::text[],ARRAY['Smoothing uneven vowel loudness across an emotional performance','Reducing low-mid buildup on a resonant voice','Balancing vowel energy so consonants stay clear in a dense mix']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da895656-0ef0-5d82-ba00-97806769f26b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vowel-body management'),'[^a-z0-9]','','g'));
