INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '42ebaff7-a8c0-57c2-ae4e-01bed5c7051c','Vowel-distance matching','The practice of matching the perceived distance or perspective of dialogue across edits by aligning the tonal character and reflected-sound content of vowels, the sustained voiced portions that most clearly carry cues to microphone distance and room. It keeps two takes or shots sounding as though they occupy the same space.','Vowels carry strong clues about how far away a voice was recorded. Vowel-distance matching means making those clues line up between edits. The editor matches the tone and room sound of the vowels. Then two takes feel like the same place.','It hides edits by making the spatial cues in vowels consistent, so a character does not seem to jump nearer or farther between takes. It exists because mismatched perspective is most audible in the sustained vowel sounds.','When cutting between two microphones, or between a production take and an ADR line, the editor matches vowel tone, level, and room so the perspective stays continuous.','Dialogue perspective',ARRAY['Voice perspective','Wide-shot relief','Vowel formation','Room tone','Worldized dialogue','ADR match']::text[],ARRAY['Matching only overall level while leaving vowel tone and room sound mismatched','Ignoring the reflected-sound cues in vowels that reveal distance','Assuming EQ alone can fix a large perspective jump between takes']::text[],ARRAY['Intercutting a boom and a lav so both sound the same distance','Matching an ADR line''s perspective to the surrounding production dialogue','Smoothing perspective across a shot change within a scene']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='42ebaff7-a8c0-57c2-ae4e-01bed5c7051c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vowel-distance matching'),'[^a-z0-9]','','g'));
