SELECT '42ebaff7-a8c0-57c2-ae4e-01bed5c7051c','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='42ebaff7-a8c0-57c2-ae4e-01bed5c7051c' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0a3cb2b0-53e5-56f6-894b-9ca56f06b203','Wide-shot relief','A perspective treatment in which dialogue on a wide or establishing shot is set back, slightly lower in level, more distant and roomier in balance, and less intimate, to match the loosened framing, giving a sense of spatial opening after tighter close-up perspectives. It is an application of matching voice perspective to shot size.','In a wide shot, people look far away. The dialogue should open up to match. It sits back a little, with more room sound and less closeness. This gives the scene a feeling of space after tight close-ups.','It reinforces the visual scale of a wide shot and provides contrast to intimate close perspectives, helping the mix breathe. It exists because holding a close, dry perspective under a wide shot feels unnatural.','On a wide establishing shot, the re-recording mixer eases dialogue level and adds a touch of room or reverb so the voices sit naturally in the larger implied space.','Dialogue perspective',ARRAY['Voice perspective','Vowel-distance matching','Reverberation','Room tone','Worldized dialogue']::text[],ARRAY['Pulling dialogue so far back on a wide shot that it loses intelligibility','Keeping the same close perspective on every shot regardless of framing','Adding reverb without controlling it, so the wide-shot voice sounds washy']::text[],ARRAY['Setting dialogue back on a wide establishing shot of a landscape','Contrasting an intimate close-up with a following wide two-shot','Opening up perspective as characters move away from camera']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0a3cb2b0-53e5-56f6-894b-9ca56f06b203' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wide-shot relief'),'[^a-z0-9]','','g'));
