INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fd4331cc-ad38-501f-8b50-41d35f8f7ca1','Wideband de-essing','A de-essing method in which detected sibilance triggers gain reduction across the entire (broadband) signal rather than only the sibilant frequency band, so the whole voice level dips momentarily whenever an "s" or "sh" exceeds threshold. It contrasts with split-band or dynamic-EQ de-essing, which attenuates only the high-frequency sibilant range.','A de-esser lowers harsh "s" and "sh" sounds in a voice. Wideband means it turns down the whole voice for a moment when an "s" is too strong. This can sound natural in small amounts. The other type dips only the high hiss.','It tames sibilance simply and can sound natural in modest amounts, but because it acts on the full band it can briefly duck the whole voice. It exists as one of the two main de-essing approaches.','An editor picks wideband mode for gentle, occasional sibilance and switches to split-band when heavy de-essing would otherwise cause audible full-voice ducking.','Dialogue processing',ARRAY['Sibilance','Split-band de-essing','Voiced versus unvoiced speech','Compression','Equalization','Dialogue leveling']::text[],ARRAY['Setting too much wideband reduction, so the whole voice audibly ducks on every "s"','Using wideband mode on heavy sibilance where split-band would be cleaner','Setting the detector threshold so low that non-sibilant sounds trigger gain reduction']::text[],ARRAY['Softening occasional harsh sibilance on a dialogue line','Choosing between wideband and split-band modes in a de-esser plugin','Taming an over-bright lavalier microphone''s "s" sounds']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fd4331cc-ad38-501f-8b50-41d35f8f7ca1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wideband de-essing'),'[^a-z0-9]','','g'));
