INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9bb73018-7bcc-5ef7-8bf1-d6fab711f969','Word-front clipping','The truncation of the beginning (onset) of a spoken word in dialogue, where the initial consonant or voice onset is cut off, commonly caused by a too-tight edit, a slow-opening noise gate, a late channel un-mute, or a dropout, leaving the word starting abruptly or missing its attack. Here "clipping" means time-domain truncation, not amplitude distortion.','Word-front clipping is when the start of a word gets cut off. The word begins too late, so its first sound is missing. It often comes from a tight edit or a gate opening too slowly. It makes speech sound chopped.','Naming this fault helps editors spot and fix lost word beginnings that hurt intelligibility and naturalness. It matters because a word''s onset carries key cues to what was said.','An editor extends the edit''s head, adjusts gate timing, or patches from another take to restore a clipped word front so the line sounds complete.','Dialogue editing',ARRAY['Voice onset','Word-tail swallowing','Noise gate','Crossfade','Dialogue editing']::text[],ARRAY['Confusing this time-based truncation with amplitude clipping (distortion from overload)','Setting a noise gate''s attack too slow, so it chews the start of words','Trimming edits so tightly that consonant onsets are lost']::text[],ARRAY['Fixing a gate that eats the first consonant of quiet words','Repairing a tight edit that cut off a word''s attack','Restoring a dropped word start after a late fader move']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9bb73018-7bcc-5ef7-8bf1-d6fab711f969' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Word-front clipping'),'[^a-z0-9]','','g'));
