SELECT '9bb73018-7bcc-5ef7-8bf1-d6fab711f969','739bdba4-0fac-4455-9ee2-1a56096cab92',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9bb73018-7bcc-5ef7-8bf1-d6fab711f969' AND gt.achievement_id='739bdba4-0fac-4455-9ee2-1a56096cab92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd482dc2d-adac-5063-a9e2-75ac2254d98b','Word-tail swallowing','The loss or premature cutting of the end (tail) of a spoken word in dialogue, its final consonant, vowel decay, or trailing breath, commonly caused by an early edit out-point, a fast-closing noise gate, aggressive level automation, or being buried under following sound, so the word sounds cut short or "swallowed."','Word-tail swallowing is when the end of a word gets lost. The final sound is cut short or fades away too soon. It often comes from a gate closing fast or an edit ending too early. The word sounds unfinished.','Naming this fault helps editors preserve the natural decay and final consonants that make speech sound complete and intelligible. It matters because trailing sounds carry meaning and realism.','An editor lengthens the edit tail, softens the gate release, or eases automation so a word''s ending is not clipped or buried.','Dialogue editing',ARRAY['Word-front clipping','Noise gate','Crossfade','Room tone','Dialogue editing']::text[],ARRAY['Setting a noise gate''s release too fast, so word endings are chopped','Cutting an edit out-point before the word''s final consonant finishes','Riding automation down too soon and swallowing trailing sounds']::text[],ARRAY['Recovering a clipped final consonant after tight editing','Softening a gate so quiet word endings survive','Keeping trailing breaths that make a line sound natural']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d482dc2d-adac-5063-a9e2-75ac2254d98b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Word-tail swallowing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
