INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '39791786-31a0-5400-8f31-840d05655eaf','Worldized dialogue','Dialogue that has been "worldized," meaning played back through a loudspeaker into a real acoustic environment and re-recorded there, so it takes on the reverberation, coloration, and noise of that physical space instead of sounding like a clean studio recording. The technique is associated with Walter Murch''s work and is used to place voices convincingly in a real-world location or through a source such as a public-address system.','Worldizing means playing a recording out of a speaker in a real place, then recording it again there. The dialogue picks up the room''s echo and background. This makes a clean voice sound like it really happened in that space, like a voice over a stadium loudspeaker.','It gives dialogue authentic real-world space and character that artificial reverb can struggle to imitate, especially for source sounds like public-address systems, radios, or hard rooms. It exists to make clean or re-recorded voices sit believably in a location.','A sound team plays a line through a speaker in the actual or a similar location, such as a tunnel, gym, or PA system, and re-records it to capture that space for the mix.','Dialogue processing',ARRAY['Voice perspective','Reverberation','Futz','Room tone','Wide-shot relief','ADR match']::text[],ARRAY['Expecting an algorithmic reverb to fully replace the natural result of worldizing','UNSAFE: Driving playback loudspeakers to excessive levels and monitoring close to them without hearing protection, which can exceed OSHA 29 CFR 1910.95 noise-exposure limits','Worldizing in a space whose noise or character does not match the scene, adding unusable sound']::text[],ARRAY['Creating a realistic stadium or airport public-address voice','Making a phone or radio voice sit in a tiled bathroom','Giving flat ADR the sound of a real hard-surfaced location']::text[],'739bdba4-0fac-4455-9ee2-1a56096cab92'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='39791786-31a0-5400-8f31-840d05655eaf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Worldized dialogue'),'[^a-z0-9]','','g'));
