INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ae24612d-19b9-5790-b5f6-250b9e9835e7','AC bias','A high-frequency alternating current, well above the audio band, that is mixed with the audio signal and fed to the record head during magnetic tape recording. Through the anhysteretic magnetization process it linearizes the tape''s inherently nonlinear magnetic transfer characteristic, so the recorded remanent flux becomes proportional to the audio signal with low distortion and high sensitivity.','Magnetic tape does not respond evenly to weak signals. AC bias adds a steady high-pitched tone you cannot hear. This tone lifts the audio into the part of the tape that behaves well. The result is a cleaner, louder recording with far less distortion.','It overcomes the dead zone and severe nonlinearity of unbiased tape, letting the recorded magnetization follow the signal linearly. Without it, tape recording suffers gross distortion and poor sensitivity, especially at low signal levels.','An engineer sets and checks the AC bias level during machine alignment for each tape type, since bias directly affects distortion, noise, sensitivity, and high-frequency response.','Bias & recording',ARRAY['Bias current','Bias frequency','Anhysteretic recording','Bias compatibility','Bias null']::text[],ARRAY['Thinking AC bias is an audible tone recorded onto the tape, when it is filtered out and only conditions the recording','Confusing AC bias with DC bias; DC bias leaves residual magnetization and much higher noise','Assuming one bias setting suits every tape, when each formulation needs its own bias adjustment']::text[],ARRAY['Aligning a multitrack recorder''s bias for a new reel of tape stock','Diagnosing distortion or dull high end traced to incorrect bias','Explaining why analog tape can record cleanly despite a nonlinear medium']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ae24612d-19b9-5790-b5f6-250b9e9835e7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('AC bias'),'[^a-z0-9]','','g'));
