WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ae24612d-19b9-5790-b5f6-250b9e9835e7' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '57406202-21cd-5beb-b702-52b82d2a13cb','AES equalization','The reproduce/record frequency-response characteristic standardized by the Audio Engineering Society (AES-1971) for open-reel recording at 30 in/s (76 cm/s), defined by a low-frequency time constant of infinity (no low-frequency step) and a high-frequency time constant of 17.5 microseconds (transition near 9 kHz). It specifies how recorded flux versus frequency is equalized so tapes made and played on different machines match.','Tape does not record every pitch at the same strength. So a fixed tone-shaping curve is agreed for recording and playback. AES equalization is that agreed curve for fast 30 inch-per-second tape. It lets a tape made on one machine play back right on another.','It provides an interchange standard so recordings transfer accurately between machines and studios at 30 in/s. Complementary record and reproduce curves give a flat overall response.','A transfer engineer selects AES equalization when playing back a 30 in/s master and uses an MRL AES calibration tape to align the reproduce chain.','Tape equalization',ARRAY['Ampex Master Equalization','AC bias','Bias current','Bias compatibility','Reference fluxivity']::text[],ARRAY['Playing a 30 in/s AES-equalized tape with a NAB curve, producing a wrong tonal balance','Assuming AES equalization applies at 15 in/s, where IEC or NAB curves are used instead','Confusing the reproduce equalization standard with the record bias setting']::text[],ARRAY['Archiving a 30 in/s analog master and choosing the correct playback EQ','Aligning a mastering recorder with an AES calibration tape','Documenting the equalization used so a tape can be replayed correctly later']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='57406202-21cd-5beb-b702-52b82d2a13cb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('AES equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '57406202-21cd-5beb-b702-52b82d2a13cb','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='57406202-21cd-5beb-b702-52b82d2a13cb' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '926f0879-d959-5a48-b0d1-cff9be64b699','Ampex Master Equalization','A proprietary recording equalization used by Ampex on certain mastering recorders that departs from a simple transition-frequency curve, applying a shaped ''hearing-curve'' pre-emphasis. The recorded flux carried a deliberate hump, roughly from about +3 dB near 630 Hz to about +8 dB near 2 kHz, falling to around -12 dB near 16 kHz.','Ampex made its own tone-shaping curve for some tape recorders. It boosted the middle frequencies more than usual and cut the highs. This was meant to match how people hear. Tapes made this way need the matching curve to play back right.','It aimed to improve the perceived signal-to-noise ratio by shaping the recorded response toward human hearing, rather than only toward tape losses. It is a nonstandard curve tied to specific Ampex machines.','An archivist who finds a tape recorded with Ampex Master Equalization must replay it with the matching curve, or reconstruct it, to avoid a badly colored transfer.','Tape equalization',ARRAY['AES equalization','AC bias','Bias current','Bias compatibility']::text[],ARRAY['Replaying an Ampex Master Equalization tape with a standard NAB or IEC curve, giving a wrong tonal balance','Assuming it is just a different transition frequency, when it is a shaped hearing curve','Not documenting that a legacy tape used this nonstandard equalization']::text[],ARRAY['Transferring an older Ampex-mastered tape in an archive','Troubleshooting an unexpectedly bright or dull transfer','Deciding which equalization curve a legacy master requires']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='926f0879-d959-5a48-b0d1-cff9be64b699' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ampex Master Equalization'),'[^a-z0-9]','','g'));
