INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c94a469d-2fef-5499-b91a-06c37d193573','Anhysteretic recording','A recording process in which the tape is magnetized by a signal field while simultaneously exposed to a large, high-frequency alternating (bias) field whose amplitude falls to zero as the tape leaves the head gap. This produces a remanent magnetization that is linearly proportional to the small signal field, and it is the mechanism that makes AC-bias tape recording linear.','Plain magnetic tape reacts to a signal in a lumpy, uneven way. Anhysteretic recording adds a strong fading high-frequency field while recording. This coaxes the tape into responding smoothly and evenly. It is the trick that makes tape recording sound clean.','It converts the tape''s nonlinear magnetic response into a linear one, so recorded level tracks the input. It is the physical basis of AC bias in audio tape recording.','Understanding anhysteretic recording helps a technician grasp why correct bias amplitude matters and why underbiased or overbiased tape distorts or loses output.','Bias & recording',ARRAY['AC bias','Anhysteretic remanence','Bias current','Bias frequency']::text[],ARRAY['Confusing anhysteretic recording with ordinary magnetization from a single steady field','Thinking the bias field itself is stored as signal, rather than enabling linear recording','Assuming more bias always means more linearity, ignoring the loss of high frequencies']::text[],ARRAY['Explaining in training why AC bias linearizes tape','Analyzing distortion when bias is set incorrectly','Comparing tape formulations by their anhysteretic sensitivity']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c94a469d-2fef-5499-b91a-06c37d193573' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Anhysteretic recording'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c94a469d-2fef-5499-b91a-06c37d193573','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c94a469d-2fef-5499-b91a-06c37d193573' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '72397df6-6dda-5ceb-89d0-89609d572f4b','Anhysteretic remanence','The remanent (permanent) magnetization left in a magnetic medium after it has been exposed simultaneously to a small signal field and a large alternating field that is then reduced to zero. In tape recording it is the ideal magnetization that is linearly proportional to the applied signal field over a wide range, and it underlies the sensitivity of AC-bias recording.','Remanence is the magnetism left in tape after recording. Here it is set with the help of a fading high-pitched field. This leftover magnetism grows evenly with the signal. That even response is why biased tape records so cleanly.','It quantifies the linear, high-sensitivity magnetization that AC bias creates, and it explains why biased tape stores signals with low distortion. It is a key property when comparing tape formulations.','Engineers and tape chemists use anhysteretic remanence and sensitivity figures to characterize tape stock and to predict how much output and headroom a formulation will give.','Bias & recording',ARRAY['Anhysteretic recording','AC bias','Bias current','Coercivity']::text[],ARRAY['Confusing anhysteretic remanence with the ordinary remanence left by a single saturating field','Assuming remanence keeps rising linearly at all signal levels, ignoring saturation','Treating remanence and coercivity as the same property']::text[],ARRAY['Comparing the sensitivity of different tape formulations','Explaining why bias improves both linearity and output','Interpreting tape datasheet magnetic properties']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='72397df6-6dda-5ceb-89d0-89609d572f4b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Anhysteretic remanence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '72397df6-6dda-5ceb-89d0-89609d572f4b','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='72397df6-6dda-5ceb-89d0-89609d572f4b' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '76591fcb-0f8b-578f-8263-da325137690a','Back tension','The controlled holdback tension applied to the tape by the supply side of a tape transport, opposing the pull of the capstan and take-up, to keep the tape firmly and consistently in contact with the heads and guides. Correct back tension maintains stable head-to-tape contact, smooth tape packing, and steady speed.','As tape moves, the supply reel gently pulls backward. This holdback keeps the tape pressed against the heads. Too little makes the sound dull and unstable. Too much can stretch the tape or wear the heads.','It ensures firm, even head-to-tape contact for good high-frequency response and steady speed, and it keeps the tape wound smoothly on the reel. Without proper back tension, output drops and wow and flutter rise.','A technician measures and adjusts back tension during transport alignment using a tension gauge, and rechecks it when high-frequency dropouts or poor tape packing appear.','Tape transport',ARRAY['Capstan','Wow and flutter','Head-to-tape contact','Pinch roller','Tape guides']::text[],ARRAY['Assuming tension is set only on the take-up side, ignoring the critical supply-side holdback','Overlooking low back tension as a cause of weak, dull high frequencies','UNSAFE: Reaching into a running transport to feel tape tension, risking fingers being caught by moving reels, capstan, and pinch roller']::text[],ARRAY['Aligning a reel-to-reel transport before a transfer session','Diagnosing high-frequency loss caused by poor head contact','Correcting uneven or spilling tape packs on the reel']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='76591fcb-0f8b-578f-8263-da325137690a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Back tension'),'[^a-z0-9]','','g'));
