WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='76591fcb-0f8b-578f-8263-da325137690a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '58b346a6-ee1d-5e73-a77f-a336244d92eb','Bias compatibility','The degree to which a given tape formulation can be recorded correctly using a machine''s or another tape''s established bias and equalization settings without recalibration. Tapes of similar sensitivity, bias requirement, and reference fluxivity are bias-compatible; differing formulations require the machine''s bias, record EQ, and level to be realigned.','Different tapes need different amounts of bias to record well. Bias compatibility means two tapes need nearly the same settings. If a tape is compatible, you can swap it in without redoing the alignment. If not, the machine must be recalibrated first.','It tells an engineer whether a tape can be used interchangeably on a machine set up for a reference stock, or whether realignment is required. It protects recording quality when the tape stock changes.','Before loading an unfamiliar reel, a technician checks whether it is bias-compatible with the current alignment, or runs a fresh bias, EQ, and level calibration.','Bias adjustment',ARRAY['AC bias','Bias current','AES equalization','Reference fluxivity','Overbias']::text[],ARRAY['Assuming any tape of the same width and speed is interchangeable without checking bias needs','Swapping tape brands mid-project without recalibrating bias, EQ, and level','Confusing bias compatibility with mere mechanical fit on the reel']::text[],ARRAY['Substituting a different tape brand when the usual stock runs out','Deciding whether an archival reel can play on a machine aligned for another tape','Planning a session''s tape budget around available compatible stock']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='58b346a6-ee1d-5e73-a77f-a336244d92eb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias compatibility'),'[^a-z0-9]','','g'));
