INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4cf72391-b8d8-5736-a5f2-68a8680a08cb','Bias current','The magnitude of the high-frequency alternating current delivered to the record head to provide AC bias. Its level is a critical alignment parameter because it trades off sensitivity, distortion, noise, and high-frequency response; it is normally set to a defined amount of overbias past the peak-output point for a given tape and speed.','Bias current is how much of the high-frequency bias signal goes to the record head. Its level is a careful balance. Too little raises distortion; too much dulls the high notes. Engineers set it to a sweet spot for each tape.','It sets the operating point of the recording, determining the balance between distortion, output, noise, and high-frequency response. Correct bias current is essential for accurate, low-distortion recording.','During alignment a technician records a tone and adjusts bias current to the peak, then past it by the tape''s specified overbias, reading the level change on a meter.','Bias adjustment',ARRAY['AC bias','Bias frequency','Bias compatibility','Overbias','Bias null']::text[],ARRAY['Setting bias current by ear instead of by the specified overbias at a defined test frequency','Forgetting that raising bias current reduces high-frequency output','UNSAFE: Servicing or probing inside an energized, mains-powered tape machine without following lockout and safe-service practice']::text[],ARRAY['Biasing a recorder for a new tape formulation','Setting overbias to a datasheet value at 10 kHz','Troubleshooting distortion or dull highs caused by wrong bias']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4cf72391-b8d8-5736-a5f2-68a8680a08cb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias current'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4cf72391-b8d8-5736-a5f2-68a8680a08cb','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4cf72391-b8d8-5736-a5f2-68a8680a08cb' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '24468457-2f74-5f65-8c46-bb9d5a79d30c','Bias feedthrough','The unwanted leakage of the high-frequency bias signal from the record head or record electronics into the reproduce head, monitor path, meters, or adjacent channels. Because it lies above the audio band, it is suppressed by bias traps so it does not overload amplifiers, disturb metering, or intermodulate with the signal.','The bias signal is strong and can leak where it is not wanted. It can bleed into the playback head or the meters. This leak is called bias feedthrough. Filters called bias traps remove it so it does not cause trouble.','Naming and controlling bias feedthrough matters because stray bias can overload reproduce amplifiers, give false meter readings, or beat with other signals. Bias traps exist specifically to reject it.','A technician who sees unexplained meter offset or amplifier overload during record-monitor checks for bias feedthrough and confirms the bias trap is tuned correctly.','Bias adjustment',ARRAY['Bias trap','Bias null','Bias frequency','AC bias']::text[],ARRAY['Mistaking bias feedthrough on a meter for real high-level audio','Ignoring a mistuned bias trap that lets feedthrough overload the electronics','Assuming feedthrough is audible, when it lies above the hearing range']::text[],ARRAY['Diagnosing meter offset while recording','Tuning a bias trap during electronics alignment','Tracing amplifier overload that appears only in record mode']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='24468457-2f74-5f65-8c46-bb9d5a79d30c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias feedthrough'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '24468457-2f74-5f65-8c46-bb9d5a79d30c','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='24468457-2f74-5f65-8c46-bb9d5a79d30c' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aa2b0fc4-7524-578e-bff2-b881afd6b061','Bias frequency','The frequency of the alternating current used for AC bias and erase, chosen well above the highest recorded audio frequency, typically about 100 kHz to 250 kHz in professional audio recorders and higher in some machines. It is set high enough to keep intermodulation products out of the audio band and to erase cleanly, yet practical for efficient head drive.','AC bias uses a high-frequency tone far above what we can hear. The exact pitch of that tone is the bias frequency. It is usually a few hundred thousand cycles per second. It sits well above the music so the two do not clash.','A high enough bias frequency keeps intermodulation products out of the audio band and allows clean erasure, while staying low enough for practical head and oscillator efficiency. It sets the operating frequency of the bias/erase oscillator.','A service technician confirms the bias oscillator frequency against the service manual when diagnosing noise, poor erasure, or oscillator faults.','Bias & recording',ARRAY['AC bias','Bias current','Bulk erasure','Bias trap']::text[],ARRAY['Assuming the bias frequency is fixed at one value across all machines, when it varies widely by design','Thinking a higher bias frequency is always better, ignoring head and oscillator efficiency','Confusing bias frequency (the carrier) with bias current (its level)']::text[],ARRAY['Servicing a bias/erase oscillator','Choosing settings when interfacing external bias equipment','Explaining why bias sits above the audio band']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aa2b0fc4-7524-578e-bff2-b881afd6b061' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias frequency'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
