WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aa2b0fc4-7524-578e-bff2-b881afd6b061' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e7a0de81-0575-5d25-b225-6144b83fe467','Bias null','The alignment condition in which an unwanted bias-frequency component is minimized to a null at a point in the signal chain, most commonly the setting of a tunable bias trap so that residual bias feedthrough at the reproduce output falls to a minimum. It is used to reject stray bias from the monitored or metered signal.','Sometimes the strong bias signal leaks into the output. A bias null is the setting where that leak drops to almost nothing. A technician tunes a filter until the stray bias reaches its lowest point. This keeps the bias out of the sound and the meters.','Finding a bias null keeps residual bias feedthrough from disturbing metering, monitoring, or downstream electronics. It is a target point during electronics alignment.','During alignment a technician adjusts the bias trap for a null while watching a meter or oscilloscope for minimum bias at the output.','Bias adjustment',ARRAY['Bias trap','Bias feedthrough','Bias frequency','AC bias']::text[],ARRAY['Confusing the bias null adjustment with setting the record bias current for the tape','Leaving the bias trap mistuned so a true null is never reached','Assuming the null point is fixed and never needs rechecking after repairs']::text[],ARRAY['Tuning a bias trap for minimum feedthrough','Aligning reproduce electronics after a repair','Removing stray bias that upsets the meters']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e7a0de81-0575-5d25-b225-6144b83fe467' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias null'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e7a0de81-0575-5d25-b225-6144b83fe467','e9c64f09-41cc-480b-affc-4e0919253e5c',true
