INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6dd402b7-d01b-5778-8c07-07e0ae59b985','Bias rocks','An informal term for the characteristic behavior seen when setting record bias: as bias current is increased, the reproduced level of a fixed test tone rises to a peak and then falls, appearing to ''rock'' over the peak. This peak is the landmark used to find peak bias before increasing bias past the peak by the tape''s specified overbias.','When you set bias, you record a steady tone and watch the level. As you turn up the bias, the level climbs to a top point, then drops. People say the bias ''rocks'' over that peak. That peak is the mark you use to set the final bias.','The peaking behavior gives a repeatable reference point for bias alignment, since the peak is easy to spot on a meter. From it the technician sets the correct overbias.','While recording a test tone such as 10 kHz, a technician watches the meter peak and drop, notes the peak, then increases bias to the specified overbias below it.','Bias adjustment',ARRAY['Bias current','AC bias','Overbias','Bias compatibility']::text[],ARRAY['Setting bias at the peak itself instead of at the specified overbias past the peak','Using the wrong test frequency, which shifts where the peak appears','Confusing the level peak with the correct final bias setting']::text[],ARRAY['Peaking bias during machine alignment','Setting overbias for a specific tape formulation','Teaching a trainee to read the bias peak on a meter']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6dd402b7-d01b-5778-8c07-07e0ae59b985' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias rocks'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6dd402b7-d01b-5778-8c07-07e0ae59b985','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6dd402b7-d01b-5778-8c07-07e0ae59b985' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8dcd212a-8e21-5dc1-9626-4039d6b8d9a4','Bias trap','A tuned filter in a tape machine''s reproduce (and sometimes record) electronics that rejects the high-frequency bias signal so it does not reach the output, meters, or following stages. Typically a notch or low-pass network centered on the bias frequency, it suppresses bias feedthrough that would otherwise overload amplifiers or disturb metering.','The bias signal is a strong high-frequency tone that can leak into the playback path. A bias trap is a filter that blocks it. It lets the audio through but stops the bias. This keeps the bias from overloading the electronics or fooling the meters.','It removes stray bias frequency from the signal path so amplifiers are not overloaded and meters read only audio. It exists because bias leakage is far stronger than the wanted signal and lies just above the audio band.','A technician tunes the bias trap for minimum bias at the output during electronics alignment, and checks it when unexplained overload or meter offset appears in record mode.','Bias adjustment',ARRAY['Bias feedthrough','Bias null','Bias frequency','AC bias']::text[],ARRAY['Assuming the bias trap affects the audio tone, when it targets only the ultrasonic bias','Leaving a mistuned bias trap in place, so bias feedthrough overloads the electronics','Confusing the bias trap with the record bias level control']::text[],ARRAY['Aligning reproduce electronics on a service bench','Curing amplifier overload traced to bias feedthrough','Restoring a machine whose bias trap drifted after component aging']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8dcd212a-8e21-5dc1-9626-4039d6b8d9a4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bias trap'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8dcd212a-8e21-5dc1-9626-4039d6b8d9a4','e9c64f09-41cc-480b-affc-4e0919253e5c',true
