INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a29b3fa5-5596-5248-88ae-dff375a5c844','Bulk erasure','The erasure of an entire reel or cassette at once by exposing it to a strong alternating magnetic field, from a bulk eraser or degausser, whose amplitude exceeds the tape''s coercivity and is then gradually reduced so the magnetic domains are left randomly oriented. This demagnetizes the whole tape to a low-noise erased state without threading it on a machine.','A bulk eraser wipes a whole reel of tape at once. It surrounds the tape with a strong, shaking magnetic field. As the field fades, it scrambles the magnetism into randomness. The tape is left blank and quiet.','It erases full reels quickly and more completely than a machine''s erase head, giving a low residual noise floor and reusable tape. It is used for wiping, recycling, or securely clearing recordings.','An operator moves each reel slowly through the eraser''s field and withdraws it slowly from a distance, so the field acting on the tape decays smoothly to zero.','Erasure',ARRAY['Bulk-erased noise','AC bias','Bias frequency','Coercivity']::text[],ARRAY['Pulling the tape out of the field too quickly, which can leave it partly magnetized and noisy','UNSAFE: Operating a bulk eraser near anyone with a pacemaker or implanted medical device, whose function a strong magnetic field can disrupt','UNSAFE: Placing credit cards, hard drives, phones, or mechanical watches near an energized eraser, whose field can damage them; and ignoring the coil''s heat and duty-cycle limits']::text[],ARRAY['Wiping reels of tape for reuse in a studio','Securely erasing recordings before disposal','Preparing blank stock with a low, uniform noise floor']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a29b3fa5-5596-5248-88ae-dff375a5c844' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bulk erasure'),'[^a-z0-9]','','g'));
