INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '219a5b97-24e3-516b-80ea-ec6e69839ad6','Bulk-erased noise','The residual reproduce noise measured from a tape that has been AC bulk-erased (fully demagnetized), representing the baseline erased-tape noise floor of the tape and transport. It is lower than the noise of a DC-saturated (DC-erased) tape and serves as a reference condition when characterizing tape and machine noise.','Even a blank, erased tape is not perfectly silent. Bulk-erased noise is the faint hiss left after a bulk eraser wipes the tape. It is about the quietest an erased tape gets. Engineers use it as a baseline to judge other noise.','It defines the lowest practical noise floor of the erased medium, used as a reference against which recorded and biased noise are compared. Measuring it helps separate tape noise from electronics or modulation noise.','When evaluating a tape or machine, a technician measures bulk-erased tape noise as the baseline, then compares biased and recorded noise against it.','Erasure',ARRAY['Bulk erasure','AC bias','Bias frequency','Modulation noise']::text[],ARRAY['Confusing bulk-erased noise with the much higher noise of a DC-saturated tape','Blaming the tape for noise actually coming from the reproduce electronics','Assuming a bulk-erased tape is completely silent']::text[],ARRAY['Measuring a tape''s baseline noise floor','Comparing noise before and after biasing','Deciding whether hiss comes from the tape or from the electronics']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='219a5b97-24e3-516b-80ea-ec6e69839ad6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bulk-erased noise'),'[^a-z0-9]','','g'));
