WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='219a5b97-24e3-516b-80ea-ec6e69839ad6' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'adf5508a-2802-599c-8326-dec1c3d54d3e','CCIR equalization','A magnetic-tape record and reproduce equalization standard (IEC1), used chiefly in Europe, defined by its playback time constants; at 15 in/s it specifies a 35 us high-frequency time constant and no low-frequency time constant, and at 7.5 in/s a 70 us high-frequency time constant. It differs from the American NAB (IEC2) curve, which adds a 3180 us low-frequency time constant (a bass turnover) and uses a 50 us high-frequency time constant.','CCIR is a European tuning standard for reel-to-reel tape. It sets how a tape machine boosts or cuts tones on playback. It uses no bass boost, unlike the American NAB standard. Play a tape with the wrong standard and the tone sounds wrong.','It standardizes the record and replay equalization curve so a tape recorded on one machine plays back with correct, flat frequency response on another. This lets tapes and calibration line up across studios and countries.','An engineer selects CCIR (IEC) or NAB on the machine to match the tape, then aligns the reproducer to a matching calibration tape before transferring or mixing.','Tape equalization',ARRAY['DIN tape equalization','NAB equalization','IEC equalization','Calibration tape','Reproduce head','Tape speed']::text[],ARRAY['Playing a CCIR-recorded tape with NAB equalization selected, which shifts the bass and makes the sound dull or bright','Assuming CCIR and NAB differ only slightly, when the low-frequency time-constant difference clearly changes the tonal balance','Forgetting that the correct high-frequency time constant changes with tape speed']::text[],ARRAY['Setting a European Studer machine to IEC/CCIR before playing an archival master','Matching a reproducer''s equalization to the standard noted on a tape box during a transfer','Troubleshooting a transferred tape that sounds tonally wrong because the wrong standard was used']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='adf5508a-2802-599c-8326-dec1c3d54d3e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('CCIR equalization'),'[^a-z0-9]','','g'));
