INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0f0b2bc0-6a47-5551-9e0a-440982ceef2f','Center track','A narrow track recorded down the longitudinal centerline of the tape, most commonly used for center-track SMPTE/EBU timecode on quarter-inch stereo tape, where the timecode track (about 31 mils wide) sits between the two audio tracks (about 82 mils each) with guard bands. Placing timecode in the center leaves both stereo audio channels usable.','A center track is a thin recording strip down the middle of the tape. It is often used to store SMPTE timecode, a timing signal. Putting it in the center keeps both stereo sound tracks free. Guard bands on each side stop the signals from bleeding together.','It provides a place for a sync or timecode signal without sacrificing an audio channel, so a stereo recording can still lock to picture or other machines. It exists to add synchronization to a two-track tape.','On center-track timecode machines such as Fostex or Tascam models, an engineer stripes timecode on the center track so the tape can chase or lock to video and other recorders.','Track formats',ARRAY['Cue track','Timecode','Guard band','Sync track','Track width','Quarter-inch tape']::text[],ARRAY['Assuming center-track timecode reduces the tape to mono, when both stereo audio tracks stay intact','Recording timecode too hot, so it crosstalks into the adjacent audio tracks despite the guard bands','Trying to read center-track timecode with a standard stereo head that cannot pick up the narrow center strip']::text[],ARRAY['Striping SMPTE timecode on a stereo location recording to sync with a camera','Transferring an old center-track tape that needs a machine with a center timecode head','Locking a stereo tape to a digital workstation using its center-track timecode']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0f0b2bc0-6a47-5551-9e0a-440982ceef2f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Center track'),'[^a-z0-9]','','g'));
