INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '494776e6-efd3-50de-8ff9-9d1bfca30e65','Closed-loop dual capstan','A tape transport design that drives the tape with two capstans, one on each side of the head stack, so the length of tape passing the heads forms an isolated closed loop. The paired capstans hold constant tension across the heads and decouple that region from disturbances at the supply and take-up reels, reducing flutter and stabilizing head-to-tape contact.','This transport uses two drive shafts, called capstans, one before the heads and one after. They trap a short loop of tape across the heads. This keeps the tape tension steady and the wobble low where it matters. Problems from the reels cannot reach the heads.','It isolates the tape at the heads from reel tension changes and stretching, giving very stable speed and tension. This lowers flutter and keeps steady head contact for cleaner high-frequency response.','Engineers favor closed-loop dual-capstan machines for mastering and archival transfer because the stable tension gives consistent level and low flutter; both capstans and their pinch rollers must be clean and correctly set.','Tape transport',ARRAY['Closed-loop transport','Constant-tension transport','Capstan','Pinch roller','Flutter','Dancer arm']::text[],ARRAY['Threading the tape outside one of the two capstans, breaking the closed loop and its tension control','Blaming flutter on the tape when a dirty or worn capstan or pinch roller is the real cause','UNSAFE: Reaching into the moving transport or cleaning capstans and pinch rollers with power on; switch off and unplug the machine before servicing to avoid pinch injuries and mains-voltage contact']::text[],ARRAY['Choosing a dual-capstan machine for a low-flutter archival transfer','Diagnosing tension or flutter problems in the head area','Cleaning both capstans and pinch rollers during routine maintenance']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='494776e6-efd3-50de-8ff9-9d1bfca30e65' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Closed-loop dual capstan'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '494776e6-efd3-50de-8ff9-9d1bfca30e65','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='494776e6-efd3-50de-8ff9-9d1bfca30e65' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'eb802d2c-eaf9-5afa-a94e-49a7e3a36b89','Closed-loop transport','A tape transport arrangement in which the section of tape passing the head assembly is held as a mechanically isolated (closed) loop, typically between two capstans or a capstan and a driven element, so that tape tension and speed at the heads are controlled independently of the supply and take-up reels. The aim is constant tension and minimal flutter and wow at the point of recording and playback.','A closed-loop transport traps a short loop of tape across the heads. Inside that loop, the tension and speed stay steady. Whatever the reels do outside the loop does not disturb the heads. This gives smoother, more stable playback.','It keeps the tape moving past the heads at a steady speed and tension, which sets pitch stability and clean sound. It exists to shield the critical head region from reel-side disturbances.','Technicians meet closed-loop designs on high-end mastering and archival machines and must thread and tension the loop correctly for the transport to hold speed and level.','Tape transport',ARRAY['Closed-loop dual capstan','Constant-tension transport','Capstan','Flutter','Dancer arm','Pinch roller']::text[],ARRAY['Threading the tape so the loop is not properly closed, losing the tension control the design depends on','Confusing this physical tape loop with a servo feedback loop in the electronics','UNSAFE: Servicing the moving transport with the machine powered; switch off and unplug before working near capstans, rollers, and mains wiring']::text[],ARRAY['Explaining why a mastering deck holds pitch better than a budget machine','Threading a closed-loop machine correctly before a transfer','Diagnosing flutter traced to a disturbed tape loop']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='eb802d2c-eaf9-5afa-a94e-49a7e3a36b89' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Closed-loop transport'),'[^a-z0-9]','','g'));
