INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e2066d45-0f12-5bc7-8833-371e16a8a84e','Coercivity','The magnitude of the reverse (opposing) magnetic field required to reduce the remanent magnetization of a magnetic material to zero, measured in oersteds (Oe) or amperes per metre (A/m). For recording tape it indicates the field strength needed to record on or erase the coating: typical values are about 300 to 360 Oe for gamma ferric oxide, 450 to 650 Oe for chromium dioxide, and roughly 1000 to 1500 Oe for metal-particle tape.','Coercivity is how hard it is to change a magnetic material''s magnetism. High-coercivity tape needs a stronger field to record on it or wipe it clean. It is like how strongly the tape resists having its magnetism changed or erased. Metal tape has high coercivity; basic oxide tape has less.','It tells the engineer how much record and bias current, and how strong an erase field, a given tape formulation needs. It also relates to how well the tape resists accidental erasure and holds short-wavelength high frequencies.','When changing tape stock, an engineer rebiases and realigns the machine because a higher-coercivity tape needs more bias and erase current to record and erase correctly.','Magnetic properties',ARRAY['Retentivity','Bias','DC erasure','Remanence','Saturation','Degausser dwell']::text[],ARRAY['Assuming a bulk eraser set for oxide tape will fully erase high-coercivity metal tape, which needs a stronger field','Confusing coercivity (resistance to field change) with retentivity or output level (how much signal the tape stores)','Switching to a different tape without rebiasing, so the recording is under- or over-biased']::text[],ARRAY['Selecting bias for a new reel of tape','Choosing a degausser strong enough to erase a high-coercivity master','Understanding why metal tape resists accidental partial erasure better than oxide']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e2066d45-0f12-5bc7-8833-371e16a8a84e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Coercivity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e2066d45-0f12-5bc7-8833-371e16a8a84e','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e2066d45-0f12-5bc7-8833-371e16a8a84e' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7024e041-925d-5a33-a6e0-be610e20c4ce','Constant-tension transport','A tape transport that actively holds the tape at a constant tension as it passes the heads, typically using tension-sensing arms (dancer arms) whose position feeds a reel servo that adjusts supply and take-up motor torque as the reel diameters change. Constant tension maintains steady head-to-tape contact, stable speed, and consistent level from the start to the end of a reel.','This transport keeps the tape pulled with the same steady tension the whole time. Sensing arms feel the tension and tell the reel motors to adjust. Steady tension keeps the tape pressed evenly on the heads. That keeps the sound level and speed stable as the reel empties.','It prevents the changing pull of a filling or emptying reel from altering head contact and level, so the recording stays even. It exists to keep tension steady despite constantly changing reel sizes.','Technicians set and check reel tension with a tension gauge during alignment so the servo holds the specified tension across the whole reel.','Tape transport',ARRAY['Dancer arm','Closed-loop transport','Reel servo','Tape tension','Capstan','Flutter']::text[],ARRAY['Setting reel tension by feel instead of measuring it with a tension gauge to the machine''s spec','Ignoring a sticking or bent tension arm, which starves the servo of correct feedback','Assuming tension only affects the reels, when it directly changes head contact, level, and high-frequency response']::text[],ARRAY['Adjusting the reel-servo tension during a machine alignment','Curing level or high-frequency changes between the start and end of a reel','Protecting fragile archival tape from excessive tension']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7024e041-925d-5a33-a6e0-be610e20c4ce' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Constant-tension transport'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7024e041-925d-5a33-a6e0-be610e20c4ce','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7024e041-925d-5a33-a6e0-be610e20c4ce' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0e2b8ad2-30ea-5af0-81e9-4ae98eff8d65','Contact loss','The loss of intimate physical contact between the tape coating and the head, which introduces a separation (spacing) between them and attenuates the reproduced signal, most severely at short wavelengths (high frequencies). The separation loss follows the Wallace relation of about 54.6 dB per wavelength of spacing, so even a microscopic gap causes large high-frequency loss.','Tape must touch the head closely to work well. Contact loss is when a tiny gap opens between them. Even a microscopic gap cuts the high frequencies a lot. It is why dirt, wear, or a rough spot makes a tape sound dull.','The concept explains why clean, close head-to-tape contact is essential and why high frequencies suffer first when contact is poor. It guides cleaning, head maintenance, and tape handling.','When a machine sounds dull or loses top end, a technician cleans the heads and tape path and checks head wear and tape pack, because contact loss is a common cause.','Head-tape interface',ARRAY['Contact-loss dropout','Dropout','Spacing loss','Head wear','Crowned guide','Azimuth']::text[],ARRAY['Blaming dull high frequencies on equalization when poor head contact is the real cause','Letting oxide, dust, or debris build on the heads, which lifts the tape and loses high frequencies','Assuming contact loss lowers all frequencies equally, when short-wavelength high frequencies are hit hardest']::text[],ARRAY['Diagnosing lost treble on playback','Cleaning heads and guides to restore high-frequency response','Assessing a worn or dished head that no longer contacts the tape well']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0e2b8ad2-30ea-5af0-81e9-4ae98eff8d65' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Contact loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0e2b8ad2-30ea-5af0-81e9-4ae98eff8d65','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0e2b8ad2-30ea-5af0-81e9-4ae98eff8d65' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '81173a3f-b686-598b-90f6-13374fa6e815','Contact-loss dropout','A brief drop or momentary loss of reproduced signal caused by a transient loss of head-to-tape contact, when debris, a coating defect, a wrinkle, or surface roughness momentarily lifts the tape off the head and creates spacing loss. It is heard as a short dip or gap, most obvious at high frequencies, and is distinct from a permanent loss of oxide.','A dropout is a quick dip or gap in the sound. This kind happens when the tape briefly lifts off the head. A speck of dirt or a bad spot on the tape can cause it. The high frequencies fade for a moment, then return.','Naming this fault helps a technician tell a temporary contact problem from permanent damage and points to cleaning or handling as the fix. It matters because these dropouts hurt clarity and can spoil a transfer.','During a transfer, an engineer who hears repeated dropouts cleans the tape path and the tape, checks for shed or debris, and may re-tension or bake a shedding tape.','Head-tape interface',ARRAY['Contact loss','Dropout','Spacing loss','Shedding','Sticky-shed syndrome','Tape cleaning']::text[],ARRAY['Confusing a contact-loss dropout with a permanent bare spot where the oxide is actually gone','Continuing to play a shedding tape, which deposits debris and causes more dropouts and contact loss','Ignoring dirty heads and guides that repeatedly lift the tape and drop the signal']::text[],ARRAY['Hearing intermittent high-frequency dips while transferring an old tape','Deciding whether dropouts come from debris or from lost oxide','Cleaning the path to reduce dropouts before an archival capture']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='81173a3f-b686-598b-90f6-13374fa6e815' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Contact-loss dropout'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '81173a3f-b686-598b-90f6-13374fa6e815','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='81173a3f-b686-598b-90f6-13374fa6e815' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '58b9bb19-c308-51f3-9a3d-094c6bd3b6f2','Crowned guide','A tape guide or roller whose contact surface is slightly convex (crowned), higher at the center than at the edges, so that the tape self-centers laterally on it. As with a crowned pulley, tape running onto the convex surface tends to climb toward the highest point, steering it to a consistent height and reducing lateral weave without relying on tight-fitting flanges.','A crowned guide is a tape roller that bulges slightly in the middle. The tape naturally rides toward the high center point. This keeps the tape at a steady height as it moves. It is the same trick that keeps a belt centered on a rounded pulley.','It keeps the tape running at a steady height so it stays aligned with the heads, without pinching the edges as flanged guides can. It exists to reduce sideways weaving and edge damage.','A technician relies on well-shaped guides for stable tracking; a worn or grooved guide lets the tape wander, causing level changes and skew that call for cleaning or replacing the guide.','Tape transport',ARRAY['Tape guide','Tracking','Azimuth','Skew','Dancer arm','Contact loss']::text[],ARRAY['Assuming edge flanges alone must force tracking, when a crowned surface self-centers the tape more gently','Overlooking a worn or grooved guide that lets the tape weave and change level','Cleaning guides with harsh tools that scratch the crowned surface and hurt its centering action']::text[],ARRAY['Explaining how a machine keeps tape aligned to the heads','Tracing tape weave or level wander to a worn guide','Inspecting guides during transport maintenance']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='58b9bb19-c308-51f3-9a3d-094c6bd3b6f2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crowned guide'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '58b9bb19-c308-51f3-9a3d-094c6bd3b6f2','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='58b9bb19-c308-51f3-9a3d-094c6bd3b6f2' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67069343-f8ac-5b28-9d9c-e79dc916a94a','Cue track','An auxiliary longitudinal track carrying non-program signals such as cue tones, sync, or timecode, kept separate from the program audio. On the NAB standard broadcast cartridge, the cue track holds cue tones (a 1 kHz primary/stop tone, a 150 Hz secondary/end-of-message tone, and an 8 kHz tertiary tone) used to stop, cue, and control the cartridge; a mono cart carries one program track plus one cue track, and a stereo cart two program tracks plus one cue track.','A cue track is an extra strip on the tape for control signals, not music. On broadcast carts it holds beep tones. A 1 kilohertz tone marks the start and stops the cart at the right place. Other tones flag the end or trigger events. The music tracks stay separate.','It lets machines automatically cue, stop, and trigger playback without putting control tones into the program audio. It exists so cueing and automation can ride alongside the recording, out of the way of the sound.','In radio automation, an operator records a 1 kHz stop tone on the cue track at the top of a cart so it re-cues to the start after playing, and secondary tones can fire the next event.','Track formats',ARRAY['Center track','Timecode','Cue tone','Guard band','Sync track','Tape cartridge']::text[],ARRAY['Recording program audio onto the cue track, or letting cue tones bleed into the program tracks','Forgetting to record the 1 kHz stop tone, so a cartridge never re-cues to its start','Confusing the cue track with a normal audio track and expecting it to carry music']::text[],ARRAY['Cueing a jingle cart to stop and re-cue at the right point','Adding secondary cue tones to trigger the next event in automation','Transferring old carts and decoding what the cue-track tones meant']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67069343-f8ac-5b28-9d9c-e79dc916a94a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue track'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
