INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3c2eb1a9-dc5c-508a-bd8c-73669dcb81ac','DC erasure','Erasing or resetting recorded tape by applying a steady (direct-current) magnetic field, for example from a DC-energized erase head or a permanent magnet, which drives the coating toward saturation in one direction. Unlike AC erasure, which uses a strong alternating field that decays to leave the domains randomized and the tape quiet, DC erasure leaves the tape magnetized in one polarity and therefore much noisier (high DC noise).','DC erasure wipes tape using a steady magnetic field in one direction. It does clear the old signal, but it leaves the tape magnetized one way. That makes it much noisier than the normal method. The better way uses a shrinking back-and-forth field that leaves the tape quiet.','It removes a previous recording, but because it saturates the tape one way it is used only where noise does not matter or occurs by accident; quality recording uses AC erasure for a quiet result. Understanding it explains why AC erase and bias are used.','A technician recognizes DC erasure as the cause of unusually high tape noise, often from a faulty erase oscillator running as DC or from a magnetized head or tool leaving a one-directional field on the tape.','Erasure and bias',ARRAY['DC noise','AC bias','Erase head','Coercivity','Degausser dwell','Bias']::text[],ARRAY['Expecting DC erasure to leave tape as quiet as AC erasure, when it leaves the tape much noisier','UNSAFE: Using a magnetized tool or permanent magnet near tape or heads, which DC-magnetizes them; keep magnets away and demagnetize heads and tools with a proper AC degausser','Assuming any erasure is equal, ignoring that AC erasure randomizes the domains while DC saturates them']::text[],ARRAY['Explaining sudden high noise from a machine whose AC erase supply has failed','Understanding why a permanent-magnet eraser leaves a noisy tape','Teaching why AC bias and AC erase are used instead of DC']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3c2eb1a9-dc5c-508a-bd8c-73669dcb81ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('DC erasure'),'[^a-z0-9]','','g'));
