INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '61cfd218-e497-5b91-ad7b-f92cb7be56b5','DC noise','The excess playback noise produced when tape is magnetized by a direct-current (unidirectional) field, as from DC erasure, a magnetized head, or DC applied to a record head, rather than being AC-erased. It arises from the non-uniform size, distribution, and packing of the magnetic particles and can raise the noise floor by up to about 10 dB over that of blank, AC-erased tape.','DC noise is extra hiss on tape that got magnetized in one steady direction. It happens after DC erasure or from a magnetized head. The uneven mix of tiny magnetic particles creates the noise. It can be about 10 decibels louder than a normal blank tape''s hiss.','The term explains why one-directional magnetizing makes tape noticeably noisier and why AC erasure and demagnetized heads matter. It helps diagnose a raised noise floor.','When a machine''s noise floor rises, a technician suspects DC noise from a magnetized head and demagnetizes the heads and tape path with a proper degausser.','Tape noise',ARRAY['DC erasure','Modulation noise','Head magnetization','AC bias','Degausser dwell','Noise floor']::text[],ARRAY['Blaming raised hiss on the tape stock when a DC-magnetized head is adding DC noise','Skipping regular head demagnetizing, letting head magnetization build up and add noise','Confusing steady DC noise with modulation noise, which rides on the recorded signal']::text[],ARRAY['Tracking down a rising noise floor on a tape machine','Demagnetizing heads to cure added hiss','Explaining why AC-erased tape is quieter than DC-erased tape']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='61cfd218-e497-5b91-ad7b-f92cb7be56b5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('DC noise'),'[^a-z0-9]','','g'));
