INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '86c718e8-e21c-5658-8fcd-e570135f8564','DIN tape equalization','The German DIN 45513 tape equalization standard, which for professional speeds specifies the same replay time constants as the IEC1/CCIR curve (for example a 35 us high-frequency time constant and no low-frequency time constant at 15 in/s), as opposed to the American NAB curve. In practice DIN, CCIR, and IEC (IEC1) name the same European equalization family.','DIN is a German tape tuning standard. It sets how a machine boosts or cuts tones on playback. For pro speeds it matches the CCIR and IEC European standard. It differs from the American NAB standard, so you must pick the right one.','It defines a common record and replay curve so European tapes play back flat and line up with calibration. It exists to standardize tonal balance across machines and studios.','When a tape box is marked DIN or CCIR, the engineer selects the IEC/CCIR equalization on the machine and aligns to a matching calibration tape before transfer.','Tape equalization',ARRAY['CCIR equalization','NAB equalization','IEC equalization','Calibration tape','Reproduce head','Tape speed']::text[],ARRAY['Treating DIN as a different curve from CCIR/IEC, when for these speeds they are the same standard','Playing a DIN/CCIR tape with NAB selected, which shifts the tonal balance','Forgetting that the correct time constants change with tape speed']::text[],ARRAY['Setting equalization for a tape marked DIN 45513','Matching a European archival tape''s standard on a reproducer','Explaining why DIN, CCIR, and IEC labels mean the same equalization']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='86c718e8-e21c-5658-8fcd-e570135f8564' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('DIN tape equalization'),'[^a-z0-9]','','g'));
