INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f1f1807-d9e2-5c16-9a80-99df8a88962a','Dancer arm','A spring-loaded, pivoting tension arm (also called a tension or swing arm) that rides against the tape and moves with changes in tape tension; its position is sensed and fed to the reel-motor servo, which adjusts torque to keep tension constant. The dancer arm also buffers tension transients during starts and stops by supplying or taking up a little slack tape.','A dancer arm is a spring-loaded arm that leans on the moving tape. It moves in and out as the tape''s pull changes. A sensor reads its position and tells the reel motors to keep the pull steady. It also smooths sudden tugs when the tape starts or stops.','It senses tape tension and lets the servo hold it constant, and it cushions the jolt of starting and stopping. It exists to keep tension steady and protect the tape from sudden shocks.','During alignment a technician checks that the dancer arm moves freely and sets the servo so the arm sits at its correct position for the specified tape tension.','Tape transport',ARRAY['Constant-tension transport','Reel servo','Tape tension','Closed-loop transport','Capstan','Flutter']::text[],ARRAY['Overlooking a bent or sticking dancer arm, which feeds the servo wrong tension information','Setting tension without checking the arm''s resting position against the machine''s spec','Assuming the dancer arm only guides the tape, when it also senses tension and buffers start/stop shocks']::text[],ARRAY['Adjusting the tension servo during a machine alignment','Diagnosing tension or flutter faults traced to a sticking arm','Protecting fragile tape from tension spikes at start and stop']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f1f1807-d9e2-5c16-9a80-99df8a88962a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dancer arm'),'[^a-z0-9]','','g'));
