WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f1f1807-d9e2-5c16-9a80-99df8a88962a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2e5ae56a-7db4-5536-95d5-086d7623d18e','Degausser dwell','The interval during bulk erasure that the tape (or head or tool being demagnetized) remains within the strong alternating field of the degausser, long enough for the AC field to cycle through and reorient the magnetic domains before the item is slowly withdrawn. Adequate dwell followed by slow withdrawal to a distance, with the degausser still energized, leaves the domains randomized and the medium demagnetized.','Degausser dwell is how long the tape stays in the eraser''s strong magnetic field. It must stay long enough for the shaking field to scramble the magnetism. Then you pull it away slowly while the eraser is still on. Pulling away slowly leaves the tape quiet and clean.','Enough dwell and a slow withdrawal ensure the field fully randomizes the domains, giving complete, low-noise erasure. Too little dwell or a fast pull-away can leave signal or a strong one-directional magnetization.','When bulk-erasing tape, the operator holds or rotates the reel in the field for a moment, then draws it several feet away before switching off, so the tape erases fully and quietly.','Maintenance',ARRAY['DC erasure','DC noise','Erase head','Head magnetization','Coercivity','Bulk eraser']::text[],ARRAY['UNSAFE: Switching the degausser off or stopping while still close to the tape, which strongly magnetizes it in one direction; withdraw at least about three feet before removing power','UNSAFE: Running a mains-powered bulk eraser past its duty cycle so it overheats; follow the maker''s on-time limit and let it cool before reuse','Giving too little dwell or pulling away too fast, so the tape is only partly erased','Bulk-erasing near working media, magnetic cards, or watches, wiping or damaging them by accident']::text[],ARRAY['Bulk-erasing a reel of tape for reuse','Demagnetizing tape heads with a hand degausser','Explaining why a reel came out noisy after a rushed erase']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2e5ae56a-7db4-5536-95d5-086d7623d18e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Degausser dwell'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2e5ae56a-7db4-5536-95d5-086d7623d18e','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2e5ae56a-7db4-5536-95d5-086d7623d18e' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ef3ac996-ac4b-54b0-ad71-957433153585','Degausser withdrawal','The final stage of demagnetizing a tape machine''s heads and metal guides, in which the energized degausser (head demagnetizer) is drawn slowly away from the components out to a distance before it is switched off, so that its alternating magnetic field decays gradually toward zero rather than collapsing abruptly. Withdrawing slowly leaves the head cores and guides with no net residual magnetization.','A demagnetizer wipes stray magnetism off tape heads. You must pull it away slowly before you turn it off. Moving it far away lets its magnetic field fade to nothing. If you switch it off too close, it can magnetize the heads instead.','It lets the degausser''s alternating field fade smoothly as the tool leaves the heads, so the metal parts end up demagnetized rather than freshly magnetized by a switching surge. This protects high-frequency response and keeps the noise floor low.','A technician switches the degausser on well away from the machine, passes it slowly over each head and guide, then retreats slowly to arm''s length before switching it off.','Tape Machine Maintenance',ARRAY['Head demagnetization','Erase head','Residual magnetization','Tape head','Bulk eraser','Erasure ratio']::text[],ARRAY['UNSAFE: Switching the degausser on or off close to the heads, which sends a magnetizing pulse into the cores that can exceed what the tool can later remove','UNSAFE: Running a mains-powered degausser for long unbroken periods, letting the coil overheat; observe the manufacturer''s duty-cycle limit','Withdrawing too quickly, so the collapsing field leaves residual magnetism behind','Leaving recorded master tapes nearby, where the strong field can partially erase them']::text[],ARRAY['Routine head demagnetization before an alignment or a critical mastering session','Servicing a machine that shows rising high-frequency loss and hiss from magnetized heads','Archival transfer work where a magnetized head could damage an irreplaceable tape']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ef3ac996-ac4b-54b0-ad71-957433153585' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Degausser withdrawal'),'[^a-z0-9]','','g'));
