INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '220d6ee4-e67e-55ea-8704-5610aa4e8997','Differential head wear','Uneven abrasion of a magnetic head''s contact face, where some regions—one track, one side of the gap, or the leading versus trailing edge—wear faster than others because of asymmetric tape tension, wrap, azimuth, or an abrasive tape formulation. The result is an irregular head contour, degraded head-to-tape contact, and loss of high-frequency response.','Tape is slightly rough and slowly grinds down the tape head. Sometimes one part of the head wears faster than the rest. This uneven wear changes the head''s shape. It hurts the sound, mostly the high notes.','Spotting differential wear tells a technician that head-to-tape geometry has drifted enough to need lapping or replacement. Catching it early prevents contact loss that quietly ruins frequency response.','A technician inspects the head face under magnification and checks for asymmetric level or high-frequency loss between tracks, then decides whether to lap or replace the head.','Tape Heads',ARRAY['Tape head','Head lapping','Azimuth','Head-to-tape contact','Differential tension','Gap depth']::text[],ARRAY['Blaming falling high-frequency output on the tape or on alignment when the real cause is an unevenly worn head contour','Assuming both stereo tracks wear equally, so ignoring level differences that signal one-sided wear','Continuing to lap a head that has already worn past its usable gap depth']::text[],ARRAY['A stereo master shows one channel noticeably duller than the other on high frequencies','Evaluating a used machine''s head life before purchase','Deciding whether to relap or replace heads during a restoration']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='220d6ee4-e67e-55ea-8704-5610aa4e8997' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Differential head wear'),'[^a-z0-9]','','g'));
