SELECT '220d6ee4-e67e-55ea-8704-5610aa4e8997','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='220d6ee4-e67e-55ea-8704-5610aa4e8997' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '35d315f9-bcce-5471-9566-4af9e4280520','Differential tension','A controlled difference in tape tension between two points in the transport—typically between the supply (hold-back) side and the take-up side, or between the two capstans of a closed-loop transport—maintained so the tape stays taut and in firm, uniform contact with the heads regardless of how the reel packs change. It keeps head contact and guiding stable across a whole reel.','Tape must stay tight and flat against the heads as it moves. Machines keep a little more pull on one side than the other. This tension difference holds the tape steady and in good contact. It stops the sound from wandering as the reels empty and fill.','It keeps head-to-tape contact and tape guiding stable by ensuring the take-up side always pulls slightly against the hold-back tension. This prevents slack, spilling, and contact loss as the reel diameters change.','A technician measures and sets hold-back and take-up tensions with a tension gauge so the difference falls within the service manual''s spec, then confirms even packing and steady contact.','Tape Transport',ARRAY['Back tension','Hold-back tension','Dual-capstan transport','Tape pack','Head-to-tape contact','Reel motor']::text[],ARRAY['Setting take-up tension so high that the tape packs too tightly and stresses the edges','Allowing too little hold-back tension, causing slack, poor head contact, and dropouts','Ignoring that tension changes between a full reel and a nearly empty one']::text[],ARRAY['Calibrating supply and take-up torque during a transport service','Diagnosing intermittent high-frequency dropouts caused by poor head contact','Setting up a closed-loop machine for archival playback of fragile tape']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='35d315f9-bcce-5471-9566-4af9e4280520' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Differential tension'),'[^a-z0-9]','','g'));
