SELECT '35d315f9-bcce-5471-9566-4af9e4280520','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='35d315f9-bcce-5471-9566-4af9e4280520' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b47137c1-607c-54af-bf90-2bc963adcedb','Domain orientation','The alignment direction of the magnetic domains, and of the acicular (needle-shaped) magnetic particles that carry them, within a tape''s coating. In analog audio tape the particles are oriented longitudinally—along the direction of travel—during manufacture, and the recorded signal is stored as patterns of domain magnetization along that axis; an AC erase field randomizes those orientations to remove any recording.','Tape is coated with tiny needle-shaped magnetic bits. Recording sets which way their magnetism points. These little magnets are lined up along the length of the tape. Erasing scrambles their directions so no signal is left.','Lining the particles up along the tape lets a track store and read back more signal, giving higher output and a better signal-to-noise ratio than a randomly oriented coating. It is set at manufacture and defines the tape''s recording behavior.','Technicians use it indirectly: it underlies why a tape has a correct playing side and direction, why a bulk eraser randomizes the coating, and why output depends on the coating''s remanence.','Magnetic Recording',ARRAY['Coercivity','Remanence','Magnetic particle','Erasure','Bias','Fluxivity']::text[],ARRAY['Confusing recording with physically moving the particles; only their magnetic direction changes','Thinking erasure strips off the coating rather than randomizing domain directions','Assuming any magnetic coating records equally well regardless of particle orientation']::text[],ARRAY['Explaining why oriented tape outputs more signal than an unoriented coating','Understanding how an AC erase head clears a tape for reuse','Interpreting the remanence and coercivity figures on a tape datasheet']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b47137c1-607c-54af-bf90-2bc963adcedb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Domain orientation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b47137c1-607c-54af-bf90-2bc963adcedb','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b47137c1-607c-54af-bf90-2bc963adcedb' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '14b5aa50-dd0b-5259-a127-bcd98243557d','Dual-capstan transport','A tape-drive design—also called a closed-loop transport—that uses two capstan and pinch-roller pairs, one before and one after the head block, to grip the tape and isolate the head zone from tension disturbances coming from the supply and take-up reels. The two capstans are driven so the span across the heads is held at a constant, tightly controlled tension, reducing flutter and improving speed stability.','A capstan is the spinning shaft that pulls tape past the heads. A dual-capstan machine uses two of them, one on each side of the heads. Together they hold the tape at steady tension over the heads. This shields the tape from tug and wobble from the reels, so playback stays stable.','Trapping the head region between two capstans holds tension there constant no matter what the reels do, which lowers wow and flutter and steadies head-to-tape contact. That stability is prized on mastering and archival machines.','On closed-loop machines such as Ampex and Studer masters, a technician checks that both capstans and pinch rollers grip properly and that the tension across the loop meets the manual''s spec.','Tape Transport',ARRAY['Capstan','Pinch roller','Differential tension','Scrape flutter','Wow and flutter','Tape transport','Closed-loop dual capstan (alternate name)']::text[],ARRAY['Assuming both capstans run at exactly the same surface speed; a small deliberate difference keeps the loop taut','Neglecting the second pinch roller when cleaning or servicing, causing slip and flutter','Threading the tape outside the closed loop, which defeats the isolation']::text[],ARRAY['Servicing a mastering recorder for the lowest possible flutter','Playing back a fragile archival tape that benefits from steady tension','Comparing a single-capstan deck against a closed-loop transport for stability']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='14b5aa50-dd0b-5259-a127-bcd98243557d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dual-capstan transport'),'[^a-z0-9]','','g'));
