INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3476fd41-d9bf-5110-bb6a-2fb08477faab','Edge guiding','A method of laterally positioning the tape by referencing one or both of its physical edges against fixed guides or flanged rollers, so the tape tracks at the correct height across the heads. Because narrow-track recorders depend on precise lateral position, edge guiding demands straight, undamaged tape edges; nicks, curl, or stretch cause mistracking and level or azimuth errors.','Tape must ride at exactly the right height across the heads. Edge guiding does this by pressing the tape''s edge against fixed guides. It works only if the edges are smooth and straight. A nicked or bent edge makes the tape wander and lose signal.','It keeps the recorded tracks aligned with the head gaps by controlling the tape''s side-to-side position, which is essential once track widths are narrow. Good edges are what make this reliable.','A technician sets guide height and checks the tape rides without climbing or curling; tapes with damaged edges are handled with care because edge guiding will mistrack them.','Tape Transport',ARRAY['Tape guide','Flange rub','Azimuth','Tracking','Reel flange','Tape transport']::text[],ARRAY['Using reels with bent or nicked flanges, which damage the very tape edge that guiding relies on','Setting guide height by eye instead of to spec, causing tracking and azimuth errors','Forcing a cupped or curled tape through tight guides, worsening the edge damage']::text[],ARRAY['Aligning tape height so playback tracks correctly over the recorded signal','Transferring an archival tape whose edges are already damaged','Diagnosing intermittent level loss caused by the tape riding up on a guide']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3476fd41-d9bf-5110-bb6a-2fb08477faab' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edge guiding'),'[^a-z0-9]','','g'));
