INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '744ed9fb-bc66-5c92-b813-ede622b952d4','Elevated operating level','A reference recording level (reference fluxivity) set higher than the older standard operating levels, expressed in nanowebers per meter (nWb/m), so a machine lays more signal onto modern high-output tape before saturation and improves the signal-to-noise ratio. Common elevated references are 355 nWb/m and 520 nWb/m, several decibels above the older 185 nWb/m and 250 nWb/m standards.','Operating level is how much signal a machine puts on tape at its zero mark. Newer tapes can hold more signal without distorting. An elevated level uses that extra headroom by recording hotter. Recording hotter lifts the music further above the tape hiss.','It exploits the higher output of modern tape formulations to push the recording further above the tape''s noise floor, raising the signal-to-noise ratio without adding distortion. This is why higher references came into use as tapes improved.','During alignment a technician uses a calibration tape and sets the machine''s meters and fluxivity so 0 VU corresponds to the chosen elevated reference, such as 355 nWb/m for a +6 tape.','Tape Machine Alignment',ARRAY['Reference fluxivity','Operating level','Calibration tape','Signal-to-noise ratio','Tape saturation','VU meter']::text[],ARRAY['Aligning to an elevated level on a tape not rated for it, causing saturation and distortion','Playing a tape recorded at an elevated level on a machine calibrated to 185 nWb/m, so the levels read wrong','Confusing operating level (fluxivity) with the meter''s reference point or with bias']::text[],ARRAY['Calibrating a multitrack for a session on high-output tape','Reading a tape-box note like ''+6 / 355 nWb/m'' and matching the playback machine','Improving the signal-to-noise ratio on a mastering recorder']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='744ed9fb-bc66-5c92-b813-ede622b952d4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Elevated operating level'),'[^a-z0-9]','','g'));
