INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '86a553d0-1ac5-5b2e-bf74-e2e0e6e2281a','Equalization ambiguity','The uncertainty, when preparing to replay an analog tape, over which recording equalization standard (for example NAB or IEC/CCIR) was used to make it, because the tape carries no embedded metadata identifying the curve. At a given speed the standards differ, so choosing the wrong one distorts the tonal balance; with undocumented tapes the correct curve may have to be inferred by ear or from context.','Tape recorders shape the tone during recording using a set curve, called equalization. Rival standards exist, one from American broadcasters and one from a European body. The tape itself does not say which was used. So for old, unlabeled tapes you must judge by ear or from clues.','Recognizing this ambiguity forces a technician to determine or estimate the record curve before replay, since equalization applied when recording must be complemented correctly on playback for flat response. It is a core problem in archival transfer.','Faced with an undocumented archival tape, a technician tries the likely curve for the speed and origin, compares the two, and keeps the one giving the most natural, flat balance.','Tape Machine Alignment',ARRAY['NAB equalization','IEC equalization','Replay equalization','Equalization misdecode','Time constant','Tape speed']::text[],ARRAY['Assuming every 15 in/s tape is NAB, or every European tape is IEC, without checking','Ignoring the recording''s origin and date, which often point to the likely standard','Failing to document the chosen replay curve, leaving the transfer unrepeatable']::text[],ARRAY['Digitizing an undocumented reel from a private collection','Deciding replay EQ for a tape recorded abroad','Reconciling a tape that sounds wrong on a NAB-only machine']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='86a553d0-1ac5-5b2e-bf74-e2e0e6e2281a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Equalization ambiguity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '86a553d0-1ac5-5b2e-bf74-e2e0e6e2281a','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='86a553d0-1ac5-5b2e-bf74-e2e0e6e2281a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f20aa648-9133-5456-bf4d-b2f24c53241e','Equalization misdecode','Replaying a tape with a playback equalization curve that does not match the one used at recording, so the reproduce-side equalization fails to complement the record-side pre-emphasis and the output has a tilted or uneven frequency response—for example excess or deficient bass and treble. It is the audible consequence of selecting the wrong standard (NAB versus IEC/CCIR) or the wrong speed''s curve.','A tape''s tone is shaped one way when recorded and un-shaped on playback. If the playback setting is wrong, the two do not cancel out. The sound then comes out too bright or too dull. That mismatch is an equalization misdecode.','Understanding misdecode lets a technician read a tonal error as a decoding mismatch rather than a fault in the tape or heads, and fix it by choosing the correct curve. It separates a setup error from real damage.','When a transfer sounds bass-heavy or dull, the technician switches the replay EQ standard or the speed setting and re-checks against a reference until the balance is right.','Tape Machine Alignment',ARRAY['Equalization ambiguity','NAB equalization','IEC equalization','Replay equalization','Pre-emphasis','Calibration tape']::text[],ARRAY['Trying to ''correct'' a misdecoded tape with tone controls instead of selecting the right curve','Leaving the machine on the wrong speed''s EQ, which also mis-shapes the response','Confusing a misdecode with worn heads or with a bad azimuth setting']::text[],ARRAY['A NAB tape played on an IEC setting sounds wrong in the bass','Verifying replay EQ against a calibration tape before a transfer','Troubleshooting a dull-sounding archival digitization']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f20aa648-9133-5456-bf4d-b2f24c53241e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Equalization misdecode'),'[^a-z0-9]','','g'));
