SELECT 'f20aa648-9133-5456-bf4d-b2f24c53241e','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f20aa648-9133-5456-bf4d-b2f24c53241e' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '650472fc-e114-51bc-b4a3-c8f1d198be91','Erase depth','The depth into the tape''s magnetic coating to which the erase field effectively removes recorded magnetization. Complete erasure requires the field to reach through the full coating thickness, which is why erase-head gaps are made several times longer than record-head gaps so their field penetrates deeper.','The signal on tape is stored through the whole thickness of the coating. To wipe it, the erase field must reach all the way down. Erase depth is how deep that wiping reaches. If it is too shallow, buried signal survives.','Adequate erase depth ensures the entire coating is cleared, so no old recording bleeds through under a new one and the erasure ratio stays high. It is why erase heads are built with wide gaps.','A technician who hears an old signal faintly under a new recording suspects shallow erase depth from weak erase current, a worn erase head, or thick tape.','Tape Erasure',ARRAY['Erase head','Erasure ratio','Erase-field penetration','Coating thickness','Bias','Coercivity']::text[],ARRAY['Assuming surface erasure means the deeper coating is clear too','Under-setting the erase-oscillator current, so thick or high-coercivity tape is only partly erased','Expecting a record head to erase fully; its short gap penetrates too shallowly']::text[],ARRAY['Bleed-through of a previous take heard beneath a new recording','Setting up erase current for a high-output, thicker tape','Evaluating why a reused tape has a raised noise floor']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='650472fc-e114-51bc-b4a3-c8f1d198be91' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Erase depth'),'[^a-z0-9]','','g'));
