SELECT '650472fc-e114-51bc-b4a3-c8f1d198be91','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='650472fc-e114-51bc-b4a3-c8f1d198be91' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c76c07ed-47aa-501d-8302-050454184559','Erase-field penetration','The extent to which the alternating magnetic field from the erase head reaches into the depth of the tape coating. Penetration increases with a longer head gap and stronger erase current and must exceed both the coating thickness and the tape''s coercivity for complete erasure; the field also weakens as the tape moves past the gap, giving the gradual decay needed to leave the coating demagnetized.','An erase head makes a strong flipping magnetic field. That field has to sink into the coating to wipe the signal. How far it reaches is its penetration. A bigger head gap and more current push the field deeper.','Enough field penetration guarantees the whole coating depth meets the erasing field, so magnetization at every level is randomized and removed. Too little leaves buried signal behind.','When erasure is incomplete on thick or high-coercivity tape, a technician checks the erase current and head condition, since both set how deeply the field reaches.','Tape Erasure',ARRAY['Erase head','Erase depth','Coercivity','Erasure ratio','Coating thickness','Bias']::text[],ARRAY['Thinking a bigger gap alone erases; the field strength must also exceed the tape''s coercivity','Overlooking a worn or partly shorted erase head that weakens the field','Using a record head''s field to try to erase; its penetration is far too shallow']::text[],ARRAY['Erasing high-coercivity tape that resists a marginal erase field','Diagnosing residual signal after a full pass through the erase head','Comparing erase-head gap sizes when specifying a machine']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c76c07ed-47aa-501d-8302-050454184559' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Erase-field penetration'),'[^a-z0-9]','','g'));
