WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c76c07ed-47aa-501d-8302-050454184559' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1a8297da-f6a0-59b2-a269-9efefcfad43b','Erased-tape noise','The residual background noise reproduced from a blank tape that has been erased (by an erase head or bulk eraser) with no signal recorded—the intrinsic noise floor of the demagnetized coating, arising from the random magnetization of its particles and from bias- and erase-related noise. It sets the lowest noise level, and thus the best signal-to-noise ratio, achievable with that tape and machine.','Even a wiped, blank tape is not perfectly silent. Its tiny magnetic bits sit in random directions and make a faint hiss. This is erased-tape noise. It sets how quiet the tape can ever be.','The erased-tape noise floor is the reference against which signal-to-noise ratio is measured and against which the benefit of recording at an elevated level is judged. It defines the tape''s quietest state.','A technician measures the playback level of freshly erased tape to characterize the machine-and-tape noise floor and to judge how clean the heads and erase stage are.','Tape Erasure',ARRAY['Signal-to-noise ratio','Erasure','Bias noise','Modulation noise','Elevated operating level','Remanence']::text[],ARRAY['Blaming the electronics for hiss that is actually the tape''s own erased-noise floor','Expecting bulk-erased tape to be completely silent','Confusing erased-tape noise with hum or with a magnetized-head problem']::text[],ARRAY['Measuring a machine''s signal-to-noise ratio on blank tape','Judging whether a reused tape is quiet enough for a new recording','Comparing the noise floor of different tape formulations']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1a8297da-f6a0-59b2-a269-9efefcfad43b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Erased-tape noise'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1a8297da-f6a0-59b2-a269-9efefcfad43b','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1a8297da-f6a0-59b2-a269-9efefcfad43b' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a9e7ad98-5ca9-5988-b37b-92cbd7afb930','Erasure ratio','A measure of how completely an erase process removes a recorded signal, expressed in decibels as the difference between the signal level before erasure and the residual level remaining after one pass through the erase field. A larger erasure ratio means more thorough erasure; professional erase systems achieve high ratios so no previous recording remains audible.','Erasing does not always remove every trace of a signal. The erasure ratio measures how much was taken away. It compares the signal before and after wiping, in decibels. A bigger number means a cleaner wipe.','It quantifies how well an erase head or bulk eraser works, so a technician can confirm that old material sits far enough below a new recording to be inaudible. It is a key spec for reusing tape.','When old program is faintly heard under new material, the technician suspects a low erasure ratio and checks erase current, head wear, and tape coercivity.','Tape Erasure',ARRAY['Erase head','Erase depth','Erase-field penetration','Bulk eraser','Coercivity','Erased-tape noise']::text[],ARRAY['Assuming any audible reduction means full erasure; only a large ratio guarantees inaudibility','Blaming print-through for bleed-through that is really poor erasure','Expecting a bulk eraser to match a high-coercivity tape it is under-powered for']::text[],ARRAY['Confirming a reused reel is clean enough for a new session','Specifying erase performance when evaluating a machine','Troubleshooting previous-take bleed-through under a new recording']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a9e7ad98-5ca9-5988-b37b-92cbd7afb930' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Erasure ratio'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a9e7ad98-5ca9-5988-b37b-92cbd7afb930','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a9e7ad98-5ca9-5988-b37b-92cbd7afb930' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bb5d8290-2bb4-5320-b071-8dacd3f2325e','Flange rub','Contact and rubbing between the edge of the tape and the inner face of a reel flange, caused by an uneven tape pack, a deflected or bent flange, or careless handling, which abrades, creases, or curls the tape edge. Because recorders guide on the tape edge, flange-rub damage leads to mistracking, level loss, and dropouts.','A reel has side walls called flanges. If the tape rubs against them, its edge gets scuffed or bent. The recorder steers using that edge, so a damaged edge makes the tape wander. That causes lost signal and dropouts.','Recognizing flange rub tells a technician that reel or packing problems are damaging the tape edge, prompting better reels, hub support, and handling to protect the recording. It links a mechanical fault to an audible one.','A technician who sees a scalloped or dished tape pack, or hears edge-track dropouts, inspects for bent flanges and rewinds at proper tension to stop further rubbing.','Tape Handling',ARRAY['Reel flange','Tape pack','Edge guiding','Tape guide','Dropout','Differential tension']::text[],ARRAY['Grabbing a reel by its flanges, deflecting them so they press on the tape edge','Storing tape wound unevenly, letting the pack stand proud and rub the flange','Reusing bent or nicked reels that keep damaging the tape edge']::text[],ARRAY['An archival reel arrives with a dished pack and creased edges','Edge-track dropouts appear after rough shipping','Choosing to rewind onto a true reel before a transfer']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bb5d8290-2bb4-5320-b071-8dacd3f2325e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flange rub'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bb5d8290-2bb4-5320-b071-8dacd3f2325e','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bb5d8290-2bb4-5320-b071-8dacd3f2325e' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3ea8704f-45f7-5b63-9c8f-8d4fc13fa529','Flutter idler','A small, low-mass rotating idler (guide roller), often on a jewel bearing, placed in the tape path—typically between the record and reproduce heads—to shorten the unsupported tape span and damp longitudinal (scrape) flutter. Because it turns with the tape and has no motion relative to it, it blocks the frictional vibrations that fixed guides and heads excite in the tape.','As tape drags over fixed heads and guides, it can shake lengthwise and add a fine warble. A flutter idler is a tiny spinning roller placed between the heads. It turns with the tape, so it does not scrape. It calms those vibrations for cleaner sound.','It reduces scrape flutter by cutting the free tape length and interrupting the friction-driven longitudinal vibrations that travel along the tape. This matters most for clean high frequencies on master tapes.','A technician cleans the idler and checks it spins freely on its bearing; a sticky or seized idler adds flutter instead of removing it.','Tape Transport',ARRAY['Scrape flutter','Wow and flutter','Tape guide','Capstan','Dual-capstan transport','Head-to-tape contact']::text[],ARRAY['Letting the idler''s bearing dry out or clog, so it drags and adds flutter','Assuming it is a driven capstan; it is a free-spinning, low-inertia guide','Skipping it when cleaning the tape path, leaving residue that causes stick-slip']::text[],ARRAY['Servicing a mastering deck to minimize scrape flutter on high frequencies','Tracing a warbly high-frequency tone to a seized flutter idler','Cleaning the tape path between the heads before a critical transfer']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3ea8704f-45f7-5b63-9c8f-8d4fc13fa529' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Flutter idler'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3ea8704f-45f7-5b63-9c8f-8d4fc13fa529','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3ea8704f-45f7-5b63-9c8f-8d4fc13fa529' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9c2a19cf-79a0-5c35-adb7-20315ad31424','Full-track mono','A monophonic tape format in which a single audio channel is recorded across essentially the full width of the tape, using one record/reproduce head that spans the whole tape width. Because it uses the largest possible track area, it yields the highest signal-to-noise ratio and headroom of the common formats, but carries only one channel and plays in a single direction.','Full-track mono puts one sound channel across the whole width of the tape. Using the whole width gives a strong, quiet signal. But it holds only one channel and plays one way.','It maximizes signal-to-noise ratio and headroom for a single channel by using the entire tape width, which is why it was the standard for mono mastering and broadcast. The wide track also makes the recorded flux easy for a reproduce head to read at high level.','An archivist transferring an old mono master selects a full-track head or format so the reproduce head reads the entire recorded width rather than a fraction of it.','Track format',ARRAY['Half-track mono','Half-track stereo','Guard track','House equalization','Head penetration']::text[],ARRAY['Playing a full-track recording on a two-track or quarter-track head, which reads only part of the width and causes level and fringing errors','Assuming full-track refers to stereo, when it means one channel across the full tape width','Forgetting that fringing correction differs when full-track material is played on a narrower reproduce head']::text[],ARRAY['Digitizing a 1950s full-track mono master for archival preservation','Choosing the correct head block when a machine offers interchangeable full-track and two-track heads','Explaining why a full-track transfer has lower noise than the same content on a quarter-track deck']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9c2a19cf-79a0-5c35-adb7-20315ad31424' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Full-track mono'),'[^a-z0-9]','','g'));
