WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9c2a19cf-79a0-5c35-adb7-20315ad31424' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1c63d413-5e49-55a3-8e38-f5646b316e7d','Gap erosion','The progressive wearing of a magnetic head at the gap region caused by abrasive tape contact, in which the pole tips recede and the gap edges round off so the effective gap length grows and gap depth changes. The enlarged effective gap increases gap-length loss and degrades high-frequency reproduce response.','The tape slowly sands the head where the tiny gap sits. Over time the gap edges wear and round off. A wider gap makes the head lose high notes.','As a wear mechanism, it defines a head''s useful service life and signals when relapping or replacement is due. Recognizing it lets a technician trace high-frequency loss to the head rather than to the tape or alignment.','A maintenance technician who measures falling high-frequency output and sees wear at the gap edges under magnification schedules the head for relapping or replacement.','Head wear',ARRAY['Gap-length loss','Head-face grooving','Head contour resonance','Head penetration','Head clogging']::text[],ARRAY['Blaming high-frequency loss on old tape when the head gap has eroded and widened','Continuing to use a head that has worn through at the gap, which the MRL alignment procedure specifically checks for','Assuming a head lasts indefinitely, when abrasive tape steadily erodes the gap']::text[],ARRAY['Diagnosing gradual treble loss on a heavily used studio machine','Inspecting a head for gap wear-through during pre-transfer alignment','Deciding whether a vintage machine''s heads can be relapped or must be replaced']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1c63d413-5e49-55a3-8e38-f5646b316e7d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gap erosion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1c63d413-5e49-55a3-8e38-f5646b316e7d','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1c63d413-5e49-55a3-8e38-f5646b316e7d' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '70062d72-f298-5a25-8908-1cf65294ef24','Gap-azimuth interaction','The combined high-frequency loss that arises when a tilted reproduce gap (azimuth error) interacts with track width and recorded wavelength. Azimuth loss follows a sin(x)/x law in which x is proportional to track width multiplied by the tangent of the azimuth angle divided by wavelength, so a gap tilted relative to the recorded tracks causes phase cancellation across the track that worsens with wider tracks and shorter wavelengths.','The head''s tiny gap must sit square to the tape. If it tilts, the top and bottom of the track fall out of step. High notes then cancel, and wider tracks make it worse.','It explains why precise azimuth alignment matters most for wide tracks and high frequencies, guiding how tightly a head must be set. Understanding the interaction tells a technician which recordings are most sensitive to azimuth error.','An engineer aligns azimuth by peaking the high-frequency output of a calibration tape, knowing wider tracks demand tighter tolerance than the roughly one arc-minute standard.','Head alignment',ARRAY['Gap-length loss','Guard track','Half-track stereo','Head penetration','Full-track mono']::text[],ARRAY['Setting azimuth by eye instead of peaking high-frequency reproduce level with a test tape','Ignoring that a wide-track format cancels highs far more severely than a narrow track for the same tilt','Confusing azimuth error (a gap tilt) with gap-length loss (set by gap size)']::text[],ARRAY['Aligning playback azimuth to an unknown tape by maximizing high-frequency output','Explaining severe treble loss and phase error between channels of a misaligned stereo tape','Setting head azimuth on a two-inch multitrack where wide tracks tighten the tolerance']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='70062d72-f298-5a25-8908-1cf65294ef24' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gap-azimuth interaction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '70062d72-f298-5a25-8908-1cf65294ef24','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='70062d72-f298-5a25-8908-1cf65294ef24' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9eb95fdb-36b2-5c2a-b010-c08ec483461d','Gap-length loss','The high-frequency reproduce loss that occurs because a head''s finite gap length averages the tape flux over a span of the recording. It is described by 20 log of sin(x)/x, where x is proportional to gap length divided by wavelength, producing a first null when the recorded wavelength approximately equals the head''s effective gap length.','The head reads the tape through a tiny slot with real width. When a wave gets as short as that slot, the head averages it out to almost nothing. So the shortest waves, the high notes, are lost.','It sets the fundamental high-frequency limit of the reproduce head, which is why playback heads use very short gaps. Knowing it lets a designer or technician predict where treble output falls away for a given gap and speed.','A technician chooses or evaluates a reproduce head by its gap length, understanding that a shorter gap extends high-frequency response at a given tape speed.','Reproduce losses',ARRAY['Gap-azimuth interaction','Head penetration','Head bump','Gap erosion','House equalization']::text[],ARRAY['Confusing gap-length loss, which is set by the gap, with spacing loss, which is set by tape-to-head separation','Assuming a narrower gap has no downside, when it also lowers head efficiency and output','Thinking gap-length loss affects recording the same way it affects reproduction']::text[],ARRAY['Predicting the treble roll-off of a machine at a lower tape speed','Comparing reproduce heads with different gap lengths for archival transfer','Explaining why worn, eroded gaps lose high frequencies as the effective gap grows']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9eb95fdb-36b2-5c2a-b010-c08ec483461d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gap-length loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9eb95fdb-36b2-5c2a-b010-c08ec483461d','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9eb95fdb-36b2-5c2a-b010-c08ec483461d' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f42c5b98-4061-573a-a47e-5632e83c5baf','Guard track','An unrecorded strip of tape (a guard band) left between adjacent recorded tracks, or between a track and the tape edge, to provide magnetic and mechanical isolation. It reduces crosstalk between channels and gives tolerance for small tracking and head-height misalignment, at the cost of narrowing the usable track width.','A guard track is an empty strip left between the recorded tracks. This blank space stops one channel leaking into the next. It also leaves room for small alignment errors.','It exists to keep channels isolated and to absorb minor mechanical misalignment between record and playback machines. The guard space is the trade-off that makes multi-track layouts reliable across different decks.','When setting up a two-track transfer, a technician relies on the guard band so slight head-height differences between machines do not pick up the neighboring track.','Track format',ARRAY['Half-track stereo','Half-track mono','Full-track mono','Gap-azimuth interaction','Head penetration']::text[],ARRAY['Assuming a wider guard band is free, when it narrows the track and lowers signal-to-noise ratio','Confusing the guard band between tracks with the unrecorded margin at the tape edge','Expecting different standard track widths (Ampex, NAB, IEC) to interchange without level or crosstalk error']::text[],ARRAY['Explaining why a quarter-inch two-track format leaves space between the two channels','Diagnosing channel crosstalk caused by head-height misalignment eating into the guard band','Choosing between Ampex, NAB, and IEC track-width standards during machine setup']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f42c5b98-4061-573a-a47e-5632e83c5baf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guard track'),'[^a-z0-9]','','g'));
