SELECT 'f42c5b98-4061-573a-a47e-5632e83c5baf','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f42c5b98-4061-573a-a47e-5632e83c5baf' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'be412359-3a18-5827-8cae-dc97a5c7be07','Guide chatter','Mechanical vibration and noise generated when tape sticks and slips against a fixed tape guide, exciting rapid longitudinal and lateral tape vibration. It is a guide-induced form of scrape flutter that frequency-modulates the recorded signal, typically producing modulation above about 100 Hz.','As tape drags over a fixed guide it can grab and release very fast. This makes the tape buzz or rattle against the guide. That vibration adds an unwanted warble to the sound.','Naming this fault helps a technician locate the source of flutter and noise in the tape path. Recognizing it points to remedies such as rotating guides or a scrape-flutter idler roller between the heads.','When a machine adds a warble that the capstan servo does not explain, a technician inspects the fixed guides for a sticky or grooved surface causing chatter.','Transport flutter',ARRAY['Head-face grooving','Head clogging','Gap-azimuth interaction','Head bump','Full-track mono']::text[],ARRAY['Blaming warble on the capstan or pinch roller when a sticky fixed guide is the real source','UNSAFE: Cleaning guides with a flammable solvent near a powered machine or ignition source instead of powering down and ventilating first','Leaving residue on a guide after cleaning, which can worsen the stick-slip that causes chatter']::text[],ARRAY['Tracing a high-frequency flutter to a worn stationary guide in the tape path','Fitting a rotating scrape-flutter idler between record and reproduce heads to reduce vibration','Cleaning and polishing tape guides during preventive maintenance to stop chatter']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='be412359-3a18-5827-8cae-dc97a5c7be07' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guide chatter'),'[^a-z0-9]','','g'));
