INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0455712b-fca9-5485-b481-c2eed3a08ba3','Half-track mono','A monophonic quarter-inch format that records a single track occupying roughly half the tape width along one edge, so the reel can be turned over and a second mono program recorded in the opposite direction on the other half. It is common on domestic and portable machines, doubling recording time per reel at the cost of narrower tracks than full-track.','Half-track mono records one channel on half the tape''s width. You can flip the reel and record the other half going back the other way. So one tape holds two separate mono passes.','It doubles the program time available on a reel by using each half of the tape for a separate one-way recording. This made it the practical choice for consumer and field mono machines.','An archivist playing a domestic half-track mono tape must know which half and which direction holds the wanted program before reading it with the correct head.','Track format',ARRAY['Half-track stereo','Full-track mono','Guard track','House equalization','Head penetration']::text[],ARRAY['Confusing half-track mono with half-track stereo, which records both halves in the same direction at once','Playing back the wrong half or wrong direction and capturing a reversed second program','Assuming half-track mono has the same signal-to-noise ratio as full-track, when the narrower track is noisier']::text[],ARRAY['Transferring a two-sided domestic mono reel that was recorded in both directions','Identifying an overlapping reversed program bleeding into a half-track mono transfer','Selecting the right head format when a machine supports both mono and stereo half-track']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0455712b-fca9-5485-b481-c2eed3a08ba3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Half-track mono'),'[^a-z0-9]','','g'));
