INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b176446-19e0-5b38-8680-3a29711ca5cd','Half-track stereo','A two-channel quarter-inch format that records left and right on two parallel tracks, each occupying roughly half the tape width and both running in the same direction, separated by a guard band. It is the professional and mastering stereo standard for quarter-inch tape, offering higher signal-to-noise ratio than quarter-track stereo.','Half-track stereo splits the tape into two wide tracks. One holds the left channel and one holds the right, both going the same way. The wide tracks give a clean, quiet stereo recording.','It provides high-quality two-channel recording by giving each channel a wide track, which is why it became the mastering and broadcast stereo standard. The wide tracks maximize signal-to-noise ratio while a guard band keeps the channels isolated.','For an archival stereo transfer, a technician fits a half-track stereo reproduce head and aligns both channels to a two-track calibration tape.','Track format',ARRAY['Half-track mono','Full-track mono','Guard track','Gap-azimuth interaction','House equalization']::text[],ARRAY['Playing a half-track stereo tape on a quarter-track head, which lands on the wrong track positions and picks up a reversed track','Assuming a half-track stereo reel can be flipped and reused like half-track mono','Ignoring that different standard track widths (Ampex, NAB, IEC) change level and crosstalk']::text[],ARRAY['Transferring a professional quarter-inch stereo master to digital','Aligning both channels of a stereo machine with a two-track reference tape','Diagnosing why a stereo tape plays with a faint reversed channel on the wrong head']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b176446-19e0-5b38-8680-3a29711ca5cd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Half-track stereo'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b176446-19e0-5b38-8680-3a29711ca5cd','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b176446-19e0-5b38-8680-3a29711ca5cd' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '17ec73e1-c70e-56a2-9036-32541a1d5b95','Head bump','Broad peaks and dips in the low-frequency reproduce response caused by the contour effect: at long wavelengths comparable to the physical dimensions of the head, flux wraps around the head core and reinforces or cancels, producing response undulations. The bumps shift up in frequency as tape speed increases and are characteristic of a given machine, speed, and format.','At low notes the magnetic wave on the tape is very long. The flux curls around the whole head and adds to itself unevenly. This makes gentle bumps and dips in the bass response.','Understanding head bump explains unavoidable low-frequency ripple in tape response and why it changes with speed. It guides realistic expectations for bass flatness rather than a fault to be fully corrected.','A mastering or transfer engineer allows for head bumps when judging low-frequency response and avoids chasing them with aggressive equalization.','Reproduce response',ARRAY['Head contour resonance','Gap-length loss','House equalization','Head penetration','Full-track mono']::text[],ARRAY['Trying to equalize head bumps perfectly flat, when they move with tape speed and format','Confusing a head bump with a monitor or room resonance in the control room','Expecting head bumps to be identical across different machines and speeds']::text[],ARRAY['Explaining a low-frequency ripple seen when sweeping a machine''s response','Comparing bass response between 15 and 30 inch-per-second transfers','Deciding how much low-end correction is realistic during an archival transfer']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='17ec73e1-c70e-56a2-9036-32541a1d5b95' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head bump'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '17ec73e1-c70e-56a2-9036-32541a1d5b95','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='17ec73e1-c70e-56a2-9036-32541a1d5b95' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ff1d9e1a-a91b-5afb-bdc5-f980eb7c3f4c','Head clogging','The accumulation of shed oxide, binder, dust, or other debris on the head face and within the gap, which increases head-to-tape separation and can bridge the gap. It causes high-frequency loss, dropouts, and intermittent level, and is common with shedding or sticky-shed tapes.','Bits of the tape''s coating and dust can build up on the head. This gunk lifts the tape off the head and fills the tiny gap. The result is dull, dropping-out sound.','Recognizing clogging tells a technician that lost highs and dropouts come from the head, not the tape or alignment. It signals that cleaning, and sometimes treating a shedding tape, is needed before transfer.','During a transfer a technician who hears the top end fade stops, inspects the head, and cleans off oxide buildup with a lint-free swab and approved solvent.','Head maintenance',ARRAY['Head-face grooving','Gap erosion','Guide chatter','Head penetration','Head bump']::text[],ARRAY['UNSAFE: Cleaning heads with a flammable solvent such as isopropyl alcohol near a powered machine or ignition source; power down and ventilate first','Scraping the gap with a metal tool, which scratches and erodes the head instead of removing buildup','Running a heavily shedding tape without addressing it, so the head reclogs within minutes']::text[],ARRAY['Cleaning oxide buildup off a head mid-transfer when the treble drops out','Handling a shedding tape that repeatedly clogs the head during playback','Diagnosing intermittent dropouts traced to debris in the reproduce gap']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ff1d9e1a-a91b-5afb-bdc5-f980eb7c3f4c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head clogging'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ff1d9e1a-a91b-5afb-bdc5-f980eb7c3f4c','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ff1d9e1a-a91b-5afb-bdc5-f980eb7c3f4c' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c1d05cd2-195b-5e42-9268-c9c5ca1c4dc8','Head contour resonance','The low-frequency resonant reinforcement underlying head bumps, in which the finite length and contour of the head and the tape wrap allow summed and reflected flux to reinforce at particular long wavelengths. This produces peaks and associated dips in the reproduce response, occurring where the wavelength is related to the head-contact length and therefore shifting with tape speed.','The tape wraps across a certain length of the head. At some low notes that length matches the wave and the flux adds up. This resonance makes the bass response peak, which is what causes head bumps.','It is the physical cause behind head bumps, so understanding it explains why low-frequency ripple is inherent to the head geometry. This helps a technician tell an unavoidable contour effect from a correctable fault.','An engineer studying a machine''s low-frequency ripple recognizes it as a contour resonance set by head and wrap geometry, not a defect to repair.','Reproduce response',ARRAY['Head bump','Gap-length loss','Head penetration','House equalization','Head-field asymmetry']::text[],ARRAY['Treating the resonance as a fault to be repaired rather than an inherent contour effect','Confusing head-contour resonance with an electrical resonance in the reproduce amplifier','Expecting the resonant frequencies to stay fixed when they move with tape speed']::text[],ARRAY['Explaining the origin of periodic low-frequency bumps in a response sweep','Comparing how the bumps shift when a machine is run at a different speed','Teaching why differently sized heads produce differently placed bumps']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c1d05cd2-195b-5e42-9268-c9c5ca1c4dc8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head contour resonance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c1d05cd2-195b-5e42-9268-c9c5ca1c4dc8','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c1d05cd2-195b-5e42-9268-c9c5ca1c4dc8' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '50fcd6e3-b200-51ed-9c68-8db8c645faa5','Head penetration','The depth to which a head''s magnetic field penetrates and magnetizes the tape coating during recording, and correspondingly how deeply layers contribute on reproduction. Long wavelengths magnetize and are read from the full coating depth, while short wavelengths are effectively recorded and read only near the surface, so deeper layers contribute less at high frequencies, following the thickness-loss relationship.','The head''s magnetic field reaches down into the tape''s coating. Low notes magnetize the coating all the way through. High notes only mark the top layer, so a thick coating does not help them.','It explains why short-wavelength (high-frequency) recording uses only the surface of the coating and why thicker coatings mainly help low frequencies. This guides choices about coating thickness and expected high-frequency output.','A technician evaluating tape formulations understands that thicker coatings boost low-frequency output and headroom but do little for the highest frequencies, which live near the surface.','Recording physics',ARRAY['Gap-length loss','Head bump','Head-field asymmetry','Head contour resonance','Full-track mono']::text[],ARRAY['Assuming a thicker coating always improves high-frequency output, when short wavelengths only use the surface','Confusing field penetration depth into the coating with the head-to-tape spacing','Expecting deep layers to contribute equally at all frequencies']::text[],ARRAY['Explaining why thick-coating tapes add low-end headroom but not extended treble','Understanding thickness loss when comparing tape formulations','Teaching why very short wavelengths are recorded only in the top of the coating']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='50fcd6e3-b200-51ed-9c68-8db8c645faa5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head penetration'),'[^a-z0-9]','','g'));
