INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1e26d268-34a6-5e35-838b-0e65137b7d45','Head-face grooving','The wearing of grooves or ridges into the head''s contact face along the path of the tape, caused by abrasive tape running at a fixed lateral position. Grooving disturbs intimate tape-to-head contact, increases spacing loss and dropouts, and eventually requires relapping or replacement of the head.','Tape running in the same spot slowly wears a groove into the head''s face. The groove stops the tape sitting flat on the head. That lifts the tape away and dulls the sound.','Recognizing grooving helps a technician trace rising dropouts and treble loss to worn head geometry rather than to the tape. It marks the point at which a head must be refinished or retired.','During inspection a technician feels for grooves and raised lips on the head face and, when found, sends the head for relapping to restore a smooth contour.','Head wear',ARRAY['Gap erosion','Head clogging','Guide chatter','Head penetration','Head bump']::text[],ARRAY['Mistaking grooving-related dropouts for defective tape','Ignoring raised lips at the edges of tape travel that hold the tape off the gap','Delaying relapping until the gap itself wears through']::text[],ARRAY['Inspecting a heavily used head for grooves before an archival transfer','Diagnosing spacing-loss dropouts caused by a grooved head face','Deciding whether relapping can restore a worn head''s contour']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1e26d268-34a6-5e35-838b-0e65137b7d45' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-face grooving'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1e26d268-34a6-5e35-838b-0e65137b7d45','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1e26d268-34a6-5e35-838b-0e65137b7d45' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '709af720-6c53-5f00-88db-5e4bf9a06e78','Head-field asymmetry','A departure from an ideal, symmetric gap field, in which a head''s magnetic field is not balanced about the gap centerline. It arises from pole-piece geometry, core saturation, or uneven wear, so the field the moving tape experiences, especially at the trailing gap edge where recording is fixed, is asymmetric, which can introduce even-order distortion and shift the effective recording location.','A perfect head would push its field evenly on both sides of the gap. Real heads can be lopsided, from their shape, from wear, or from overload. This uneven field can add distortion and move where the signal is set.','The concept flags why a real head may add distortion or record slightly off from the ideal point. It helps a technician separate a field-imbalance problem from a simple gap tilt.','When a machine shows even-harmonic distortion that alignment does not fix, a technician considers head-field asymmetry from wear or saturation as a cause.','Recording physics',ARRAY['Gap-azimuth interaction','Head penetration','Head contour resonance','Gap erosion','Head bump']::text[],ARRAY['Assuming the record field is perfectly symmetric like an idealized textbook model','Confusing head-field asymmetry (a field imbalance) with azimuth error (a gap tilt)','Overlooking uneven head wear as a source of field asymmetry']::text[],ARRAY['Investigating even-harmonic distortion that persists after alignment','Explaining why recording is fixed at the trailing edge of the gap field','Considering worn pole pieces as a cause of an unbalanced head field']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='709af720-6c53-5f00-88db-5e4bf9a06e78' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-field asymmetry'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '709af720-6c53-5f00-88db-5e4bf9a06e78','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='709af720-6c53-5f00-88db-5e4bf9a06e78' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '05542f8a-75f6-5d00-b40b-1d47738c3196','House equalization','The overall equalization applied to a sound reproduction or reinforcement system to compensate for the combined response of the loudspeakers, the room acoustics, and the playback chain of a particular venue, or house. It shapes the system''s response toward a chosen target curve at the listening area rather than correcting a single component.','House equalization tunes a sound system to a room. It corrects for how the speakers and the room change the sound. The goal is even, natural tone for the whole audience.','It exists to make a system sound consistent and balanced in a specific space, since every room and speaker layout colors the sound differently. It aims the combined response at a target curve for the listeners.','A system technician measures a venue with pink noise and an analyzer, then adjusts a system equalizer to bring the response toward the house target curve.','System equalization',ARRAY['Target curve','Real-time analyzer','Pink noise','Room modes','Graphic equalizer','Feedback']::text[],ARRAY['Trying to equalize away a reflection or reverberation problem that only acoustic treatment can fix','Trusting an analyzer curve without accounting for the measurement microphone and its position','Applying deep narrow boosts that waste amplifier headroom instead of gentle correction']::text[],ARRAY['Tuning a fixed installation to a target curve before an event','Correcting a room mode that muddies the low end in a venue','Setting a consistent baseline tone for a sound system across multiple rooms']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='05542f8a-75f6-5d00-b40b-1d47738c3196' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('House equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
