INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ed1e692f-4f1e-55bf-8271-bb8d3ed51fb2','Hub-slot deformation','A permanent physical deformation of the innermost turns of a tape pack caused by the tape being pressed against the leader-anchoring slot cut into the reel hub. Under long-term winding tension and storage, the slot embosses a repeating mark into several inner layers, leaving a localized ridge or crease that can disturb level and tracking on replay.','Reel hubs have a slot that grips the end of the tape. Wound tight for years, the tape presses into that slot. This leaves a repeating dent in the inner layers. The dent can cause bumps in the sound when you play those turns.','Naming this defect lets archivists spot and avoid a specific, preventable form of tape damage. It exists because a slotted hub concentrates winding stress into the few innermost layers of the pack.','When transferring old reels, a technician inspects the inner turns near the hub for slot marks, expects brief level or tracking upsets there, and rewinds valuable tapes onto slot-less hubs for storage.','Tape defects',ARRAY['Tape pack','Winding tension','Leader tape','Print-through','Cinching']::text[],ARRAY['Mistaking the repeating slot mark for a recording dropout rather than physical deformation of the tape','Storing tapes long-term on slotted hubs instead of transferring them to slot-less hubs or flanged reels','Winding the tape too tightly, which drives the slot imprint deeper into more layers']::text[],ARRAY['Inspecting the inner turns of an archived master reel before transfer','Diagnosing a repeating level bump that appears only near the hub end of a reel','Deciding to rewind a valuable tape onto a slot-less hub for storage']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ed1e692f-4f1e-55bf-8271-bb8d3ed51fb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hub-slot deformation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ed1e692f-4f1e-55bf-8271-bb8d3ed51fb2','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ed1e692f-4f1e-55bf-8271-bb8d3ed51fb2' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9bd7e894-9c0c-525c-bb9f-789fec802143','Hysteresis loop','The closed curve traced by a magnetic material''s flux density (B) or magnetization (M) as the applied field (H) is cycled fully positive to negative and back; it displays the material''s saturation, remanence (magnetization retained at zero field), and coercivity (the reverse field needed to return it to zero). In magnetic recording the loop describes the nonlinear, memory-like transfer characteristic of the tape oxide, which AC bias linearizes for recording.','Magnetic tape remembers the last field it felt. If you chart the field against the magnetism, the path does not retrace itself. It forms a loop. This loop shows how tape stores sound, and it is why recorders add a steady high-frequency signal called bias.','It characterizes how a magnetic material takes on and holds magnetization, defining recording properties such as remanence, coercivity, and saturation. It exists because ferromagnetic materials respond to a field with memory rather than instantly and linearly.','An engineer relies on the loop''s shape when setting bias and record level, because its nonlinear region and saturation point set distortion, headroom, and the tape''s usable dynamic range.','Magnetics',ARRAY['Intrinsic coercivity','Remanence','AC bias','Saturation','Coercivity']::text[],ARRAY['Assuming the tape responds linearly to the record field, when the loop is strongly nonlinear without bias','Confusing remanence (the magnetization left behind) with coercivity (the reverse field needed to remove it)','Thinking a bigger record signal always yields more output, ignoring saturation at the top of the loop']::text[],ARRAY['Explaining why AC bias is required for low-distortion analog recording','Understanding why over-recording drives the tape into saturation','Relating a tape formulation''s coercivity and remanence to its performance']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9bd7e894-9c0c-525c-bb9f-789fec802143' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hysteresis loop'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9bd7e894-9c0c-525c-bb9f-789fec802143','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9bd7e894-9c0c-525c-bb9f-789fec802143' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0086efb3-146b-5405-b824-265eec5dc452','IEC1 equalization','The reproduce (playback) equalization characteristic defined by IEC 60094 for professional open-reel tape, formerly the CCIR/DIN curve, specified by an infinite low-frequency time constant (no bass boost or cut) with a high-frequency time constant of 35 microseconds at 15 and 30 in/s (70 microseconds at 7.5 in/s). Its transition frequency is about 4500 Hz, and it is the standard used for most European professional recordings.','IEC1 is a European playback tone-correction setting for reel tape. IEC stands for International Electrotechnical Commission. It leaves the bass flat and only lifts the treble to undo tape''s high-frequency loss. Tapes made in Europe usually use it.','It restores flat playback response by reversing the treble losses of the tape process, without the low-frequency boost of the NAB/IEC2 curve. It exists to standardize European professional record and replay so tapes interchange between machines.','When aligning for a European master or archive reel, a technician selects IEC1 (CCIR) equalization and calibrates high-frequency response with a matching alignment tape, leaving the bass EQ flat.','Equalization',ARRAY['IEC2 equalization','Infinite low-frequency time constant','NAB equalization','Alignment tape','Reproduce equalization']::text[],ARRAY['Playing an IEC1 (CCIR) tape with NAB/IEC2 equalization, which adds a wrong low-frequency boost and skews the balance','Assuming all reel tapes use the same curve regardless of their origin or speed','Confusing IEC1 with IEC2, when only IEC2 (NAB) applies a low-frequency time constant']::text[],ARRAY['Setting up a machine to transfer a European (CCIR) master tape','Choosing the correct EQ switch position before playing an unknown archive reel','Calibrating high-frequency response with an IEC alignment tape']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0086efb3-146b-5405-b824-265eec5dc452' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('IEC1 equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0086efb3-146b-5405-b824-265eec5dc452','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0086efb3-146b-5405-b824-265eec5dc452' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'af16ab14-7cd8-5949-9182-6d5140194ba6','IEC2 equalization','The reproduce equalization characteristic defined by IEC 60094 that matches the American NAB curve, using a 3180 microsecond low-frequency time constant (a defined bass boost/cut) together with a 50 microsecond high-frequency time constant at 15 and 7.5 in/s; its transition frequency is about 3150 Hz. It is the standard used for most North American professional and semi-professional recordings.','IEC2 is the playback setting that matches the United States NAB standard. NAB stands for National Association of Broadcasters. It boosts the bass and lifts the treble to correct tape losses. Tapes made in North America usually use it.','It restores flat playback response by reversing both the low- and high-frequency errors of the NAB record and replay chain. It exists to standardize North American professional and broadcast tape so recordings interchange between machines.','For a North American master or a machine set to NAB, a technician selects IEC2/NAB equalization and aligns both the low- and high-frequency reproduce response to an NAB alignment tape.','Equalization',ARRAY['IEC1 equalization','NAB equalization','Infinite low-frequency time constant','Alignment tape','Reproduce equalization']::text[],ARRAY['Playing an NAB/IEC2 tape with IEC1 (CCIR) equalization, which omits the needed low-frequency correction','Aligning only the high-frequency response and ignoring the 3180 microsecond low-frequency time constant','Assuming IEC2 and IEC1 are interchangeable, when their bass handling differs']::text[],ARRAY['Aligning a machine to play a North American (NAB) master tape','Transferring a broadcast archive reel recorded to NAB','Selecting the EQ standard that matches an alignment tape''s specification']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='af16ab14-7cd8-5949-9182-6d5140194ba6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('IEC2 equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'af16ab14-7cd8-5949-9182-6d5140194ba6','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='af16ab14-7cd8-5949-9182-6d5140194ba6' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2e0586c0-f105-5101-88c8-20cc938aa13d','Impedance roller','A rotating, low-friction guide of high rotational inertia, often incorporating a flywheel or an inertia spring-mass damper, placed in the tape path (typically near or between the heads) to present a high mechanical impedance to longitudinal tape vibration. By absorbing and blocking those vibrations it reduces scrape flutter and speed-related signal modulation.','An impedance roller is a heavy, free-spinning wheel the tape rides over. Because it is heavy and turns smoothly, it soaks up tiny back-and-forth shakes in the tape. This steadies the tape speed. It cuts a high-pitched flutter called scrape flutter.','It damps the lengthwise (longitudinal) vibrations that friction at guides and heads excites in the moving tape, smoothing speed and lowering scrape flutter. It exists because a plain fixed guide lets those vibrations pass and modulate the signal.','On machines fitted with one, a technician keeps the impedance or scrape-flutter roller clean and free-turning, since a sticky or seized roller stops damping vibration and lets scrape flutter return.','Transport mechanics',ARRAY['Scrape flutter','Longitudinal tape resonance','Flutter','Tape guide','Capstan']::text[],ARRAY['Confusing the free-spinning impedance/flutter roller with the driven capstan that sets tape speed','Letting the roller''s bearing dry out or seize, so it no longer damps vibration','Assuming any tape guide reduces flutter, when only a high-inertia rotating roller presents the needed mechanical impedance']::text[],ARRAY['Tracing the source of high-frequency flutter on a transport','Servicing bearings so the flutter roller spins freely','Explaining why a rotating guide sits between the record and playback heads']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2e0586c0-f105-5101-88c8-20cc938aa13d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Impedance roller'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2e0586c0-f105-5101-88c8-20cc938aa13d','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2e0586c0-f105-5101-88c8-20cc938aa13d' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cdf18889-b5bf-5650-972b-96041277aaa8','Incomplete erasure','A condition in which the erase process fails to reduce a previously recorded signal fully to the tape noise floor, leaving an audible residual of the old program beneath new material or on supposedly blank tape. Common causes include insufficient erase-head current, a worn, dirty, or misaligned erase head, a defective bias/erase oscillator, or tape whose coercivity is too high for the machine''s erase field.','Erasing should wipe the old sound off the tape. Incomplete erasure means some of it survives. You then hear a faint ghost of the old recording under the new one. It often means the erase head or its power is weak, or the tape needs a stronger field.','The concept flags a fault in the erase stage that lets old signal contaminate a recording, so a technician can trace and correct it. It matters because clean erasure is required for a low-noise, single-program recording.','Hearing a residual signal under a new take, a technician checks erase-head current and cleanliness, oscillator function, and whether the tape''s coercivity suits the machine before re-recording.','Erasure',ARRAY['Erase head','Bias oscillator','Intrinsic coercivity','Bulk eraser','Print-through']::text[],ARRAY['Assuming the record head also erases, when without a working erase head old signal remains','Using high-coercivity tape on a machine whose erase field is too weak to fully clear it','UNSAFE: Running a mains-powered bulk eraser or degausser near credit cards, other recordings, hard drives, or medical devices such as pacemakers, or operating it past its rated duty cycle so it overheats; follow the manufacturer''s clearance and duty-cycle instructions.']::text[],ARRAY['Hearing a faint previous recording beneath a fresh take','Diagnosing a weak or dirty erase head on an older machine','Bulk-erasing reels of high-coercivity tape before reuse']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cdf18889-b5bf-5650-972b-96041277aaa8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Incomplete erasure'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cdf18889-b5bf-5650-972b-96041277aaa8','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cdf18889-b5bf-5650-972b-96041277aaa8' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '804b5fe0-ed8f-595e-9806-19f021293dc7','Infinite low-frequency time constant','The specification, characteristic of the IEC1/CCIR reproduce curve, of a low-frequency equalization time constant of infinity, meaning the standard applies no low-frequency boost or cut and holds the reproduced flux flat down to the lowest frequencies. It contrasts with the NAB/IEC2 curve''s finite 3180 microsecond low-frequency time constant, which defines a bass turnover.','A time constant sets where an equalizer starts to bend the bass. Setting it to infinity means it never bends, so the bass stays flat. The IEC1 (European) tape standard works this way. It adds no bass correction, unlike the NAB standard.','It defines the flat low-frequency behavior of the IEC1 standard, simplifying the reproduce chain and avoiding a defined bass turnover. It exists because, at professional speeds, that curve needs no standardized low-frequency boost.','A technician aligning to IEC1 leaves the low-frequency reproduce EQ flat and adjusts only the high end, whereas an NAB/IEC2 setup also sets a defined bass turnover.','Equalization',ARRAY['IEC1 equalization','IEC2 equalization','NAB equalization','Reproduce equalization','Alignment tape']::text[],ARRAY['Reading ''infinite'' as a very large bass boost, when it means no bass equalization at all','Applying a 3180 microsecond NAB bass turnover to a tape recorded flat to the IEC1 curve','Confusing the low-frequency time constant with the separate high-frequency time constant']::text[],ARRAY['Explaining why an IEC1/CCIR tape needs no low-frequency reproduce boost','Setting reproduce EQ when switching a machine between IEC1 and NAB','Interpreting a standard''s time-constant table']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='804b5fe0-ed8f-595e-9806-19f021293dc7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Infinite low-frequency time constant'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '804b5fe0-ed8f-595e-9806-19f021293dc7','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='804b5fe0-ed8f-595e-9806-19f021293dc7' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2d174e30-d41b-5446-9386-fc7511decb4a','Inline-head stereo','A stereo tape head configuration in which the two channel gaps are stacked vertically within a single head assembly at the same point along the tape path (in-line or stacked), as opposed to staggered heads, where the two channels sit in separate head structures spaced apart along the tape. In-line heads reproduce both channels at the same instant, eliminating the fixed inter-channel time delay that staggered heads introduce.','Early stereo tape used two heads spaced apart along the tape. One channel reached its head slightly before the other. In-line stereo stacks both channels in one head at the same spot. Both channels then line up in time, with no built-in delay.','It places both stereo channels at one lengthwise position so they record and replay in time alignment, removing the inter-channel delay and phase problems of staggered heads. It became standard so stereo tapes interchange and sum correctly to mono.','A technician setting azimuth on a modern in-line stereo head aligns one stack for both channels and does not need the timing offset that old staggered-head tapes required.','Head configuration',ARRAY['Staggered heads','Intertrack timing error','Azimuth','Head stack','Tape head']::text[],ARRAY['Assuming every stereo tape is in-line, when early staggered-head tapes need a matching machine or a time offset','Ignoring azimuth on an in-line stack, which still causes high-frequency phase errors between channels','Confusing head stagger (a lengthwise spacing) with azimuth (a gap-angle error)']::text[],ARRAY['Aligning azimuth on a two-track in-line head','Explaining why an old staggered-head tape sums oddly to mono on a modern deck','Understanding why stacked heads keep stereo channels time-aligned']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2d174e30-d41b-5446-9386-fc7511decb4a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Inline-head stereo'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2d174e30-d41b-5446-9386-fc7511decb4a','e9c64f09-41cc-480b-affc-4e0919253e5c',true
