INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '19c87d36-cf2a-519d-96f5-41beb18aaf7a','Intertrack timing error','A time (phase) displacement between signals on parallel tape tracks that should be synchronous, caused by head-gap misalignment such as azimuth error, by inter-gap scatter within a head stack, by staggered-head geometry, or by tape skew. When the mistimed tracks are combined, the delay produces phase cancellation and comb filtering that degrade stereo imaging and mono compatibility.','Tracks recorded side by side should line up in time. Intertrack timing error means one track is slightly early or late. When you mix the tracks together, the offset causes phase problems. This can thin the sound or hurt the stereo image.','Naming this error lets a technician find and correct the timing offsets between tracks that harm phase, imaging, and mono summation. It matters because multitrack and stereo playback assume the tracks stay time-aligned.','A technician minimizes intertrack timing error by carefully setting head azimuth with an alignment tape and checking phase between channels, especially before summing tracks to mono.','Head alignment',ARRAY['Azimuth','Inline-head stereo','Staggered heads','Phase cancellation','Gap scatter']::text[],ARRAY['Leaving azimuth misadjusted, which shifts high-frequency timing between the tracks','Checking only level and not phase between channels after alignment','Blaming the tape for comb filtering that a head-timing error actually causes']::text[],ARRAY['Setting azimuth so stereo channels stay phase-aligned','Diagnosing a hollow, comb-filtered sound when summing two tracks to mono','Interchanging a tape between machines with slightly different head alignment']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='19c87d36-cf2a-519d-96f5-41beb18aaf7a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Intertrack timing error'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
