WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='19c87d36-cf2a-519d-96f5-41beb18aaf7a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '71ff5d9b-2d9e-5f07-be1f-23779d8262b5','Intrinsic coercivity','The magnitude of reverse magnetic field, denoted Hci (or HcJ), required to reduce a magnetic material''s intrinsic magnetization (magnetic polarization) to zero after it has been saturated; it is expressed in oersteds (Oe) or amperes per metre (A/m). It differs from the normal coercivity Hc, which is the reverse field that brings flux density B to zero, and it is the truer measure of the material''s resistance to demagnetization.','Coercivity is how hard it is to wipe the magnetism from a material. Intrinsic coercivity measures the field needed to cancel that magnetism. A higher value means the tape grips its recording harder. Such tape needs a stronger field to erase.','It quantifies how firmly a tape''s oxide holds magnetization, setting the erase and bias fields the tape needs and its resistance to accidental erasure. It exists as the fundamental measure of a material''s magnetic hardness.','Knowing a tape''s coercivity, a technician makes sure the machine''s erase and bias fields are strong enough to fully clear and correctly bias it, since high-coercivity formulations resist weaker fields.','Magnetics',ARRAY['Hysteresis loop','Remanence','AC bias','Incomplete erasure','Saturation']::text[],ARRAY['Confusing intrinsic coercivity (Hci) with normal coercivity (Hc), when they mark different points on the loop','Assuming any tape erases on any machine, when high-coercivity tape needs a stronger erase field','Treating coercivity and remanence as the same property, when one resists erasure and the other is the retained level']::text[],ARRAY['Matching bias and erase settings to a tape formulation''s coercivity','Explaining why metal-particle tape resists erasure more than ferric tape','Understanding why the wrong tape type erases incompletely on a given machine']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='71ff5d9b-2d9e-5f07-be1f-23779d8262b5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Intrinsic coercivity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '71ff5d9b-2d9e-5f07-be1f-23779d8262b5','e9c64f09-41cc-480b-affc-4e0919253e5c',true
