INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '38c2f102-b49f-576b-8046-b15b634fc676','Isolated tape loop','In a closed-loop (isolated-loop) tape drive, the short span of tape across the head assembly that is mechanically isolated from the reels by two capstan contact points (or a single dual-diameter capstan with two pinch rollers, as in the 3M Isoloop), so that tension and speed disturbances from the supply and take-up reels cannot reach the heads. Isolating this loop stabilizes tension and speed at the heads and reduces flutter.','Some machines trap a short loop of tape between two drive points at the heads. This loop is sealed off from the tugging of the reels. Shakes and tension changes from the reels cannot reach it. That keeps the tape steady over the heads and lowers flutter.','It shields the record and playback zone from reel-borne tension and speed changes, giving steadier tape motion and lower flutter than a single-capstan path. It exists to improve speed stability right where the signal is recorded and read.','On a closed-loop machine, a technician keeps both capstan/pinch-roller contacts and the loop guides clean and correctly tensioned, because a fault inside the loop directly raises flutter at the heads.','Transport mechanics',ARRAY['Capstan','Pinch roller','Flutter','Impedance roller','Tape tension']::text[],ARRAY['Confusing the isolated head-loop of a closed-loop drive with an endless splice-free tape loop used for repeating playback','Neglecting one of the two capstan/pinch contacts, so the loop no longer stays isolated','Assuming more capstans always help, without keeping their speeds and tensions matched']::text[],ARRAY['Servicing a closed-loop (Isoloop-type) transport for flutter problems','Explaining why isolating the head zone improves speed stability','Setting tension across a dual-capstan tape path']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='38c2f102-b49f-576b-8046-b15b634fc676' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Isolated tape loop'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '38c2f102-b49f-576b-8046-b15b634fc676','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='38c2f102-b49f-576b-8046-b15b634fc676' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8af15ab5-e585-5847-8688-d14332377302','Lifter scrape','The abrasive contact and resulting noise produced when moving tape rubs against the heads or the lifter posts instead of being cleanly held clear of them by the tape lifters. It occurs when lifters are defeated for cueing (deliberately dragging tape across the heads to locate a point by ear) or when worn or misadjusted lifters fail to pull the tape fully off the heads during fast wind, accelerating head and tape wear.','During fast wind, small arms called lifters pull the tape off the heads. This protects the heads from wear. Lifter scrape is the rubbing and noise when the tape still touches the heads. It happens when you cue by hand, or when the lifters are worn.','The term names the unwanted friction that appears when lifters do not keep tape clear of the heads, alerting a technician to wear and to needed lifter adjustment. Tape lifters exist to prevent this contact during high-speed wind and spare the heads.','A technician who hears scraping during fast wind checks and adjusts the tape lifters, while an editor may intentionally defeat the lifters to rock the reels and cue an edit point by ear.','Transport mechanics',ARRAY['Tape lifter','Cueing','Head wear','Fast wind','Scrape flutter']::text[],ARRAY['Leaving worn or misadjusted lifters uncorrected, so tape scrapes the heads on every fast wind and wears them','Cueing against the heads for long periods, adding needless head and tape wear','Mistaking lifter scrape (mechanical rubbing) for scrape flutter (a speed modulation of the signal)']::text[],ARRAY['Hearing a scraping noise during fast forward or rewind','Defeating the lifters to cue an edit point by ear','Adjusting lifters after a head cleaning or transport service']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8af15ab5-e585-5847-8688-d14332377302' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lifter scrape'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8af15ab5-e585-5847-8688-d14332377302','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8af15ab5-e585-5847-8688-d14332377302' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7c32e9ed-4719-5e13-a630-5a2550c0971c','Long-wavelength level','The reproduced signal level measured at a long recorded wavelength, that is, at a low or mid frequency whose wavelength is far larger than the head gap, where reproduction is essentially free of gap, spacing, and other short-wavelength losses and so reflects the tape''s true recorded fluxivity. Standard reference operating levels (reference fluxivity, for example 185, 250, 320, or 355 nWb/m) are established at such long wavelengths, though narrow-track long-wavelength readings are affected by fringing and low-frequency head bumps.','Wavelength is the length of one recorded wave on the tape. Low notes make long waves. At long waves the head reads the tape almost perfectly, with little loss. So engineers set the playback level using a long-wave tone. That level shows the tape''s true strength.','It gives a loss-free reference point for setting reproduce level and checking recorded fluxivity, because short-wavelength high-frequency losses do not corrupt it. It exists so operating level can be defined and matched consistently across machines and tapes.','Using a calibration tape, a technician sets the reproducer''s level to the standard reference fluxivity with a long-wavelength (low- or mid-frequency) reference tone before adjusting high-frequency response.','Calibration',ARRAY['Reference fluxivity','Fringing','Alignment tape','Operating level','Head bumps']::text[],ARRAY['Setting reference level on a high-frequency tone, where head losses make the reading unreliable','Ignoring fringing and low-frequency head bumps when reading narrow-track long-wavelength levels','Confusing recorded fluxivity in nWb/m with electrical output voltage, which depends on the machine']::text[],ARRAY['Setting reproduce level to reference fluxivity from a calibration tape','Comparing operating levels between two machines','Interpreting a low-frequency level bump caused by fringing on a narrow track']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7c32e9ed-4719-5e13-a630-5a2550c0971c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Long-wavelength level'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7c32e9ed-4719-5e13-a630-5a2550c0971c','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7c32e9ed-4719-5e13-a630-5a2550c0971c' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b0c5f925-ed44-5195-90a4-d7e3f32332d3','Longitudinal tape resonance','A mechanical resonance in which a free span of tape between two supports behaves like a stretched string vibrating along its length (longitudinally), with resonant frequencies set by the span length, tape tension, mass per unit length, and elasticity. Excited by random friction at fixed guides and heads, these longitudinal vibrations are the primary source of scrape flutter.','The free length of tape between two guides acts like a plucked guitar string. Rubbing at the heads makes it vibrate along its length. This vibration changes the tape speed slightly and quickly. The result is a high-pitched flutter called scrape flutter.','Understanding this resonance explains where scrape flutter comes from and why rotating guides or damping rollers between the heads suppress it. It matters because the vibration modulates the recorded and replayed signal.','To control it, a technician relies on scrape-flutter idlers or impedance rollers and correct tension, and keeps the free tape spans short and well guided between the heads.','Transport mechanics',ARRAY['Scrape flutter','Impedance roller','Flutter','Tape tension','Tape guide']::text[],ARRAY['Treating scrape flutter as an electronic problem, when it is a mechanical tape resonance','Removing or seizing the scrape-flutter roller, which lets the resonance modulate the signal','Assuming higher tension always helps, when tension, span length, and damping must be balanced']::text[],ARRAY['Explaining the mechanical origin of scrape flutter','Justifying a damping roller between the record and playback heads','Diagnosing a high-frequency flutter that changes with tape tension']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b0c5f925-ed44-5195-90a4-d7e3f32332d3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Longitudinal tape resonance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b0c5f925-ed44-5195-90a4-d7e3f32332d3','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b0c5f925-ed44-5195-90a4-d7e3f32332d3' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '25f5d666-762d-5bb1-b3db-68ac62b4f9a3','Magnetic fluxivity','The short-circuit magnetic flux per unit track width recorded on, or reproduced from, magnetic tape, expressed in nanowebers per meter (nWb/m). It quantifies the strength of the tape''s remanent magnetization independent of head or track dimensions, and defines standard reference operating levels such as 250 or 320 nWb/m.','Fluxivity measures how strongly a tape is magnetized. It is given in nanowebers per meter. A studio picks one standard value, such as 250, as its zero mark. Then every machine can be set to match it.','It gives a machine-independent measure of recorded signal strength, so tapes and reproducers can be aligned to a common reference level and exchanged between studios.','A technician plays a calibration tape recorded at a known fluxivity (for example 250 nWb/m at 1 kHz) and adjusts the reproduce gain so the meter reads 0 VU, setting the machine''s operating level.','Magnetic Measurement',ARRAY['Reference fluxivity','Operating level','Maximum output level','Multifrequency alignment tape','Magnetic remanence']::text[],ARRAY['Confusing fluxivity, a magnetic quantity in nWb/m, with electrical output voltage or a VU meter reading','Assuming a tape recorded at one reference fluxivity will play at the correct level on a machine aligned to a different reference']::text[],ARRAY['Aligning a tape machine''s playback level to a calibration tape before a mastering session','Documenting the operating level (e.g., 250 nWb/m) of an archival transfer so future engineers can match it','Interchanging master tapes between studios that use different reference fluxivities']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='25f5d666-762d-5bb1-b3db-68ac62b4f9a3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Magnetic fluxivity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '25f5d666-762d-5bb1-b3db-68ac62b4f9a3','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='25f5d666-762d-5bb1-b3db-68ac62b4f9a3' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '89bc2c50-67a0-5128-a606-157f34d8bba3','Magnetic hysteresis','The property whereby the magnetization of a ferromagnetic material lags behind the applied field, so the material follows different paths during magnetization and demagnetization, tracing a closed B-H loop. The loop''s remanence (flux retained at zero field) and coercivity (reverse field needed to remove it) govern a tape''s recording behavior.','Magnetic materials remember the fields they have felt. As you raise and lower a magnetic field, the material does not retrace its path. This lag is called hysteresis. It is why tape can store a signal after the field is gone.','Hysteresis is the physical basis of magnetic recording: the remanent magnetization left in the tape after the record field passes is what stores the signal.','Grasping the hysteresis loop helps a technician understand why AC bias is needed to linearize recording, and why a strong external field can partly erase or distort a stored signal.','Magnetic Fundamentals',ARRAY['Magnetic remanence','Coercivity','AC bias','Magnetization transition','Magnetic fluxivity']::text[],ARRAY['Believing magnetization follows the same curve up and down, which hides why AC bias is required','Confusing coercivity (resistance to demagnetization) with remanence (the flux retained)']::text[],ARRAY['Explaining why AC bias linearizes the transfer of signal onto tape','Assessing why high-coercivity formulations resist accidental erasure','Diagnosing print-through and partial erasure caused by stray magnetic fields']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='89bc2c50-67a0-5128-a606-157f34d8bba3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Magnetic hysteresis'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
