WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='89bc2c50-67a0-5128-a606-157f34d8bba3' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e0433007-c02d-5675-adf1-64103aad223a','Magnetization transition','The finite boundary region on tape between two zones of opposite magnetization, where the magnetization reverses over a non-zero distance called the transition length. Its width, set by the tape''s loop steepness at coercivity and by head-to-tape spacing, limits short-wavelength (high-frequency) resolution.','On tape, the magnetized pattern flips direction to store sound. That flip is not perfectly sharp; it spreads over a tiny distance. A wider spread blurs the highest tones. Keeping the tape close to the head keeps the flip sharp.','The transition region sets the smallest usable recorded wavelength, so it governs the high-frequency response and resolution limit of the recording.','It explains why worn or dirty heads (increased spacing) and some tapes lose high-frequency detail, guiding a technician''s head-cleaning and tape-selection choices.','Magnetic Fundamentals',ARRAY['Magnetic hysteresis','Coercivity','Head-to-tape contact','Short-wavelength response','Magnetic fluxivity']::text[],ARRAY['Assuming the magnetization reverses instantly at a sharp line rather than over a finite length','Overlooking that increased head-to-tape spacing widens transitions and reduces high-frequency output']::text[],ARRAY['Explaining high-frequency loss caused by head wear or debris','Comparing tape formulations for short-wavelength performance','Understanding resolution limits when transferring high-frequency-rich material']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e0433007-c02d-5675-adf1-64103aad223a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Magnetization transition'),'[^a-z0-9]','','g'));
