WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e0433007-c02d-5675-adf1-64103aad223a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '17fec20d-6951-53fb-a00f-495d1259ba4c','Maximum output level','The highest signal level a magnetic tape can reproduce before harmonic distortion reaches a specified limit, expressed in dB relative to a reference fluxivity. For analog audio tape it is conventionally the point at which the third-harmonic distortion of a mid-band tone reaches 3%.','Every tape has a loudest signal it can hold cleanly. Push past it and the sound distorts. That ceiling is the maximum output level. It sets how much headroom you have above your normal level.','It defines a tape''s headroom and, together with the noise floor, its dynamic range, letting engineers choose tape and set safe recording levels.','A technician compares the maximum output level figures of tape stocks (higher means more headroom) and sets record levels to stay below the onset of audible distortion.','Level & Distortion',ARRAY['Maximum output level at 3% distortion','Saturation output level','Reference fluxivity','Optimum bias','Modulation noise']::text[],ARRAY['Treating maximum output level as a hard clipping point rather than a defined-distortion threshold','Comparing figures from different tapes without noting the reference fluxivity they are quoted against']::text[],ARRAY['Selecting a high-output tape formulation for a loud session','Setting safe peak recording levels during tracking','Comparing headroom specs when qualifying a new tape stock']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='17fec20d-6951-53fb-a00f-495d1259ba4c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Maximum output level'),'[^a-z0-9]','','g'));
