INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0d7f395c-db2c-517a-9258-05f8717a628d','Maximum output level at 3% distortion','A tape''s maximum output level defined as the reproduced level, in dB relative to a reference fluxivity, at which the third-harmonic distortion of a recorded mid-band tone (typically 1 kHz) reaches 3%. It is the standard headroom figure quoted on analog audio tape data sheets.','This is the standard way to state a tape''s clean loudness limit. Engineers record a steady tone and raise the level. When distortion reaches three percent, that level is the number. It lets you compare tapes fairly.','Fixing a common distortion criterion (3% third harmonic) lets different tapes and machines be compared on equal footing and gives a repeatable headroom specification.','A technician reads the ''MOL at 3% THD'' figure (for example +7.5 dB relative to 320 nWb/m) from a tape data sheet to judge headroom and pick the right stock for a session.','Level & Distortion',ARRAY['Maximum output level','Saturation output level','Reference fluxivity','Third-harmonic distortion','Optimum bias']::text[],ARRAY['Confusing maximum output level at 3% distortion with saturation output level, which is measured at much higher distortion','Ignoring the reference fluxivity the figure is quoted against, so the dB value is misread']::text[],ARRAY['Reading a tape data sheet to compare headroom between formulations','Documenting the headroom of an archival tape stock','Setting alignment targets during machine calibration']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0d7f395c-db2c-517a-9258-05f8717a628d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Maximum output level at 3% distortion'),'[^a-z0-9]','','g'));
