INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '89624b27-0e7e-542f-862a-dc92cdbd2f47','Modulation noise','Signal-dependent noise that appears only when a signal is recorded, riding on the reproduced signal and roughly proportional to its amplitude. It arises from irregularities in the tape coating (variations in particle size, orientation, coercivity, and dispersion) and is heard as noise ''behind'' the signal.','Some tape noise is only there when a sound is playing. It rides along with the signal and grows as the signal grows. It comes from tiny unevenness in the tape''s coating. Quiet parts hide it, but loud steady tones reveal it.','It is a basic noise limit of magnetic tape, distinct from constant hiss; recognizing it explains audible noise around a signal that simple gating cannot remove.','A technician hears modulation noise as a rough halo around sustained tones such as piano or vocals, and may choose smoother-particle tape or lower levels to reduce it.','Noise & Artifacts',ARRAY['Tape hiss','Print-through','Dynamic range','Magnetic fluxivity','Optimum bias']::text[],ARRAY['Confusing modulation noise, present only with signal, with the constant bias hiss heard in silence','Assuming a noise gate removes it; because it tracks the signal, it cannot be gated out']::text[],ARRAY['Evaluating tape stocks for clean sustained instruments','Diagnosing a rough halo around loud tones on a transfer','Explaining why noise reduction that works on hiss fails on modulation noise']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='89624b27-0e7e-542f-862a-dc92cdbd2f47' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Modulation noise'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '89624b27-0e7e-542f-862a-dc92cdbd2f47','e9c64f09-41cc-480b-affc-4e0919253e5c',true
