INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f7087937-0e37-53cb-b693-65450d215ccc','Multifrequency alignment tape','A calibration test tape carrying recorded sine-wave tones at many frequencies, plus reference-level and azimuth sections, used to standardize a tape reproducer''s gain, head azimuth, and equalization/frequency response. It is recorded to a known reference fluxivity on precisely aligned equipment.','This is a reference tape holding test tones at many pitches. You play it to set a machine up correctly. It lets you fix the playback level, the head angle, and the tone balance. Think of it as a tuning fork for tape machines.','It gives technicians a traceable standard so any reproducer can be aligned to the same level, azimuth, and frequency response, allowing tapes to interchange between machines and studios.','During setup, a technician plays the tape, sets reproduce gain to the reference tone, peaks head azimuth on a high-frequency tone, and adjusts reproduce equalization for uniform output across the tones.','Alignment & Calibration',ARRAY['Reference fluxivity','Magnetic fluxivity','Azimuth','NAB equalization','Operating level']::text[],ARRAY['Using an alignment tape to set record parameters or to check flutter and distortion; it is a reproduce standard only','Aligning to a worn or wrong-speed/EQ calibration tape and thus to false targets']::text[],ARRAY['Aligning reproduce level, azimuth, and EQ before transferring archival tapes','Verifying a machine''s playback response during routine maintenance','Standardizing several machines so tapes interchange between them']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f7087937-0e37-53cb-b693-65450d215ccc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Multifrequency alignment tape'),'[^a-z0-9]','','g'));
