INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '535924e7-a4a4-55a3-8be7-878910ca6358','NAB equalization','The tape recording and reproducing equalization standard defined by the U.S. National Association of Broadcasters, specifying the flux-versus-frequency characteristic by two time constants (3180 microseconds and 50 microseconds at 15 and 7.5 ips). It is the common North American open-reel standard, distinct from the IEC/CCIR curve.','NAB is an American standard for how tape machines shape tone. Record and playback follow an agreed curve, so a tape sounds right on any machine. It is defined by two time values. Europe often uses a different standard called IEC.','A shared equalization curve ensures a tape recorded on one machine plays back with correct frequency balance on another, making tapes interchangeable across studios and broadcasters.','A technician selects the NAB position to match the tape''s recorded standard and aligns reproduce EQ to an NAB calibration tape; playing an NAB tape on IEC EQ gives a wrong high-frequency balance.','Equalization Standards',ARRAY['NARTB equalization','IEC equalization','CCIR equalization','Multifrequency alignment tape','NagraMaster equalization']::text[],ARRAY['Playing an NAB-recorded tape with IEC/CCIR equalization selected, giving a wrong high-frequency balance','Forgetting that NAB also specifies a low-frequency (3180 microsecond) boost, not just the high-frequency time constant']::text[],ARRAY['Setting the EQ switch to match an archival tape''s recorded standard','Aligning a broadcast or studio machine to an NAB calibration tape','Transferring North American master tapes cut to NAB']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='535924e7-a4a4-55a3-8be7-878910ca6358' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('NAB equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '535924e7-a4a4-55a3-8be7-878910ca6358','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='535924e7-a4a4-55a3-8be7-878910ca6358' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '13e8fe98-3cb4-5b14-83e6-6bd0949cc9fa','NARTB equalization','An equalization curve for magnetic tape identical to the NAB curve. NARTB stands for the National Association of Radio and Television Broadcasters, the organization''s name (1951-1958) under which the standard was published in 1953, so ''NARTB'' and ''NAB'' equalization denote the same 3180/50 microsecond characteristic.','NARTB and NAB name the very same tape standard. The broadcasters'' group simply changed its name over the years. Old machines may be labeled NARTB; newer ones say NAB. Treat the two as identical.','It is the same interchange standard as NAB; the alternate label reflects the standards body''s historical name and appears on older equipment and tape boxes.','Seeing ''NARTB'' on a vintage machine or tape box, a technician treats it exactly as NAB and aligns to an NAB calibration tape.','Equalization Standards',ARRAY['NAB equalization','IEC equalization','CCIR equalization','Multifrequency alignment tape','Reference fluxivity']::text[],ARRAY['Believing NARTB is a different curve needing different alignment from NAB; they are identical','Searching for a separate NARTB calibration tape instead of using an NAB one']::text[],ARRAY['Interpreting ''NARTB'' markings on a vintage tape machine or tape box','Aligning an older broadcast recorder labeled NARTB','Cataloging archival tapes whose documentation cites NARTB equalization']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='13e8fe98-3cb4-5b14-83e6-6bd0949cc9fa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('NARTB equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
