INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '600346ea-fa01-5f71-aeed-212cdec8e045','NagraMaster equalization','A proprietary tape equalization standard offered on certain Nagra recorders that increases high-frequency pre-emphasis compared with NAB or IEC/CCIR at the same speed, permitting higher recording levels and an improved signal-to-noise ratio. Tapes recorded with NagraMaster must be reproduced with the matching NagraMaster curve.','NagraMaster is a special tone curve built into some Nagra recorders. It boosts the highs more than the usual standards. This lets the tape hold more level with less hiss. But you must play the tape back with the same setting.','It trades interchangeability for performance, giving Nagra field recorders extra headroom and lower noise where both the recording and playback machines use the curve.','A technician transferring Nagra field tapes must identify NagraMaster recordings and set the reproducer to the matching curve, or the high frequencies will be wrong.','Equalization Standards',ARRAY['NAB equalization','IEC equalization','CCIR equalization','Reference fluxivity','Modulation noise']::text[],ARRAY['Reproducing a NagraMaster tape with NAB or IEC equalization, giving a boosted or dull high end','Assuming NagraMaster is interchangeable with standard curves across all machines']::text[],ARRAY['Transferring vintage Nagra field-recorded tapes in an archive','Documenting the equalization standard of location-sound masters','Setting up a Nagra recorder for high-level, low-noise field work']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='600346ea-fa01-5f71-aeed-212cdec8e045' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('NagraMaster equalization'),'[^a-z0-9]','','g'));
