INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f32c7f50-0080-564d-9316-2700d3b02266','Open-loop transport','A tape transport design in which a single capstan drives the tape and the tape path past the heads is not isolated from reel-side tension disturbances by a second capstan. Tape tension at the heads is influenced by supply- and take-up-reel behavior, in contrast to a closed-loop (dual-capstan) transport.','In an open-loop machine, one roller pulls the tape past the heads. Nothing shields the head area from tugs coming from the reels. So reel wobble can reach the heads. A closed-loop design adds a second roller to block that.','It is a simpler, lower-cost transport arrangement, but it leaves the head-to-tape zone more exposed to tension and speed changes from the reels than a closed-loop transport.','A technician servicing an open-loop machine pays close attention to reel-motor and hold-back tension, since these directly affect flutter and head contact.','Tape Transport',ARRAY['Closed-loop transport','Capstan','Pinch roller','Tape tension','Flutter']::text[],ARRAY['Assuming open-loop transports isolate the heads from reel disturbances; they do not','Neglecting reel and hold-back tension setup, which strongly affects flutter on open-loop machines']::text[],ARRAY['Servicing tension and flutter on a single-capstan tape machine','Comparing transport designs when choosing a machine for archival transfer','Diagnosing speed instability traced to reel-side tension']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f32c7f50-0080-564d-9316-2700d3b02266' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Open-loop transport'),'[^a-z0-9]','','g'));
