INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '03488926-dea2-514f-b6b8-544e89c5dfb7','Optimum bias','The AC bias current setting that gives the best overall compromise among sensitivity, distortion, noise, and frequency response for a given tape and speed. In practice it is set by the overbias method: increasing bias past the point of peak long-wavelength output by the tape''s specified overbias amount.','AC bias is a hidden high-frequency current added while recording. Each tape has a best amount. Too little or too much hurts the sound. Engineers find the peak output, then nudge the bias a little higher to the sweet spot.','Correct bias linearizes recording; the optimum setting balances competing tradeoffs so the tape records with low distortion, good high-frequency response, and low noise.','Using an oscillator and meter, a technician records a test tone, finds the bias that peaks the output, then adds the tape''s rated overbias to reach the optimum setting on each channel.','Bias & Recording',ARRAY['Overbias','AC bias','Maximum output level','Modulation noise','Reference fluxivity']::text[],ARRAY['Setting bias only for peak output instead of adding the specified overbias, leaving distortion and response non-optimal','Using another tape''s overbias value, since optimum bias differs by formulation and speed','UNSAFE: probing bias-oscillator and record-amplifier circuitry inside a powered chassis (tube machines carry lethal high voltage) without following the service manual''s lockout and shock-hazard precautions']::text[],ARRAY['Biasing each channel of a multitrack recorder for a new tape stock','Re-biasing when switching between tape formulations','Routine calibration before a recording session']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='03488926-dea2-514f-b6b8-544e89c5dfb7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Optimum bias'),'[^a-z0-9]','','g'));
