INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f2250252-6740-5838-94db-1ec4525c9dfe','Orientation ratio','A measure of how well a tape''s acicular (needle-shaped) magnetic particles are aligned along the tape length, expressed as the ratio of remanent magnetization measured in the longitudinal (machine) direction to that measured in the transverse direction. A ratio well above 1 (commonly greater than about 1.5 for oriented tape) indicates strongly aligned particles and yields higher output and a better signal-to-noise ratio.','Tape coatings hold tiny needle-shaped magnets. They record best when lined up along the tape''s length. The orientation ratio tells how well they are lined up. A higher number means better alignment, more output, and less noise.','It quantifies particle alignment, a key quality metric because well-oriented tape records more strongly and quietly in the direction of travel than randomly oriented tape.','A tape manufacturer or archivist uses the orientation ratio to compare formulations, since a higher ratio predicts stronger, cleaner longitudinal recording performance.','Magnetic Measurement',ARRAY['Magnetic remanence','Magnetic hysteresis','Coercivity','Magnetic fluxivity','Maximum output level']::text[],ARRAY['Confusing orientation ratio (a longitudinal-to-transverse comparison) with squareness, which is remanence divided by saturation in one direction','Assuming a random, unoriented coating (ratio near 1) records as strongly as an oriented one']::text[],ARRAY['Comparing magnetic properties of candidate tape formulations','Explaining why oriented tape outputs more in the direction of travel','Assessing coating quality during tape manufacture or evaluation']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f2250252-6740-5838-94db-1ec4525c9dfe' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Orientation ratio'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f2250252-6740-5838-94db-1ec4525c9dfe','e9c64f09-41cc-480b-affc-4e0919253e5c',true
