INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0b4daffe-00a1-534d-9097-504e489dc20d','Overbias','The amount by which AC bias current is increased beyond the level that produces peak output at a specified high frequency, expressed in dB of output reduction from that peak. It is the standard method for setting a tape to its optimum bias; the required overbias depends on tape formulation and speed.','To bias tape, engineers first find the bias that gives the loudest test tone. Then they raise the bias more until the tone drops by a set amount. That extra push is the overbias. Each tape has its own recommended figure.','Setting bias slightly past the output peak reduces distortion and evens out frequency response, at the small cost of some high-frequency output, placing the tape at its optimum operating point.','A technician records a high-frequency tone (for example 10 kHz), finds the output peak, then raises bias until the level drops by the tape''s rated overbias to set optimum bias.','Bias & Recording',ARRAY['Optimum bias','AC bias','Maximum output level','Modulation noise','Reference fluxivity']::text[],ARRAY['Confusing overbias (bias past the peak) with the total bias current itself','Applying a generic overbias value instead of the specific figure for the tape and speed in use','Finding the bias peak at the wrong frequency, giving an incorrect overbias setting']::text[],ARRAY['Setting optimum bias for a new tape stock by the overbias method','Adjusting overbias when changing tape speed','Trading a little high-frequency output for lower distortion during alignment']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0b4daffe-00a1-534d-9097-504e489dc20d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Overbias'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
