INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '485193db-c2f4-5bcd-9f88-27e936ff486b','Overbias curve','A plot of a tape''s reproduced output versus the applied high-frequency AC bias current, showing output rising to a peak (peak bias, or maximum sensitivity) and then falling as bias is increased further into the overbiased region. Recordists set bias a specified amount above this peak (the overbias) to trade a small short-wavelength loss for lower distortion and flatter response.','Bias is a steady high tone added to the signal while recording. As you raise it, the sound gets louder up to a peak, then quieter again. A graph of that rise and fall is the overbias curve. Engineers set the bias just past the peak on purpose.','It shows how output changes with bias so a technician can find peak bias and then set the correct amount of overbias for a given tape and speed. This balances high-frequency response, distortion, and noise.','During alignment a technician records a tone, sweeps bias while watching output, notes the peak, then raises bias by the tape maker''s specified overbias, often defined as a set decibel drop at a high frequency.','Bias & alignment',ARRAY['Reference fluxivity','Reference tape','Relative tape sensitivity','Recorded wavelength','Remanence']::text[],ARRAY['Setting bias exactly at the peak, which leaves high-frequency response and distortion un-optimized','Treating overbias as one fixed value rather than a tape- and speed-specific amount past the peak','Confusing AC record bias with the erase signal or with DC bias','UNSAFE: Reaching inside the machine to adjust bias oscillator circuits with mains power live; follow lockout and the manufacturer''s service procedure']::text[],ARRAY['Aligning a recorder to a new batch of tape before a session','Optimizing high-frequency headroom when comparing 15 and 30 inches per second','Diagnosing dull highs traced to under- or over-biasing']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='485193db-c2f4-5bcd-9f88-27e936ff486b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Overbias curve'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
