INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c13f8ec9-b55c-5ebc-b0ec-e0ce9ee51aa5','Particle orientation','The alignment of a tape coating''s acicular (needle-shaped) magnetic particles along the intended recording direction, produced by passing the wet coating through a magnetic field before it dries. Orientation raises remanence and output in the head-to-tape motion direction and increases the squareness ratio (Mr/Ms) from about 0.5 for random particles toward 0.7 to 0.9.','The magnetic bits in tape are shaped like tiny needles. During making, a magnet lines them up along the length of the tape. Lined-up needles hold a stronger, cleaner signal than jumbled ones. It is like combing hairs so they all point one way.','Aligning the particles maximizes signal output and retained magnetism in the recording direction and improves uniformity, so the tape records more efficiently with a better signal-to-noise ratio.','A technician meets orientation as the reason different tape formulations have different output and bias needs, and why tape can behave directionally.','Tape media',ARRAY['Remanence','Reference fluxivity','Relative tape sensitivity','Print-through ratio','Recorded wavelength']::text[],ARRAY['Assuming all tapes are equally sensitive regardless of how well their particles are oriented','Thinking orientation is something the user sets rather than a property fixed during manufacture','Confusing particle orientation in the coating with head azimuth alignment at playback']::text[],ARRAY['Explaining why a given tape formulation needs its own bias and level calibration','Comparing output between tape brands during a media evaluation','Understanding directional performance differences during archival transfer']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c13f8ec9-b55c-5ebc-b0ec-e0ce9ee51aa5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Particle orientation'),'[^a-z0-9]','','g'));
