INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '002336ba-474d-5cee-9694-493b8865ff4c','Pole-piece magnetization','An unwanted residual (DC) magnetization retained by the ferromagnetic pole pieces that form a tape head''s gap, usually caused by exposure to a steady magnetic field from magnetized tools, static, or switching transients. It leaves a standing field at the gap that raises noise and can partially erase recorded high frequencies.','A tape head has two metal pieces that meet at a tiny gap. Over time they can pick up a weak, stuck magnetism. This stuck magnetism adds hiss and can rub the high notes off the tape. You clear it by demagnetizing the head.','Naming this fault explains why heads must be demagnetized periodically to keep noise low and protect recordings; it is the condition that demagnetization cures.','A technician removes pole-piece magnetization by demagnetizing (degaussing) the heads and metal tape-path parts during routine maintenance.','Heads & maintenance',ARRAY['Remanent head field','Remanence','Pole-tip recession','Recorded wavelength','Reference tape']::text[],ARRAY['UNSAFE: Running the head demagnetizer with recorded tapes on or near the machine, which can partially erase them; keep all tapes well away','UNSAFE: Switching the demagnetizer on or off close to the heads, or moving it quickly; switch it on well away, approach and withdraw slowly, then switch off far away','Touching heads or guides with a magnetized screwdriver, which magnetizes the pole pieces','Assuming tape heads never need demagnetizing']::text[],ARRAY['Routine periodic maintenance of a studio tape machine','Chasing rising tape hiss or dulled highs on playback','Preparing a deck for an archival transfer session']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='002336ba-474d-5cee-9694-493b8865ff4c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pole-piece magnetization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '002336ba-474d-5cee-9694-493b8865ff4c','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='002336ba-474d-5cee-9694-493b8865ff4c' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b2ac5335-c27b-575a-bf84-b4f1e391886c','Pole-tip recession','The wear-induced recession of a head''s magnetic pole tips below the surrounding, harder head substrate surface, caused by differential (preferential) abrasion at the head-tape interface. The recessed pole tips increase the effective head-to-tape spacing, producing spacing loss that reduces short-wavelength (high-frequency) output.','A tape head rubs against moving tape for years. The soft magnetic parts wear down faster than the hard body around them. That leaves a tiny gap between the tip and the tape. Even a small gap quietly weakens the high notes.','The concept explains a gradual loss of highs and output from head wear, and guides when heads need relapping or replacement.','A technician suspects pole-tip recession when a well-aligned deck loses highs and level that bias and equalization cannot restore, pointing to worn heads.','Heads & maintenance',ARRAY['Recorded wavelength','Pole-piece magnetization','Remanent head field','Reference tape','Relative tape sensitivity']::text[],ARRAY['Blaming tape or alignment for lost highs that actually come from worn, recessed heads','Cleaning heads abrasively, which speeds wear and recession','Confusing pole-tip recession with widening of the head gap, a related but distinct wear effect']::text[],ARRAY['Evaluating whether a vintage deck''s heads need relapping','Explaining unrecoverable high-frequency loss during calibration','Deciding to replace heads on a heavily used archival transport']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b2ac5335-c27b-575a-bf84-b4f1e391886c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pole-tip recession'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b2ac5335-c27b-575a-bf84-b4f1e391886c','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b2ac5335-c27b-575a-bf84-b4f1e391886c' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '72ffaccb-65af-52f7-bea8-6eebcf9647c0','Print-through ratio','The ratio, expressed in decibels, of a printed (transferred) signal to the original recorded signal, quantifying print-through: the unwanted magnetic transfer between adjacent tape layers on a reel that produces pre-echo and post-echo. It worsens with higher storage temperature, longer storage time, thinner tape, and higher recording level.','On a reel, each wrap of tape presses against the next. A loud sound can slowly copy itself faintly onto the neighboring layers. You then hear a ghost just before or after it. The print-through ratio measures how loud that ghost is next to the real sound, in decibels.','It gives a measurable figure for how much a stored recording will suffer ghost echoes, helping archivists judge tape and storage quality.','Archivists limit print-through by storing tapes tails-out, keeping them cool, and rewinding periodically, and they assess the ratio when evaluating at-risk masters.','Storage & preservation',ARRAY['Remanence','Reference fluxivity','Reference tape','Particle orientation','Recorded wavelength']::text[],ARRAY['Storing tape heads-out, which makes the audible echo a pre-echo before the sound rather than the less noticeable post-echo','Recording at excessively hot levels, which raises print-through','Storing tapes near loudspeakers, motors, or other strong magnetic fields','Assuming a single rewind fixes print-through permanently rather than needing periodic re-winding']::text[],ARRAY['Assessing a decades-old master tape before transfer','Choosing tails-out storage for archival masters','Explaining a faint pre-echo heard before a loud musical entrance']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='72ffaccb-65af-52f7-bea8-6eebcf9647c0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Print-through ratio'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '72ffaccb-65af-52f7-bea8-6eebcf9647c0','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='72ffaccb-65af-52f7-bea8-6eebcf9647c0' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f6d12b05-8d48-5657-bd62-ef8f1140321a','Quarter-track stereo','A quarter-inch open-reel tape format that divides the tape width into four parallel tracks, recording one stereo pair (tracks 1 and 3) in one direction and, after the reel is flipped, a second stereo pair (tracks 2 and 4) in the opposite direction. It doubles program time per reel versus half-track (two-track) stereo but uses narrower tracks, giving lower output and signal-to-noise ratio.','The tape is split into four thin lanes side by side. Two lanes carry left and right for one direction. Flip the reel over and the other two lanes play the way back. So one reel holds twice as much, but thinner lanes mean a bit more hiss.','The format exists to double recording time and allow both-directions use on consumer machines, trading some quality for capacity.','A transfer technician must fit a matching quarter-track playback head and map the tracks correctly to recover both stereo passes from such a tape.','Track formats',ARRAY['Recorded wavelength','Relative tape sensitivity','Reference tape','Reference fluxivity','Print-through ratio']::text[],ARRAY['Playing a quarter-track tape on a half-track machine, or the reverse, which mixes or mistracks the audio','Transferring only the forward pair and forgetting the reverse-direction tracks','Expecting the same output level and noise floor as wider half-track tracks']::text[],ARRAY['Transferring a home-recorded reel from the 1960s or 1970s','Identifying an unknown reel''s track format before playback','Explaining lower output when calibrating a quarter-track deck']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f6d12b05-8d48-5657-bd62-ef8f1140321a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Quarter-track stereo'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f6d12b05-8d48-5657-bd62-ef8f1140321a','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f6d12b05-8d48-5657-bd62-ef8f1140321a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ce1aabfa-bf5c-56ce-af0a-2f6e885726e1','Recorded wavelength','The physical length along the tape of one cycle of a recorded signal, equal to the tape speed divided by the signal frequency. Short wavelengths, produced by high frequencies or low tape speeds, are progressively attenuated by spacing loss, gap loss, and self-demagnetization, which set the high-frequency limit of a tape system.','A recorded tone is a wavy magnetic pattern along the tape. Its wavelength is how long one full wave is on the tape. Faster tape or lower notes make longer waves. Very short waves are hard to record and play back, so they fade.','The idea links tape speed and frequency to short-wavelength losses, explaining why higher tape speeds improve high-frequency response and headroom.','A technician uses it to understand why 30 inches per second captures better highs than 7.5, and why head gap and head-to-tape spacing matter most at short wavelengths.','Recording theory',ARRAY['Overbias curve','Pole-tip recession','Remanence','Reference fluxivity','Relative tape sensitivity']::text[],ARRAY['Confusing recorded wavelength, a length on the tape, with the signal''s frequency in cycles per second','Forgetting that halving tape speed halves every wavelength and worsens high-frequency loss','Assuming a smaller head gap alone fixes short-wavelength losses that are caused by spacing']::text[],ARRAY['Choosing 15 versus 30 inches per second for a mastering session','Explaining head-gap and spacing-loss effects during alignment','Understanding self-erasure of high frequencies at low tape speeds']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ce1aabfa-bf5c-56ce-af0a-2f6e885726e1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Recorded wavelength'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
