WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ce1aabfa-bf5c-56ce-af0a-2f6e885726e1' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ffe82bec-9cce-5088-b2ad-d9954ba6ee01','Reel-table height','The vertical height at which a tape machine''s reel tables (the hub platforms carrying the supply and take-up reels) are set, so the tape pays off and winds in the same plane as the guides, capstan, and heads. Correct, matched reel-table height keeps the tape running flat through the path, minimizing edge stress and pack problems.','Two round platforms hold the tape reels. They must sit at the right height. Then the tape runs level into the guides and heads. If one is too high or low, the tape rides crooked and its edges get stressed. It is like lining up two spools so a thread feeds straight.','Setting reel-table height keeps the tape coplanar with the transport so it tracks correctly and winds a clean pack without edge damage.','During servicing a technician checks and adjusts reel-table height per the service manual, especially after replacing a reel table or reel motor.','Transport alignment',ARRAY['Reel-table runout','Recorded wavelength','Reference tape','Pole-tip recession','Print-through ratio']::text[],ARRAY['UNSAFE: Servicing the reel motor or transport with mains power live; follow lockout/tagout and the manufacturer''s procedure before removing covers','Blaming tracking or edge damage on guides alone while ignoring reel-table height','Adjusting one reel table''s height without matching the other']::text[],ARRAY['Servicing a deck after a reel-table or reel-motor replacement','Curing a scattered wind or tape edge damage','Restoring a vintage transport for archival use']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ffe82bec-9cce-5088-b2ad-d9954ba6ee01' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reel-table height'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ffe82bec-9cce-5088-b2ad-d9954ba6ee01','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ffe82bec-9cce-5088-b2ad-d9954ba6ee01' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1fcbc74e-07d8-5e54-ab05-b922f17729c3','Reel-table runout','The axial (vertical) runout of a rotating reel table, meaning how much its mounting face wobbles up and down away from true perpendicular rotation as the reel turns. Excessive runout moves the tape pack vertically during winding, causing scatter wind, uneven pack, edge weave, and tension or level fluctuations.','A reel platform should spin perfectly flat. If it is warped or loose, it bobs up and down as it turns. That wobble shifts the tape and makes a messy, uneven wind. Think of a bent record turntable that bobs while it spins.','Keeping runout within tolerance ensures the tape winds evenly and runs steadily, protecting the tape edges and the wind quality.','A technician measures reel-table runout with a dial indicator during a transport overhaul and replaces a warped table or worn motor bearing if it is out of spec.','Transport alignment',ARRAY['Reel-table height','Reference tape','Print-through ratio','Recorded wavelength','Pole-tip recession']::text[],ARRAY['UNSAFE: Reaching into a spinning transport or servicing it with mains power live; power down and follow lockout before measuring or adjusting','Mistaking pack and edge problems from runout for a tension or guide fault','Overlooking a worn reel-motor bearing as the source of the runout']::text[],ARRAY['Diagnosing scattered or stepped tape packs','Overhauling a transport with worn reel-motor bearings','Qualifying a machine before archival transfers']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1fcbc74e-07d8-5e54-ab05-b922f17729c3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reel-table runout'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1fcbc74e-07d8-5e54-ab05-b922f17729c3','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1fcbc74e-07d8-5e54-ab05-b922f17729c3' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5ed0635d-b36b-5507-88bf-f511e281f04d','Reference fluxivity','A standardized reference level of recorded magnetic flux per unit track width on a tape, expressed in nanowebers per meter at a stated frequency (commonly 1 kHz), used to set a reproducer''s gain so its meter reads a defined operating level (usually 0 dB). Common values include 200, 250, 320 (German standard), 355, and 500 nanowebers per meter.','Tape stores sound as magnetism. Reference fluxivity is an agreed standard strength of that magnetism, in special units. A test tape holds a tone at this exact strength. Engineers use it to set the machine so its meter reads the right level. It is like a standard weight used to set a scale.','It provides a common, measurable zero-decibel reference so recordings made and played on different machines match in level.','A technician plays the reference-fluxivity tone from a calibration tape and adjusts the reproduce gain until the meter reads the target level.','Levels & calibration',ARRAY['Reference tape','Relative tape sensitivity','Overbias curve','Remanence','Recorded wavelength']::text[],ARRAY['Confusing reference fluxivity, a magnetic level on tape, with electrical line level in volts or dBu','Calibrating to the wrong fluxivity standard for the tape and equalization in use, such as 250 versus 355 nanowebers per meter','Assuming a higher fluxivity always sounds better rather than meaning more level and possible distortion']::text[],ARRAY['Setting reproduce level with a calibration tape','Matching operating levels between two studios'' machines','Documenting the fluxivity a master tape was aligned to']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5ed0635d-b36b-5507-88bf-f511e281f04d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reference fluxivity'),'[^a-z0-9]','','g'));
