INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aeeadfbe-b2b4-5936-8d64-363a83ea4d7c','Reference tape','A precisely recorded standard tape, also called a calibration or test tape, containing tones of known fluxivity and frequency used to standardize a reproducer''s azimuth, equalization, and sensitivity (level) so machines reproduce recordings consistently. Reproduce alignment is performed against the reference tape before record calibration is done.','A reference tape is a factory-made test tape. It holds tones recorded at exact, known strengths. You play it first to set the machine''s playback correctly. Then you know the machine is right before you record. It works like a tuning fork for a tape deck.','It gives a known, traceable playback standard so every machine''s reproduce path is aligned the same way, independent of the tape being recorded.','A technician threads a reference tape and sets reproduce level, high-frequency equalization, and head azimuth to its tones before touching any record adjustment.','Levels & calibration',ARRAY['Reference fluxivity','Relative tape sensitivity','Overbias curve','Recorded wavelength','Reel-table height']::text[],ARRAY['Setting record calibration before the reproduce path is aligned to the reference tape','Using a reference tape of the wrong speed or equalization standard','Fast-winding or mishandling a valuable reference tape, causing wear or stretch']::text[],ARRAY['Full alignment of a tape machine at the start of a session','Verifying azimuth and equalization before an archival transfer','Checking a suspected level error between two machines']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aeeadfbe-b2b4-5936-8d64-363a83ea4d7c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reference tape'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'aeeadfbe-b2b4-5936-8d64-363a83ea4d7c','e9c64f09-41cc-480b-affc-4e0919253e5c',true
