INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1eb1c014-5d94-5f9a-aff1-0a9d0d653910','Relative tape sensitivity','The recording sensitivity of a given tape expressed in decibels relative to a reference tape, describing how much reproduced output the tape yields for a fixed record current compared with the reference. It lets a technician re-trim record level so different tape formulations reach the same operating fluxivity.','Different tapes need different amounts of signal to reach the same loudness. Relative tape sensitivity compares a tape to a standard one, in decibels. If a tape is less sensitive, you feed it a little more to match. It is like some films needing more light for the same photo.','It quantifies how a tape''s efficiency differs from the reference so record level and bias can be reset when the tape stock is changed.','When switching tape brands, a technician measures the new tape''s relative sensitivity and re-trims record level to hit the target operating fluxivity.','Levels & calibration',ARRAY['Reference tape','Reference fluxivity','Overbias curve','Particle orientation','Remanence']::text[],ARRAY['Assuming every tape reaches reference level at the same record setting without re-calibrating','Confusing sensitivity differences with bias or equalization differences','Ignoring that sensitivity can vary with frequency, not just at one test tone']::text[],ARRAY['Re-aligning a deck after changing tape formulation','Comparing candidate tape stocks for a project','Explaining why a tape reads low at the same record gain']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1eb1c014-5d94-5f9a-aff1-0a9d0d653910' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Relative tape sensitivity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
