INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c100986a-b656-5f56-aeae-d93db92ae486','Remanence','The magnetic flux density (Br) that remains in a magnetic material after the applied magnetizing field is removed; in tape it is the retained magnetization that stores the recorded signal. Together with the material''s coercivity and squareness, higher remanence yields higher reproduced output for a given track width.','Remanence is the magnetism a material keeps after the magnet is taken away. In tape, this leftover magnetism is the actual stored recording. More of it means a stronger playback signal. It is like a nail that stays a little magnetic after you rub a magnet on it.','Remanence is the physical basis of tape storage: it is what holds the signal on the tape after recording, and it sets how strong the played-back signal can be.','A technician meets remanence as a tape specification that, with coercivity, explains a formulation''s output and why it needs its own bias and level calibration.','Magnetic properties',ARRAY['Remanent head field','Reference fluxivity','Particle orientation','Relative tape sensitivity','Print-through ratio']::text[],ARRAY['Confusing remanence, the leftover magnetization, with coercivity, the resistance to being magnetized or erased','Assuming higher remanence alone guarantees better sound while ignoring noise and distortion','UNSAFE: Bringing recorded tapes near a running bulk eraser or degausser, which erases the remanent signal; keep media clear until you intend to erase it']::text[],ARRAY['Reading a tape datasheet''s magnetic specifications','Explaining output differences between tape formulations','Understanding what a bulk eraser removes from a tape']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c100986a-b656-5f56-aeae-d93db92ae486' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Remanence'),'[^a-z0-9]','','g'));
