INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0c0e1a8c-a09c-50ba-92ce-47331f01b700','Remanent head field','A residual magnetic field remaining at a tape head''s gap because the head core and pole pieces have become permanently (DC) magnetized, for example by a magnetized tool, static, or a switching transient. This standing field adds noise and can partially erase recorded high frequencies, and it is removed by demagnetizing the head.','A tape head can become slightly magnetized by accident. Then a weak magnetic field stays at its gap all the time. This leftover field adds hiss and can wipe some high notes off the tape. Demagnetizing the head clears it.','The term names the residual field that makes head demagnetization necessary, protecting recordings and keeping the noise floor low.','A technician demagnetizes heads and metal guides on a schedule to remove any remanent head field before it degrades tapes.','Heads & maintenance',ARRAY['Pole-piece magnetization','Remanence','Pole-tip recession','Recorded wavelength','Reference tape']::text[],ARRAY['UNSAFE: Energizing or switching off the head demagnetizer close to the heads, or moving it quickly; switch on well away, approach and withdraw slowly, then switch off far away','UNSAFE: Demagnetizing with recorded tapes on or near the machine, risking their erasure; remove all tapes first','Using magnetized tools near the heads, which creates the remanent field in the first place','Assuming newer or well-built machines never need head demagnetization']::text[],ARRAY['Routine maintenance before a recording session','Troubleshooting a slow rise in tape hiss','Preparing a transport for irreplaceable archival tapes']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0c0e1a8c-a09c-50ba-92ce-47331f01b700' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Remanent head field'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0c0e1a8c-a09c-50ba-92ce-47331f01b700','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0c0e1a8c-a09c-50ba-92ce-47331f01b700' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bccdc4e7-96ec-5b03-9b5f-06fbb376f714','Replay time constant','A replay (reproduce) time constant is an RC time value, expressed in microseconds, that defines a transition or turnover frequency in the standardized playback equalization of an analog tape machine. Each standard specifies a set of time constants, such as a 3180 microsecond bass turnover together with a high-frequency transition of 50 microseconds for NAB, 35 microseconds for IEC/CCIR at 15 in/s, or 17.5 microseconds for AES at 30 in/s, defining where the reproduce amplifier changes response slope to complement the recorded flux.','Tape machines boost or cut certain tones so a recording plays back right. A time constant is a number, in millionths of a second, that marks where a boost or cut begins. Each tape standard sets its own values. That way any machine plays a tape the same way.','It codifies the reproduce equalization curve so any correctly aligned machine reproduces a standard recording with flat, matched frequency response, making tapes interchangeable between studios.','A technician selects the correct time-constant set, such as NAB or IEC, for the tape speed and format, then aligns the reproduce equalization to a calibration tape so playback matches the standard.','Reproduce Equalization',ARRAY['Reproducer test tape','NAB equalization','IEC/CCIR equalization','Reproduce equalization','Transition frequency','Reference flux']::text[],ARRAY['Confusing the replay time constant with the record (pre-emphasis) equalization; record and reproduce curves are specified separately.','Assuming one time-constant set fits every speed, when 7.5, 15 and 30 in/s use different high-frequency transitions.','Treating a time constant as a fixed frequency instead of converting it: frequency in hertz equals 159155 divided by the time constant in microseconds.','UNSAFE: Reaching into an open, powered tape machine to trim reproduce-equalization presets without lockout and shock-safety practice for exposed mains wiring.']::text[],ARRAY['Setting a two-track mastering deck to the NAB curve before transferring a 15 in/s studio master.','Choosing IEC (CCIR) equalization to correctly play a European archival tape.','Aligning a multitrack recorder''s reproduce electronics to a calibration tape at the start of a session.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bccdc4e7-96ec-5b03-9b5f-06fbb376f714' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Replay time constant'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bccdc4e7-96ec-5b03-9b5f-06fbb376f714','e9c64f09-41cc-480b-affc-4e0919253e5c',true
