INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ab26f278-f754-5120-82d8-55ae08da5f0d','Reproducer test tape','A reproducer (calibration) test tape is a precision-recorded reference tape carrying reference-fluxivity tones at defined frequencies and levels, produced to a recognized standard such as those from Magnetic Reference Laboratory. It is essentially the same object as a reference or calibration tape, the name emphasizing use on the reproduce side: it is used to align and verify a tape machine''s reproduce (playback) chain, including reference level, reproduce equalization, and head azimuth, independently of the machine''s own record electronics.','A test tape is a factory-made tape with known test tones on it. You play it to check that your tape machine reads a tape correctly. It lets you set the level, the tone balance, and the head angle to a shared standard.','It provides an external, traceable reference so the reproduce path can be standardized, ensuring tapes recorded elsewhere play back at correct level and frequency response.','At the start of a transfer or session the technician plays the test tape''s tones and adjusts reproduce level, equalization, and azimuth for correct readings before recording or archiving.','Calibration',ARRAY['Replay time constant','Reproduce head','Azimuth','Reference flux','Reproduce equalization','Fluxivity']::text[],ARRAY['Assuming a reference fluxivity different from the one the test tape was recorded at, giving a wrong reference-level alignment.','Threading the calibration tape backward or tails-out so the recorded section runs against the heads incorrectly.','Recording over or splicing the alignment tape, destroying an expensive traceable reference.','Ignoring fringing and low-frequency effects when a narrow reproduce head plays a full-track test recording.']::text[],ARRAY['Aligning an archival transfer deck before digitizing a fragile master tape.','Verifying reproduce azimuth on a two-track machine using the tape''s high-frequency azimuth tones.','Checking that a rented multitrack''s playback level matches the studio''s reference.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ab26f278-f754-5120-82d8-55ae08da5f0d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reproducer test tape'),'[^a-z0-9]','','g'));
