SELECT 'ab26f278-f754-5120-82d8-55ae08da5f0d','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ab26f278-f754-5120-82d8-55ae08da5f0d' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc76d998-11ba-5185-8029-197d94dbfc8a','Retentivity','Retentivity is the maximum residual magnetic flux density (remanence) that a magnetic material, such as a tape''s oxide coating, retains after being magnetized to saturation and the applied field removed. It is the saturation value of remanence and, with coercivity, characterizes a material''s suitability for permanent magnetic storage.','Retentivity is how much magnetism a tape keeps after you magnetize it fully and take the magnet away. High retentivity means the tape holds a strong signal on its own. That stored magnetism is what a player later reads back as sound.','It quantifies how strongly a recording medium retains a magnetic pattern, which sets how much signal a recorded tape can hold and reproduce.','Technicians rely on retentivity indirectly when choosing tape stock; a higher-retentivity oxide supports higher output and better signal-to-noise for a given track width.','Magnetic Properties',ARRAY['Remanence','Saturation remanence','Coercivity','Saturation magnetization','Self-demagnetization']::text[],ARRAY['Confusing retentivity (remanence after saturation) with coercivity (the field needed to demagnetize the material).','Assuming higher retentivity alone guarantees better high-frequency performance; short-wavelength output also depends on coercivity and self-demagnetization.','Treating retentivity and reproduced output level as identical, when retentivity is a material property rather than a system measurement.']::text[],ARRAY['Comparing tape stocks when specifying a formulation for a mastering session.','Explaining why a fully erased tape shows near-zero remanence.','Assessing why an old, poorly stored tape reproduces at reduced level.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc76d998-11ba-5185-8029-197d94dbfc8a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Retentivity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dc76d998-11ba-5185-8029-197d94dbfc8a','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dc76d998-11ba-5185-8029-197d94dbfc8a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '46d624aa-9836-5388-9772-e96335a862c7','Saturation magnetization','Saturation magnetization (Ms) is the maximum magnetization a magnetic material can attain when a sufficiently strong applied field aligns essentially all of its magnetic domains or particles; beyond this point, increasing the field produces no further increase in magnetization.','A tape can only be magnetized so much. Saturation magnetization is that top limit. When all its tiny magnetic bits point the same way, the tape is full. Adding more field then does nothing.','It sets the ceiling on how much magnetic moment a material can hold, bounding the strongest signal a recording medium can store.','It underlies why recording levels cannot rise without limit: as level nears the tape''s saturation, added signal no longer increases magnetization and distortion rises.','Magnetic Properties',ARRAY['Saturation remanence','Retentivity','Saturation output','Coercivity','Remanence']::text[],ARRAY['Confusing saturation magnetization (maximum magnetization while the field is applied) with saturation remanence (what remains after the field is removed).','Assuming the tape stores its full saturation magnetization, when only the remanent fraction stays once the field is gone.','Equating saturation magnetization directly with a machine''s saturation output level, which also depends on head and wavelength effects.']::text[],ARRAY['Understanding why heavy tape saturation compresses and distorts loud peaks.','Comparing oxide and metal-particle formulations by their saturation magnetization.','Explaining the upper end of a tape''s recording transfer characteristic.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='46d624aa-9836-5388-9772-e96335a862c7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saturation magnetization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '46d624aa-9836-5388-9772-e96335a862c7','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='46d624aa-9836-5388-9772-e96335a862c7' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1d2ba210-fc3e-517b-963f-5deef3d3bfd0','Saturation output','Saturation output is the maximum reproduced output obtainable from a tape as the recording level is increased: output first rises with record level, then levels off (saturates) because the tape''s magnetization approaches its remanent limit and can store no additional signal.','Turn up the recording level and the tape gets louder, up to a point. Saturation output is the highest playback level the tape can give. Past it, recording harder does not get louder; it only adds distortion.','It marks the top of a tape''s usable dynamic range on the loud side, defining how much signal the medium can deliver before it stops responding.','Engineers push level toward saturation for deliberate tape compression and warmth, but back off before excessive distortion when clean headroom is needed.','Recording Level',ARRAY['Saturation output level','Saturation magnetization','Maximum output level','Remanence','Tape compression']::text[],ARRAY['Confusing saturation output (the leveling-off of playback output) with clipping in the electronics.','Assuming saturation behaves the same at all frequencies; high frequencies saturate at lower levels than low frequencies.','Believing more record level always yields more output once the tape is already in saturation.']::text[],ARRAY['Driving a mix bus into tape saturation for glue and coloration.','Explaining why a hot kick drum stops getting louder on tape.','Setting record level to stay below saturation for a clean classical recording.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1d2ba210-fc3e-517b-963f-5deef3d3bfd0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saturation output'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1d2ba210-fc3e-517b-963f-5deef3d3bfd0','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1d2ba210-fc3e-517b-963f-5deef3d3bfd0' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7be283af-bbe5-587e-90ae-5c9a8a269538','Saturation output level','Saturation output level (SOL) is a specified tape parameter giving the reproduced output, relative to a reference, that a tape reaches at saturation when driven at a defined short-wavelength (high) frequency, commonly 10 kHz, 12.5 kHz or 16 kHz at a stated speed. Unlike maximum output level (MOL), which is fixed by a low-frequency distortion limit, SOL characterizes the tape''s short-wavelength high-frequency headroom.','Saturation output level, or SOL, measures how much high-frequency signal a tape can hold before it maxes out. It is checked with a high test tone, such as 10 kilohertz. It tells you the tape''s headroom for treble sounds.','It quantifies short-wavelength headroom so users can compare how much high-frequency energy different tape stocks store before saturating.','A mastering engineer reads SOL figures on a tape datasheet to judge how a stock handles bright, high-transient material at a given speed.','Recording Level',ARRAY['Saturation output','Maximum output level','Short-wavelength level','Saturation magnetization','Self-demagnetization']::text[],ARRAY['Confusing SOL (short-wavelength, high-frequency saturation) with MOL, which is a 1 kHz distortion-limited figure.','Comparing SOL numbers from datasheets measured at different frequencies or tape speeds as if equivalent.','Assuming a tape with high MOL automatically has high SOL, when high-frequency saturation often limits first.']::text[],ARRAY['Selecting a tape formulation for cymbal-heavy material at 30 in/s.','Reading a manufacturer datasheet to compare high-frequency headroom of two stocks.','Explaining why loud high frequencies distort on tape before loud bass does.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7be283af-bbe5-587e-90ae-5c9a8a269538' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saturation output level'),'[^a-z0-9]','','g'));
