WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7be283af-bbe5-587e-90ae-5c9a8a269538' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc184f4f-f3e3-58f5-b0f7-f09d8e7ef2b2','Saturation remanence','Saturation remanence (Mrs, sometimes Brs) is the remanent magnetization that remains in a material after it has been magnetized to saturation and the applied field removed, i.e. the maximum possible remanence. It is numerically the retentivity of the material and is a key point on the hysteresis (B-H) loop.','Magnetize a tape as hard as it will go, then take the magnet away. Saturation remanence is the magnetism that stays behind. It is the most a tape can hold on its own after full magnetizing.','It defines the strongest permanent magnetic state a medium can hold, bounding the maximum signal a saturated recording leaves on the tape.','It appears in tape and head material specifications; a high saturation remanence in the oxide supports high recorded output for a given coating.','Magnetic Properties',ARRAY['Retentivity','Remanence','Saturation magnetization','Coercivity','Hysteresis loop']::text[],ARRAY['Confusing saturation remanence (after saturation, field removed) with saturation magnetization (present while the saturating field is applied).','Using remanence and saturation remanence interchangeably, when ordinary remanence can follow a non-saturating field.','Assuming saturation remanence equals playback output, when wavelength, head, and spacing losses reduce actual reproduced level.']::text[],ARRAY['Reading a hysteresis (B-H) loop to characterize a tape oxide.','Comparing squareness, the remanence-to-saturation ratio, of tape formulations.','Explaining the residual signal left after a strong overload recording.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc184f4f-f3e3-58f5-b0f7-f09d8e7ef2b2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saturation remanence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dc184f4f-f3e3-58f5-b0f7-f09d8e7ef2b2','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dc184f4f-f3e3-58f5-b0f7-f09d8e7ef2b2' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5abdafad-5b0f-5eec-93eb-93dedafb2d10','Sel-sync track','A Sel-Sync (Selective Synchronous) track is a track on a multitrack recorder whose record head is temporarily switched to act as its own playback head, so previously recorded material on that track is reproduced from the same physical position at which new tracks are being recorded. This removes the time offset that would arise from monitoring the separate reproduce head, keeping overdubs in synchronization; the technique was introduced by Ampex in 1955.','On a multitrack tape machine, the record and play heads sit apart. That gap would make an overdub arrive late. Sel-Sync plays an already-recorded track back through its own record head instead. So a new part you add lines up in time with the old ones.','It lets musicians overdub new parts in time with existing tracks by eliminating the record-to-reproduce head spacing delay during synchronous recording.','An engineer switches selected tracks to Sel-Sync (sync) mode so the performer hears earlier takes in time while recording new tracks on the same machine.','Recording Technique',ARRAY['Overdubbing','Multitrack recording','Record head','Reproduce head','Punch-in','Monitor mode']::text[],ARRAY['Forgetting that a record head used for sync playback has poorer high-frequency response than the dedicated reproduce head, so sync monitoring sounds duller.','Leaving tracks in Sel-Sync (sync) monitoring during final playback instead of switching to the reproduce head.','Assuming Sel-Sync removes all timing error, when residual gap and alignment effects can still cause slight offset.']::text[],ARRAY['Building a song part by part on a 24-track analog machine.','Punching in a corrected phrase while the artist monitors existing tracks in sync.','Explaining why early multitrack overdubs stayed in time without a separate delay.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5abdafad-5b0f-5eec-93eb-93dedafb2d10' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sel-sync track'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5abdafad-5b0f-5eec-93eb-93dedafb2d10','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5abdafad-5b0f-5eec-93eb-93dedafb2d10' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3d68cde3-f12c-542e-bdcf-529378fadc59','Self-demagnetization','Self-demagnetization is the tendency of a recorded magnetic pattern to partially demagnetize itself because adjacent regions of opposite polarity set up internal demagnetizing fields that oppose the stored magnetization. The effect grows as recorded wavelength shortens, so it most strongly reduces short-wavelength (high-frequency) signals, especially in thicker or lower-coercivity coatings.','A recording on tape is made of tiny magnets, and nearby ones point opposite ways. Their fields fight each other and weaken the signal. This is worst for high notes, whose magnetic pattern is packed very close together. Better tape resists this more.','It explains a basic limit on high-frequency recording: the medium erodes its own short-wavelength signal, which record equalization and high-coercivity tape must counter.','It is why engineers use higher tape speeds and high-coercivity formulations for extended high-frequency response, and why high-frequency pre-emphasis is applied when recording.','Magnetic Properties',ARRAY['Short-wavelength level','Coercivity','Remanence','Record equalization','Wavelength','Retentivity']::text[],ARRAY['Confusing self-demagnetization (internal to the recorded tape) with spacing loss or gap loss (playback head geometry effects).','Assuming higher recording level fixes high-frequency loss, when excessive short-wavelength level worsens self-demagnetization.','Believing it only affects old tapes, when it is inherent to the recording process at short wavelengths.','UNSAFE: Trying to refresh or erase tape with an improvised strong magnet or unguarded bulk degausser, risking injury and wiping adjacent recordings; follow the manufacturer''s degausser procedure.']::text[],ARRAY['Choosing 30 in/s over 15 in/s to improve high-frequency retention.','Explaining why a dubbed copy loses treble compared with the master.','Specifying high-coercivity tape for bright program material.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3d68cde3-f12c-542e-bdcf-529378fadc59' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Self-demagnetization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3d68cde3-f12c-542e-bdcf-529378fadc59','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3d68cde3-f12c-542e-bdcf-529378fadc59' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '59b6fc1f-dea5-5902-82ef-11eda5b1fec0','Short-wavelength level','Short-wavelength level is the recorded or reproduced signal level at short recorded wavelengths, that is at high frequencies for a given tape speed, where cumulative losses such as self-demagnetization, spacing, thickness and gap losses are significant. It is used as a reference point when aligning high-frequency response and when characterizing head and tape efficiency.','On tape, high notes are stored as very short magnetic patterns. Short-wavelength level is how strong those tiny high-frequency signals are. It matters because short patterns lose strength easily. So it shows how well a machine handles treble.','It provides a high-frequency benchmark for judging and aligning the short-wavelength, treble performance of a tape and head system.','Technicians check short-wavelength reference tones on a calibration tape to set and verify high-frequency reproduce response and head contact.','Calibration',ARRAY['Self-demagnetization','Wavelength','Reproducer test tape','Spacing loss','Saturation output level','Azimuth']::text[],ARRAY['Confusing short wavelength (high frequency) with low level; wavelength depends on frequency and tape speed, not amplitude.','Forgetting that a given frequency is a shorter physical wavelength as tape speed drops, worsening losses.','Blaming the tape for low short-wavelength level when dirty heads or poor tape-to-head contact are the real cause.']::text[],ARRAY['Adjusting reproduce high-frequency equalization to a short-wavelength reference tone.','Diagnosing dull playback caused by head wear or spacing loss.','Comparing high-frequency output between two tape speeds.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='59b6fc1f-dea5-5902-82ef-11eda5b1fec0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Short-wavelength level'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
