INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '54d99553-cfd2-585b-a574-9cbf615a9531','Span resonance','Span resonance is the natural mechanical resonance of a free, unsupported span of tape between two contact points such as guides or heads, which behaves like a stretched string. Friction-driven stick-slip excitation of this resonance produces longitudinal vibration that frequency-modulates the signal, heard as scrape flutter and modulation noise; the resonant frequency depends on span length, tension, and the tape''s elasticity and mass.','The tape between two rollers is like a guitar string stretched tight. Rubbing against the heads can make it vibrate at its own pitch. That vibration smears the sound and adds a rough noise. Shorter, tighter spans vibrate higher and cause less trouble.','Understanding span resonance explains one source of flutter and modulation noise, guiding transport design to keep the free-span resonance out of the audible modulation band.','A scrape-flutter idler or roller is placed in the free span to shorten it and damp the resonance, reducing high-frequency flutter on precision machines.','Transport / Flutter',ARRAY['Scrape flutter','Flutter','Modulation noise','Tape tension','Flutter idler','Wow and flutter']::text[],ARRAY['Confusing span resonance (a mechanical, string-like resonance of the tape) with electrical resonance in the audio circuitry.','Assuming higher tension always cures it, when excessive tension causes head wear and other transport problems.','Overlooking a seized or dirty scrape-flutter idler as the cause of returning high-frequency flutter.']::text[],ARRAY['Servicing a mastering deck to restore its scrape-flutter idler.','Diagnosing a rough, grainy high-frequency modulation on playback.','Explaining why free tape length between heads is kept short in precision transports.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='54d99553-cfd2-585b-a574-9cbf615a9531' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Span resonance'),'[^a-z0-9]','','g'));
