INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4056709f-a1e0-56b1-8acc-53280eb4e745','Stagger correction','Stagger correction is the compensating time adjustment applied when the record or reproduce heads for different channels are physically offset (staggered) along the tape path, as in staggered-head stereo. Because each channel meets the tape at a different point, its signal is displaced in time by the head spacing divided by the tape speed; stagger correction restores channel time alignment, either by delaying the leading channel or by matching the head stagger between recorder and reproducer.','In some old stereo machines the two heads sat apart along the tape, not side by side. That made one channel play a moment before the other. Stagger correction lines the two channels back up in time. It uses a matching head layout or an added delay.','It preserves correct stereo timing and phase when heads are staggered, preventing the two channels from arriving at different moments.','When transferring staggered-head stereo tapes, an archivist reproduces them on a matching staggered head or applies a calculated delay to one channel to realign the audio.','Tape Format',ARRAY['Staggered-head stereo','Stagger offset','Azimuth','Reproduce head','Phase','Time alignment']::text[],ARRAY['Playing a staggered-head stereo tape on an in-line (stacked) head without correcting the resulting inter-channel delay.','Applying the wrong delay by using head spacing without dividing by the actual tape speed.','Confusing stagger (a lengthwise time offset between channels) with azimuth error (a tilt of the head gap).']::text[],ARRAY['Restoring 1950s staggered stereo reels for digitization.','Realigning two channels that arrive at different times on an unusual head layout.','Setting a channel delay to match a known head offset during archival transfer.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4056709f-a1e0-56b1-8acc-53280eb4e745' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stagger correction'),'[^a-z0-9]','','g'));
