WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4056709f-a1e0-56b1-8acc-53280eb4e745' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8425c228-1fd5-5ec0-9847-877dab691cd9','Stagger offset','Stagger offset is the physical lengthwise separation between staggered heads, or between the two channels'' recorded positions on the tape, and the corresponding time offset it produces between channels. The time offset equals the head spacing divided by the tape speed, so a fixed physical stagger yields a larger time displacement at lower tape speeds.','Stagger offset is the gap between two heads placed apart along the tape. Because the tape reaches one head first, that channel is early. The offset is both this distance and the small time gap it makes. Slower tape means a bigger time gap.','It quantifies the built-in inter-channel time displacement of a staggered-head system, the value that stagger correction must cancel.','An archivist measures or looks up the stagger offset of a legacy format to calculate the delay needed to realign the channels during transfer.','Tape Format',ARRAY['Staggered-head stereo','Stagger correction','Tape speed','Reproduce head','Time alignment','Phase']::text[],ARRAY['Treating the stagger offset as a fixed time value, when the time offset changes with tape speed for the same physical spacing.','Confusing stagger offset (a lengthwise separation) with track spacing across the tape width.','Ignoring the offset entirely and getting a smeared or out-of-phase stereo image.']::text[],ARRAY['Calculating the channel delay from a known head spacing and speed.','Documenting the format parameters of an archival staggered stereo tape.','Explaining stereo phase problems on early two-track tapes.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8425c228-1fd5-5ec0-9847-877dab691cd9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stagger offset'),'[^a-z0-9]','','g'));
