SELECT '8425c228-1fd5-5ec0-9847-877dab691cd9','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8425c228-1fd5-5ec0-9847-877dab691cd9' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7b1b4a9d-4781-5031-8997-f9ea8e11a3de','Staggered-head stereo','Staggered-head stereo is an early two-channel tape format in which the two heads are staggered, offset from one another along the tape path, rather than stacked vertically in-line, so the left and right channels are recorded at physically separated points on the tape. Correct reproduction requires a machine with the same head stagger or an equivalent inter-channel delay (stagger correction); it was later largely superseded by the stacked, in-line head format.','Staggered-head stereo is an old way of putting two channels on tape. The two heads sat apart along the tape instead of one above the other. So the left and right sounds were recorded at different spots. You need a matching machine, or a small delay, to play it back in time.','It was an early method for recording two-channel stereo on tape before stacked in-line heads became standard, using separated heads to keep the two tracks apart.','Archivists identify staggered-head tapes and reproduce them on a matching head or apply stagger correction so the two channels play in correct time alignment.','Tape Format',ARRAY['Stagger offset','Stagger correction','In-line head','Two-track stereo','Reproduce head','Azimuth']::text[],ARRAY['Playing staggered-head tapes on a modern in-line (stacked) head machine without applying a compensating delay.','Confusing staggered heads (offset along the tape) with staggered tracks or track-width format differences.','Assuming the two channels are time-aligned as recorded, when they carry a built-in offset that must be corrected.']::text[],ARRAY['Transferring 1950s pre-recorded stereo reels held in an archive.','Identifying why an old stereo tape sounds phasey on standard equipment.','Selecting the right playback head configuration for a legacy format.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7b1b4a9d-4781-5031-8997-f9ea8e11a3de' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Staggered-head stereo'),'[^a-z0-9]','','g'));
