WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7b1b4a9d-4781-5031-8997-f9ea8e11a3de' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bb929e6d-8603-5e00-b7c1-ed91c5c32f50','Standard reference level','The standard reference level is a defined magnetic recording flux level, or reference fluxivity, expressed in nanowebers per meter (nWb/m), that a tape machine is aligned to reproduce at a specified electrical level, typically 0 VU. Common reference fluxivities include 185, 250, 320, and 355 nWb/m; recorded from a calibration tape, it fixes the relationship between tape flux and meter/console level so recordings are interchangeable between machines and studios.','A tape machine needs to agree on what "zero" means. The standard reference level sets that. It is a fixed amount of magnetism on the tape, measured in nanowebers per meter. Engineers play a special test tape and adjust the machine to match it. Then a recording plays at the same level on any calibrated machine.','It provides a common, machine-independent anchor for record and playback levels so tapes made on one aligned machine reproduce at the correct level on another. Without it, the same tape would play back at different levels on different machines.','During alignment a technician plays a calibration (MRL) tape at the chosen reference fluxivity and adjusts reproduce gain so the meter reads 0 VU, then sets record level to match.','Calibration & Levels',ARRAY['Reference fluxivity','MRL calibration tape','Operating level','Tape sensitivity','Tape headroom','Machine alignment']::text[],ARRAY['Confusing the electrical operating level (such as +4 dBu) with the magnetic reference fluxivity on tape; they are linked by calibration but are not the same quantity.','Assuming every studio uses the same reference fluxivity; a tape recorded at 320 nWb/m plays back at the wrong level on a machine set to 185 nWb/m.','Setting record level before the reproduce chain has been calibrated to the reference tape, so every later adjustment rests on a wrong reference.']::text[],ARRAY['Aligning a tape machine to an MRL calibration tape before a recording session.','Transferring an archival tape and setting playback level to the documented reference fluxivity.','Matching two studios'' machines so a project tape reproduces at the same level in both.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bb929e6d-8603-5e00-b7c1-ed91c5c32f50' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Standard reference level'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
