INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '128c15d4-625a-5892-b935-b947d55b6fd5','Switching-field distribution','Switching-field distribution (SFD) is the statistical spread of the magnetic fields required to reverse, or switch, the magnetization of the individual particles in a magnetic tape coating. A narrow SFD means the particles switch over a small range of applied field, giving a steeper, squarer hysteresis loop, sharper recorded transitions, and better short-wavelength (high-frequency) performance.','A tape''s coating is full of tiny magnetic particles. Each one flips its magnetism at a slightly different field strength. Switching-field distribution describes how spread out those flip points are. A narrow spread lets the tape record sharp, clean changes. That gives better high-frequency sound.','It characterizes how uniformly a tape''s particles respond to the recording field, which controls how sharply magnetic transitions can be written and thus the tape''s resolution and high-frequency output. Manufacturers minimize SFD to improve recording performance.','An engineer meets SFD indirectly through a tape''s rated high-frequency output and bias behavior; tapes with a narrower SFD hold short wavelengths better and are chosen for demanding high-resolution work.','Tape Magnetics',ARRAY['Coercivity','Remanence','Squareness ratio','Bias','Thickness loss','Tape sensitivity']::text[],ARRAY['Confusing switching-field distribution with coercivity; coercivity is the average field needed to demagnetize, while SFD is the spread of switching fields around it.','Assuming a higher-coercivity tape automatically records better; a wide SFD can offset the benefit by smearing the recorded transitions.','Treating SFD as something the engineer sets, when it is a fixed property of the tape formulation.']::text[],ARRAY['Comparing tape formulations for high-frequency headroom in mastering.','Explaining why a squarer hysteresis loop yields sharper recorded transitions.','Evaluating a new tape stock''s short-wavelength performance.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='128c15d4-625a-5892-b935-b947d55b6fd5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Switching-field distribution'),'[^a-z0-9]','','g'));
