SELECT '9c26d9bb-7c55-5aed-a219-79750096e0e8','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9c26d9bb-7c55-5aed-a219-79750096e0e8' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a6c12c65-da73-5fe1-94a3-958de7573790','Take-up tension','Take-up tension is the pulling force applied to the tape as it is wound onto the take-up reel. It controls how tightly and evenly the tape pack is wound and, together with supply-side hold-back tension, helps maintain stable tape-to-head contact and constant tape speed; because torque equals tension times winding radius, transports must vary reel torque as the pack grows to keep take-up tension roughly constant.','As tape winds onto the take-up reel, something pulls it snug. That pull is the take-up tension. It decides how tightly and neatly the roll winds. Too little makes a loose, sloppy pack; too much can stress the tape. The machine adjusts the reel pull as the roll grows to keep the tension steady.','It ensures the tape winds into a firm, even pack and stays in proper contact with the guides and heads, which protects the tape and keeps playback stable. Constant take-up tension prevents speed and contact problems as the reel diameter changes.','A technician checks take-up tension, often with a tension gauge, during transport service so tapes pack cleanly and do not scrape, cinch, or lose head contact.','Tape Transport',ARRAY['Hold-back tension','Tension arm','Reel servo','Tape pack','Capstan','Tape-path skew']::text[],ARRAY['Setting take-up tension too low, producing a loose pack that spills or cinches and causes speed instability.','Setting it too high, over-stressing the tape and its edges and increasing wear.','Assuming take-up tension stays constant on its own; without torque control it falls as the take-up pack grows.']::text[],ARRAY['Adjusting reel-motor tension so archival tapes wind into a smooth, protective pack.','Diagnosing a loose or spoked tape pack caused by low take-up tension.','Servicing a transport whose tension drifts as the reel fills.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a6c12c65-da73-5fe1-94a3-958de7573790' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Take-up tension'),'[^a-z0-9]','','g'));
