INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '352389b2-1a27-519b-a0f6-3881386ad2bf','Tape headroom','Tape headroom is the level margin, in decibels, between the standard reference/operating level and the level at which the tape reaches a defined overload, commonly the maximum output level (MOL), the point where the third-harmonic distortion of a mid-frequency tone reaches 3%. It expresses how far a signal can exceed the reference level before tape saturation and distortion become objectionable, and it depends on tape formulation, speed, bias, and reference fluxivity.','Every tape sounds clean up to a point, then it starts to distort. Tape headroom is the safety margin between your normal "zero" level and that distortion point. More headroom means you can push louder peaks before the sound breaks up. It is measured in decibels. Faster speeds and better tapes give more of it.','It tells the engineer how much peak level above the reference the tape can accept before saturating, guiding safe record levels. It exists because magnetic tape overloads gradually, so knowing the margin prevents unwanted distortion, or lets it be used deliberately.','An engineer sets record levels so program peaks stay within the tape''s headroom above 0 VU, choosing a higher reference fluxivity or faster speed when more clean level is needed.','Calibration & Levels',ARRAY['Maximum output level','Standard reference level','Tape saturation','Tape sensitivity','Bias','Reference fluxivity']::text[],ARRAY['Confusing tape headroom with the console''s electronic headroom; the tape saturates well before most electronics clip.','Assuming headroom is fixed; it changes with tape type, speed, bias, and the chosen reference fluxivity.','Recording hot "for warmth" without knowing the maximum output level, then finding peaks distorted beyond recovery.']::text[],ARRAY['Deciding how hot to print drums before the tape audibly saturates.','Choosing 30 ips over 15 ips to gain clean high-frequency headroom.','Selecting a higher reference fluxivity to gain level over the noise floor while tracking headroom.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='352389b2-1a27-519b-a0f6-3881386ad2bf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape headroom'),'[^a-z0-9]','','g'));
