INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd2da6872-1018-512f-bb1d-5faa5b09214f','Tape lifter','A tape lifter is a mechanical device, typically a solenoid- or cam-actuated pin or post, that moves the tape away from the head faces during fast-wind (fast-forward and rewind) modes. Lifting the tape off the heads during high-speed winding reduces head and tape wear and avoids loud, garbled high-speed playback; the lifters can usually be defeated by an edit or cue function so the tape contacts the heads for audible spooling to locate edit points.','When a tape machine winds fast, you do not want the tape scraping across the heads. A tape lifter is a small pin or arm. It pushes the tape away from the heads. It does this during fast-forward and rewind, which saves wear on both the tape and the heads. A cue or edit button lets the tape touch the heads again. Then you can hear it while winding to find a spot.','It protects the heads and tape from needless wear during high-speed winding and avoids blasting loud, garbled audio, while still allowing head contact on demand to locate edit points. It exists because full-speed head contact during wind is abrasive and rarely wanted.','During editing, an operator holds the cue or edit control to defeat the lifters and rocks the reels by hand or spools slowly, listening at the heads to find the exact cut point.','Tape Transport',ARRAY['Capstan','Tension arm','Reproduce head','Cue mode','Splice editing','Tape-path skew']::text[],ARRAY['Assuming a fault when no audio is heard during fast-wind; the lifters are simply holding the tape off the heads by design.','Editing with worn or misadjusted lifters that fail to retract fully, so the tape never seats properly on the heads for cueing.','Leaving lifters misaligned so the tape is pulled off its guided path, causing skew or edge damage.']::text[],ARRAY['Spooling quickly to a section while the lifters keep the tape off the heads.','Defeating the lifters to rock the tape by hand and find a splice point.','Servicing lifters that no longer lift, causing excess head wear during rewind.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d2da6872-1018-512f-bb1d-5faa5b09214f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape lifter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd2da6872-1018-512f-bb1d-5faa5b09214f','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d2da6872-1018-512f-bb1d-5faa5b09214f' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '65555d4d-3aea-54c3-914a-8696de0266ba','Tape sensitivity','Tape sensitivity is the reproduce output a tape delivers for a given recording field, expressed relative to a reference tape, usually at a specified frequency and bias. It quantifies how efficiently a particular tape converts the record signal into recorded flux; sensitivity varies between formulations and production batches, so it is checked and compensated during machine alignment.','Give two tapes the same recording signal and they can play back at slightly different volumes. Tape sensitivity measures that difference against a standard reference tape. A more sensitive tape gives more output for the same input. It changes from one tape type or batch to another. So engineers check it when they set up a machine.','It tells the engineer how a given tape''s output compares to the reference, so record and playback levels can be adjusted to keep recordings consistent. It matters because tape-to-tape and batch-to-batch differences would otherwise shift recorded levels.','During alignment a technician records a tone on the working tape and compares its output to the reference-tape level, trimming record calibration to compensate for the tape''s sensitivity.','Tape Magnetics',ARRAY['Standard reference level','Reference fluxivity','Bias','Tape headroom','Machine alignment','Remanence']::text[],ARRAY['Assuming a fresh box of the same brand has identical sensitivity; batch differences shift level and must be rechecked.','Setting record calibration on the working tape before the reproduce chain is aligned to the reference tape.','Confusing sensitivity (output for a given input) with headroom (how hot the tape can go before overload).']::text[],ARRAY['Re-aligning record calibration when switching to a new tape stock.','Compensating for a batch of tape that reads a decibel low against the reference tape.','Matching recorded level across reels from different production runs.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='65555d4d-3aea-54c3-914a-8696de0266ba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape sensitivity'),'[^a-z0-9]','','g'));
