SELECT '65555d4d-3aea-54c3-914a-8696de0266ba','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='65555d4d-3aea-54c3-914a-8696de0266ba' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9f558aff-5de4-5434-9929-fed47a9c92ab','Tape tenting','Tape tenting is the localized lifting of the tape away from the head so that it bridges, or tents, over a raised point, commonly a contaminant particle, debris clump, or defect trapped between tape and head. Because the tape''s bending stiffness holds it off the surface across a region wider than the obstruction, the increased head-to-tape spacing causes signal loss, a dropout, over an area larger than the particle itself.','If a speck of dirt gets stuck between the tape and the head, the tape cannot press flat. It rises over the speck like a tent over a pole. This lifts the tape off the head for a short stretch. That gap weakens the signal and causes a dropout. The dead spot is wider than the speck that caused it.','Naming tenting helps a technician recognize a mechanical, spacing-related cause of dropouts, distinct from magnetic problems, so the fix is cleaning and contamination control rather than re-recording. It highlights why even tiny debris causes audible losses through increased head-to-tape spacing.','When intermittent dropouts appear, a technician cleans the heads, guides, and tape path to remove the particles that tent the tape off the heads, and keeps the tape and environment free of debris.','Tape-Head Interface',ARRAY['Dropout','Spacing loss','Head-to-tape contact','Thickness loss','Tape-path coplanarity','Shedding']::text[],ARRAY['Blaming dropouts on the recording when a contaminant is tenting the tape off the head during playback.','Cleaning only the heads and ignoring the guides and rollers, where debris also tents the tape.','UNSAFE: cleaning heads and the tape path with unapproved solvents or without ventilation; use only manufacturer-approved cleaners and follow the solvent''s safety data sheet for fumes, skin contact, and flammability.']::text[],ARRAY['Diagnosing brief dropouts caused by a shed particle bridging the tape off the head.','Cleaning the tape path on an archival transfer to eliminate tenting dropouts.','Explaining why a dropout is wider than the debris speck that caused it.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9f558aff-5de4-5434-9929-fed47a9c92ab' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape tenting'),'[^a-z0-9]','','g'));
