INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bef10f58-95f7-5321-bd47-db41938b7ae0','Tape-path coplanarity','Tape-path coplanarity is the condition in which all tape-guiding elements, including supply and take-up guides, rollers, scrape-flutter idlers, and head faces, are aligned so the tape travels in a single common plane without being forced to twist, tilt, or ride up and down. Departures from coplanarity make the tape weave or skew, producing edge damage, unstable head contact, and azimuth and tracking errors.','A tape should travel flat, like a belt running straight between pulleys. Coplanarity means every guide, roller, and head lines up in the same plane. Then the tape does not twist or ride up and down. If parts are out of plane, the tape weaves, wears at the edges, and loses steady contact with the heads.','It keeps the tape flat and steady across the heads so head contact, azimuth, and tracking stay correct and the tape edges are not stressed. Proper coplanarity is the geometric foundation for stable, low-error playback.','During transport alignment a technician checks and shims guide and roller heights so the tape runs in one plane, correcting weave, edge curl, or uneven head wrap.','Tape Path',ARRAY['Tape-path skew','Azimuth','Zenith','Tape guide','Head wrap','Tension arm']::text[],ARRAY['Adjusting head azimuth to chase a problem actually caused by out-of-plane guides.','Ignoring guide and roller height, so the tape rides up or down and weaves across the heads.','Assuming coplanarity is set once forever; worn guides and rollers drift and reintroduce skew.']::text[],ARRAY['Setting guide heights so the tape runs flat across the head stack.','Curing tape weave and edge damage traced to a guide out of plane.','Restoring a serviced transport''s geometry before checking azimuth.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bef10f58-95f7-5321-bd47-db41938b7ae0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape-path coplanarity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bef10f58-95f7-5321-bd47-db41938b7ae0','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bef10f58-95f7-5321-bd47-db41938b7ae0' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2cac10d2-0d11-5386-b84f-1589e7f2ef92','Tape-path resonance','Tape-path resonance is the mechanical resonance of the free spans of tape between guides, which vibrate longitudinally like a stretched string and modulate the tape speed, the principal cause of scrape flutter. The resonant frequencies depend on span length and tape tension (measured samples fall in the range of a few hundred hertz up to about 1 kHz); shortening the free span with rotating scrape-flutter idlers near the heads raises and damps the resonance to reduce flutter.','Between the guides, the tape is like a stretched string. It can vibrate and "sing" at certain pitches. These vibrations make tiny speed wobbles called scrape flutter. The longer and looser the free length of tape, the lower and worse it gets. Adding a small spinning roller near the heads shortens that length and calms the vibration.','Recognizing tape-path resonance explains a major source of flutter and guides its cure: controlling free-span length and tension. Rotating flutter idlers exploit this by shortening the vibrating span so its resonance rises and is better damped.','A technician keeps scrape-flutter idlers clean, freely rotating, and correctly placed near the heads to shorten the tape''s free span and suppress resonance-driven flutter.','Tape Path',ARRAY['Scrape flutter','Flutter idler','Wow and flutter','Tension arm','Tape guide','Take-up tension']::text[],ARRAY['Blaming high-frequency flutter on the capstan when the free tape span is resonating as scrape flutter.','Leaving a scrape-flutter idler seized or dirty so it no longer damps the resonance.','Assuming more tension always helps; tension shifts the resonant frequency but is not a substitute for a proper flutter idler.']::text[],ARRAY['Tracing a hazy, grainy high-frequency flutter to scrape flutter from tape-path resonance.','Servicing a seized flutter idler to restore damping near the heads.','Explaining why long, unsupported tape spans increase flutter.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2cac10d2-0d11-5386-b84f-1589e7f2ef92' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape-path resonance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2cac10d2-0d11-5386-b84f-1589e7f2ef92','e9c64f09-41cc-480b-affc-4e0919253e5c',true
