INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '959812f0-7b62-5aae-b826-e2b42f3f0083','Tape-path skew','Tape-path skew is a lateral or angular tracking error in which the tape does not travel squarely and flat across the head gaps, instead riding at a slight angle or weaving laterally, so it fails to meet the heads perpendicular to its length. In multitrack work this produces a dynamic azimuth error and inter-track time (phase) displacement; it arises from misaligned guides, non-coplanar tape-path components, uneven tension, or tape deformation.','The tape should cross the heads dead straight and square. Skew is when it drifts sideways or rides at a slight angle. Then different tracks reach the head gap at slightly different times. That smears the timing between tracks and dulls high frequencies. Bad guides, uneven tension, or warped tape all cause it.','Identifying skew separates a mechanical guiding or geometry fault from magnetic or electronic problems, pointing to guide alignment, tension, and coplanarity as the fix. Controlling skew preserves azimuth accuracy and inter-track timing.','A technician checks for skew by watching how the tape rides and by measuring inter-track phase, then corrects guide alignment, tension, and coplanarity so the tape meets the heads squarely.','Tape Path',ARRAY['Azimuth','Tape-path coplanarity','Lateral tape motion','Tape guide','Zenith','Tension arm']::text[],ARRAY['Re-cutting head azimuth to compensate for skew, which only hides a mechanical guiding fault.','Overlooking uneven supply and take-up tension as a cause of dynamic skew.','Confusing static azimuth error with skew, which is a variable, path-driven tilt.']::text[],ARRAY['Diagnosing wandering high-frequency response and inter-track phase as tape skew.','Aligning guides to stop the tape riding at an angle across the heads.','Explaining why a warped or cupped tape tracks unevenly.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='959812f0-7b62-5aae-b826-e2b42f3f0083' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tape-path skew'),'[^a-z0-9]','','g'));
