INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e6a0115b-7629-5af0-a753-4afb7155678a','Track assignment','The routing of a chosen signal source — a console input, group, or bus — to a specific physical track of a multitrack tape machine for recording, and the arming of that track into record-ready while other tracks stay in safe or playback. It determines which material is laid onto which track of the tape.','Track assignment means choosing which tape track a sound records onto. You send a microphone or a mix to one track and arm that track. The other tracks stay safe so they are not erased.','It lets an engineer place each source on a known, separate track so parts stay independent for later overdubbing and mixdown, and it protects tracks that must not be recorded over.','Before a take the engineer routes each channel to its intended track, arms only those tracks, and confirms the assignment on the machine''s channel-status indicators.','Signal Routing',ARRAY['Track configuration','Twin-track','Track pitch','Multitrack recording','Sel-Sync']::text[],ARRAY['Confusing track assignment (routing a source to a track) with track configuration (the fixed physical track layout of the format).','Arming the wrong track and erasing a previously recorded part on the next take.','Assuming a track is protected when it is still in record-ready, so it records over existing material.']::text[],ARRAY['Assigning eight console channels to eight tape tracks for a live drum session.','Routing a submix bus to a single track to bounce several parts down.','Arming only tracks 5 and 6 for an overdub while protecting the rest of the reel.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e6a0115b-7629-5af0-a753-4afb7155678a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track assignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e6a0115b-7629-5af0-a753-4afb7155678a','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e6a0115b-7629-5af0-a753-4afb7155678a' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b5b48393-dc63-5b20-86c1-e8bbbb2abe84','Track configuration','The physical layout of recorded tracks across the width of a magnetic tape: how many tracks there are, their width, their spacing and guard bands, and their direction of travel. Common analog audio configurations include full-track, half-track (two-track), quarter-track, and multitrack formats such as 8-, 16- and 24-track.','Track configuration is how the recorded stripes are arranged across the tape. It sets how many tracks there are, how wide they are, and how they are spaced. Mono, stereo, and multitrack each use a different layout.','It standardises how signal is laid across the tape width so a recording made on one machine can be played back correctly on another that has a matching head format.','A transfer engineer identifies the tape''s track configuration before playback and fits a head stack of the same format to recover every channel cleanly.','Track Formats',ARRAY['Track pitch','Track-format mismatch','Twin-track','Full-track','Quarter-track','Guard band']::text[],ARRAY['Confusing track configuration (the physical layout) with track assignment (routing a source to a track).','Assuming all quarter-inch tapes share one layout, when full-, half- and quarter-track formats differ.','UNSAFE: Switching a demagnetiser on or off near a mounted rare archival tape, which can partially erase an irreplaceable recording; energise it well away and approach slowly.']::text[],ARRAY['Documenting a tape''s track configuration on the box before archiving.','Selecting a quarter-track playback head to match a home-recorded four-track tape.','Recognising a two-track stereo master versus a half-track mono recording.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b5b48393-dc63-5b20-86c1-e8bbbb2abe84' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track configuration'),'[^a-z0-9]','','g'));
