INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '16e39a89-d8cb-5532-b90b-2f2490549c24','Track pitch','The centre-to-centre distance between adjacent tracks on a magnetic tape. In analog audio formats it equals the track width plus the guard band between tracks, and together with track width it fixes how densely tracks are packed and the format''s crosstalk and signal-to-noise trade-off.','Track pitch is the distance from the middle of one track to the middle of the next. A wider pitch spaces the tracks further apart. That lowers bleed between them but fits fewer tracks on the tape.','It sets how many tracks fit across a given tape width and how much guard band separates them, trading track count against crosstalk and noise performance.','When choosing a replacement head or matching an archival format, a technician checks that the head''s track pitch matches the pitch the tape was recorded with.','Track Formats',ARRAY['Track configuration','Guard band','Track width','Twin-track','Track-edge effect','Crosstalk']::text[],ARRAY['Confusing track pitch (centre-to-centre spacing) with track width (the recorded stripe itself).','Forgetting that track pitch includes the guard band, not just the track.','Assuming two formats with the same track count must share the same pitch.']::text[],ARRAY['Comparing a 16-track and a 24-track two-inch format, where the 24-track has a smaller track pitch.','Fitting a head whose track pitch matches an older multitrack tape.','Explaining why a narrower pitch raises crosstalk between neighbouring tracks.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='16e39a89-d8cb-5532-b90b-2f2490549c24' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track pitch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '16e39a89-d8cb-5532-b90b-2f2490549c24','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='16e39a89-d8cb-5532-b90b-2f2490549c24' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f02759f2-6c7d-5bec-afd7-ff051f8c09b7','Track-edge effect','A collective term for signal anomalies at the lateral boundaries of a recorded track, where the recorded field is not sharply defined. Fringing fields extend beyond the physical track and can raise or distort the reproduced output — most noticeably lifting low-frequency level when a wide-track tape is played on a narrower head — while imperfect edge definition and edge damage increase crosstalk, level variation and dropout risk near the edges.','The edges of a recorded track are not perfectly sharp. The magnetic field spreads a little past the track. This edge effect can change the level, add bleed from neighbours, and make dropouts more likely at the sides.','It explains why reproduced level and crosstalk depend on how well the record and playback tracks line up, and why formats use guard bands and matched head widths.','During alignment a technician allows for fringing when a full-width reference tape is played on a narrower head, since edge fields inflate the low-frequency reading.','Recording Physics',ARRAY['Track pitch','Guard band','Track width','Fringing','Crosstalk','Track configuration']::text[],ARRAY['Ignoring fringing when calibrating with a full-track reference tape on a narrower reproduce head, which inflates low-frequency readings.','Assuming a recorded track has perfectly sharp edges with no magnetic field beyond its width.','Blaming edge crosstalk on the electronics when it actually comes from track overlap and fringing fields.']::text[],ARRAY['Explaining a low-frequency level error when a full-width alignment tape is played on a two-track head.','Diagnosing edge crosstalk between adjacent tracks on a multitrack tape.','Setting guard-band width in a format to control edge effects.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f02759f2-6c7d-5bec-afd7-ff051f8c09b7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track-edge effect'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f02759f2-6c7d-5bec-afd7-ff051f8c09b7','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f02759f2-6c7d-5bec-afd7-ff051f8c09b7' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c56500b3-7f20-5dcb-8242-0c9c5be39f3f','Track-format mismatch','The condition where a tape is played on a machine whose head track format differs from the format used to record it — for example a quarter-track tape played on a half-track head. The reproduce gaps then straddle the wrong regions of the tape, producing wrong channel mapping, reduced level, extra crosstalk, and audible artefacts such as superimposed or backward programme.','A track-format mismatch happens when the playback head does not match how the tape was recorded. The head reads the wrong stripes. You get the wrong channels, low level, or backward sound bleeding in.','Recognising the mismatch protects archival transfers, because only a head of the correct format recovers the recording the way it was made.','An archivist who hears a faint backward signal or a level drop suspects a format mismatch and swaps to a head stack matching the original recording format.','Track Formats',ARRAY['Track configuration','Twin-track','Quarter-track','Full-track','Track pitch','Azimuth']::text[],ARRAY['Assuming every quarter-inch tape will play correctly on any quarter-inch machine.','Not documenting the recording format, so the correct playback head cannot be chosen later.','Mistaking mismatch artefacts (backward bleed, low level) for tape damage or a faulty machine.']::text[],ARRAY['Hearing backward speech bleeding through a quarter-track tape played on a half-track head.','Transferring a mono full-track tape on a two-track machine and getting reduced level.','Choosing the right head format before digitising an unlabelled archival reel.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c56500b3-7f20-5dcb-8242-0c9c5be39f3f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track-format mismatch'),'[^a-z0-9]','','g'));
