SELECT 'c56500b3-7f20-5dcb-8242-0c9c5be39f3f','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c56500b3-7f20-5dcb-8242-0c9c5be39f3f' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '23af20df-0f95-52ee-a469-f1625b32d2ac','Transition crowding','The loss of reproduced output and shifting of signal peaks that occurs when recorded magnetic transitions are packed closely together at short wavelengths or high recording densities. The opposing magnetisations of adjacent transitions partially demagnetise one another, reducing short-wavelength output; the effect is also called pulse crowding or bit crowding.','When recorded magnetic flips are squeezed close together, they fight each other. Their opposite fields cancel part of the signal. This makes closely packed pulses, and high frequencies, play back weaker and slightly shifted.','It sets a practical limit on how much high-frequency or high-density information a tape and head can store, and it drives choices of tape speed, gap size and equalisation.','An engineer reduces crowding losses by running a faster tape speed, which lengthens the recorded wavelength and spaces the transitions further apart.','Recording Physics',ARRAY['Wavelength response','Self-demagnetisation','Gap loss','Underbias','Track pitch']::text[],ARRAY['Thinking short-wavelength loss is only gap loss, and ignoring self-demagnetisation between crowded transitions.','Trying to fix crowding losses with more record equalisation instead of a faster tape speed.','Assuming higher density always stores more, when crowding eventually cuts the output.']::text[],ARRAY['Choosing 30 inches per second over 15 for more high-frequency headroom on a master.','Explaining why very high frequencies fall off on slow-speed cassette tape.','Diagnosing weak, smeared high-frequency response on a densely recorded tape.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='23af20df-0f95-52ee-a469-f1625b32d2ac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transition crowding'),'[^a-z0-9]','','g'));
