INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '516b77f1-a4cb-5876-a5d6-8dfd471dc00e','Twin-track','A two-track tape format in which two parallel tracks run in the same direction across the tape, each carrying one channel, typically as a stereo left/right pair on quarter-inch tape. It is distinguished from half-track mono, whose two tracks run in opposite directions.','Twin-track means two tracks side by side, both playing the same way along the tape. Usually one holds the left channel and one holds the right. That gives you stereo in a single pass.','It provides stereo, or two independent channels, on standard quarter-inch tape without flipping the reel, and at a wider track width than four-track for better noise performance.','A studio uses a twin-track (two-track) machine to capture or master a stereo mix, playing both tracks in one direction as a matched pair.','Track Formats',ARRAY['Track configuration','Full-track','Quarter-track','Track pitch','Track-format mismatch']::text[],ARRAY['Confusing twin-track (two tracks, same direction) with half-track mono (two tracks, opposite directions).','Assuming twin-track and quarter-track are the same because both can appear on quarter-inch tape.','Flipping a twin-track reel expecting a second side, which this format does not provide.']::text[],ARRAY['Mastering a final stereo mix onto a two-track quarter-inch machine.','Identifying an old stereo reel as twin-track before transfer.','Choosing twin-track over quarter-track for lower noise on a stereo recording.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='516b77f1-a4cb-5876-a5d6-8dfd471dc00e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Twin-track'),'[^a-z0-9]','','g'));
