WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='516b77f1-a4cb-5876-a5d6-8dfd471dc00e' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '75e9115a-190f-5b75-b427-eeecd4d5edb8','Underbias','A record-alignment condition in which the AC bias current is set below the value that produces peak output at the reference (usually long) wavelength. Underbiasing lifts high-frequency (short-wavelength) output but lowers mid- and low-frequency output, raises harmonic and modulation-noise levels, and makes the recording more sensitive to dropout.','Bias is a steady high tone added while recording so the tape captures sound cleanly. Underbias means setting that tone too low. It boosts the treble but adds distortion and makes the sound less stable.','Bias is set to a defined point for flattest response and lowest distortion; naming the underbiased state helps a technician recognise and correct a mis-set machine.','During alignment the engineer raises bias to peak output, then over-biases by the maker''s figure; a machine left underbiased sounds bright but distorted and noisy.','Bias & Magnetics',ARRAY['Overbias','Bias','Wavelength response','Transition crowding','Weighted tape noise']::text[],ARRAY['UNSAFE: Reaching into an open, powered tape machine to adjust bias without respecting exposed mains-voltage points; follow the maker''s service and lock-out/tag-out procedure.','Deliberately underbiasing to chase a bright top end, which trades treble for distortion, noise and dropout.','Setting bias by ear instead of peaking output at the specified wavelength with test tones.','Forgetting that optimum bias depends on the tape formulation, so a new tape stock needs re-biasing.']::text[],ARRAY['Aligning a machine to a new tape stock and recognising an underbiased, distorted result.','Diagnosing a bright but gritty recording traced to bias set too low.','Setting record bias with an oscillator and level meter during routine calibration.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='75e9115a-190f-5b75-b427-eeecd4d5edb8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Underbias'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
