INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a256a895-e287-5a7b-96b5-5bf84fd1c744','Vacuum buffer','A tape-handling element that uses suction to hold a slack loop of tape, storing tape and decoupling the inertia and sudden motion of the reels from the tape at the capstan and heads. It absorbs start/stop transients and helps maintain steady tape tension.','A vacuum buffer is a suction chamber that holds a loose loop of tape. The loop acts like a shock absorber. It lets the tape start and stop fast at the head without the heavy reels jerking it.','It isolates the low-inertia head and capstan region from the high-inertia reels, allowing rapid start/stop and constant tension without stretching or snapping the tape.','On high-speed transports a technician checks that the tape loops sit correctly in the vacuum buffers and that suction is present before running the machine.','Tape Transport',ARRAY['Vacuum column','Capstan','Tape tension','Reel motor','Pinch roller']::text[],ARRAY['Confusing the vacuum buffer''s tension and isolation job with the capstan''s speed-control job.','UNSAFE: Servicing a running transport near capstan and reel pinch points, or exposed mains, without following the maker''s lock-out/tag-out procedure.','Assuming stronger vacuum is always better, when the loop force is tuned to the tape and tension.']::text[],ARRAY['Threading tape into the vacuum buffers of a high-speed duplicator.','Troubleshooting tension errors traced to weak vacuum in the buffer.','Explaining why fast-start transports use vacuum buffers instead of only tension arms.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a256a895-e287-5a7b-96b5-5bf84fd1c744' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vacuum buffer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a256a895-e287-5a7b-96b5-5bf84fd1c744','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a256a895-e287-5a7b-96b5-5bf84fd1c744' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc093308-026c-5734-88d2-6e924f634570','Vacuum column','A vertical, suction-fed chamber in a tape transport that draws a loop of tape into it with a partial vacuum. The loop forms a compliant buffer that decouples the inertia of the supply and take-up reels from the fast start/stop motion of the tape at the capstan and heads, and helps hold tape tension nearly constant.','A vacuum column is a tall slot that sucks a loop of tape into it. The loop stores slack and works like a spring. It lets the tape start and stop quickly while the big reels catch up smoothly.','It buffers the tape between reels and capstan so the reels'' inertia never jerks the tape at the head, enabling fast, accurate start/stop and steady tension in computer, instrumentation and high-speed audio transports.','A technician verifies vacuum-column suction and that the tape loop rides at the correct depth, since a loop that runs too high or low upsets tension and tracking.','Tape Transport',ARRAY['Vacuum buffer','Capstan','Tape tension','Reel motor','Tape transport']::text[],ARRAY['Confusing the vacuum column (a tension buffer) with the capstan (which controls speed).','UNSAFE: Reaching into a powered transport''s reel and capstan pinch points, or exposed mains, during service without the maker''s lock-out/tag-out procedure.','Assuming any tape-loop depth is fine, when the loop position in the column sets tension and must stay in range.']::text[],ARRAY['Loading tape into the vacuum columns of an IBM-style or high-speed data transport.','Diagnosing tension or start/stop faults caused by a leaking vacuum column.','Explaining why vacuum-column machines can shuttle tape faster than simple tension-arm decks.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc093308-026c-5734-88d2-6e924f634570' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vacuum column'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dc093308-026c-5734-88d2-6e924f634570','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dc093308-026c-5734-88d2-6e924f634570' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '77eeabcc-7d18-5fce-ae0a-26b31cd7dbe2','Wavelength response','The variation of a tape/head system''s reproduced output as a function of the recorded wavelength, where wavelength equals tape speed divided by signal frequency. Analysing performance versus wavelength rather than frequency reveals the physical loss mechanisms — gap loss, spacing loss, thickness loss and self-demagnetisation at short wavelengths, and head-bump ripples at long wavelengths.','Recorded wavelength is how much tape one wave of sound takes up. It equals tape speed divided by frequency. Wavelength response shows how strong the playback is at each wavelength. Short waves lose the most output.','It explains why high frequencies are hard to record and why faster tape speeds help them, guiding the equalisation, gap size and speed choices that flatten the overall frequency response.','Engineers judge a machine on a wavelength basis so results carry across tape speeds, and they raise speed to move troublesome frequencies to longer, easier wavelengths.','Recording Physics',ARRAY['Gap loss','Transition crowding','Underbias','Tape speed','Equalisation']::text[],ARRAY['Treating response as a function of frequency alone, forgetting it really depends on wavelength and tape speed.','Assuming a fixed high-frequency limit, when doubling the tape speed doubles the wavelength for a given frequency.','Blaming only the gap for short-wavelength loss, ignoring spacing, thickness and self-demagnetisation.']::text[],ARRAY['Comparing the same tape at 7.5 and 15 inches per second and seeing better highs at the faster speed.','Setting reproduce equalisation to correct wavelength-dependent losses.','Explaining why a shorter head gap recovers shorter wavelengths.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='77eeabcc-7d18-5fce-ae0a-26b31cd7dbe2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wavelength response'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '77eeabcc-7d18-5fce-ae0a-26b31cd7dbe2','e9c64f09-41cc-480b-affc-4e0919253e5c',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='77eeabcc-7d18-5fce-ae0a-26b31cd7dbe2' AND gt.achievement_id='e9c64f09-41cc-480b-affc-4e0919253e5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8b2cc3dc-7bf7-5dbc-bd16-60af2e65a588','Weighted tape noise','Residual tape noise (hiss) measured through a standard frequency-weighting filter — such as A-weighting or CCIR/ITU-R 468 — so the reading reflects how loud the noise sounds to the ear rather than its raw energy. Weighted figures are quoted as a signal-to-noise ratio relative to a stated reference (alignment) level and typically differ by several decibels from unweighted values.','Tape always adds a faint hiss. Weighted tape noise measures that hiss through a filter shaped like human hearing. So the number matches how loud the hiss really seems, not just its raw power.','Weighting makes a noise specification track perceived loudness, so recorders and tape stocks can be compared fairly and to a repeatable standard.','A technician measures weighted noise on a bulk-erased, biased tape against alignment level to confirm that a machine and tape meet their signal-to-noise specification.','Measurement & Noise',ARRAY['Underbias','Wavelength response','Modulation noise','Signal-to-noise ratio','Bias noise']::text[],ARRAY['Comparing a weighted figure with an unweighted one as if they were the same measurement.','Not stating the weighting curve (A-weighting versus CCIR/ITU-R 468) or the reference level, which makes the number meaningless.','UNSAFE: Bulk-erasing a test tape by switching a hand demagnetiser on or off close to the heads; energise it well away, then approach and withdraw slowly.','Measuring noise on virgin tape and quoting it as the recorded (biased) noise floor, which is higher.']::text[],ARRAY['Verifying a tape machine''s published weighted signal-to-noise ratio during service.','Choosing a weighting curve to match a specification when comparing two tape stocks.','Reporting noise relative to alignment level rather than an undefined signal level.']::text[],'e9c64f09-41cc-480b-affc-4e0919253e5c'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8b2cc3dc-7bf7-5dbc-bd16-60af2e65a588' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Weighted tape noise'),'[^a-z0-9]','','g'));
