INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1e17b405-cd9b-5ddd-98a3-76e4de2a005c','AES57 object structure','AES57-2011 ("AES standard for audio metadata — Audio object structures for preservation and restoration") defines a structured vocabulary and schema of technical, structural, and administrative metadata for describing digital and analog audio objects. Its object structure is the ordered arrangement of these elements around the audio object — its formats, physical and digital characteristics, and the relationships among source item, file, and stream.','AES57 is a rule set for writing down technical facts about a recording. It puts those facts in a set order so any archive can read them. This helps people preserve and restore old audio.','It gives archives a shared, machine-readable way to record the technical and administrative traits of audio objects so preservation data stays consistent and can be exchanged between systems.','An archivist uses AES57, often as XML, to document a transfer''s source carrier, format, and sampling parameters alongside the preservation master file.','Preservation Metadata',ARRAY['Carrier metadata','Audit trail','Archival ingest','Bit-level preservation','Authentic signal representation']::text[],ARRAY['Confusing AES57 (structural and technical audio-object metadata) with descriptive cataloguing metadata such as AES60.','Thinking AES57 stores the audio itself, when it only describes the object and its characteristics.','Treating this metadata as optional, so a preservation file''s format and provenance cannot be verified later.']::text[],ARRAY['Generating AES57-conformant metadata from a batch of digitized tapes.','Recording a source carrier''s format and condition in a preservation metadata record.','Exchanging technical metadata between two archives'' repository systems.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1e17b405-cd9b-5ddd-98a3-76e4de2a005c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('AES57 object structure'),'[^a-z0-9]','','g'));
