WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1e17b405-cd9b-5ddd-98a3-76e4de2a005c' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69ae0f64-2e9d-5353-a544-ead5897372fa','Access derivative','A secondary file created from the preservation master for delivery and everyday use, produced in a lower-bitrate, more compatible, and often lossy format (for example MP3 or AAC) so users can listen without endangering the archival master. It is a transformed copy, not a bit-for-bit duplicate of the original.','An access derivative is an easy-to-play copy made from the archive''s master file. People listen to this copy so the real master stays safe. It is usually smaller and lower in quality.','It lets patrons and staff hear a recording on ordinary devices while the high-resolution preservation master is kept untouched for long-term safekeeping.','After making a preservation master, a technician exports a compressed access derivative for the catalogue or a listening-room delivery system.','Access & Delivery',ARRAY['Bit-level preservation','Archival ingest','Authentic signal representation','Carrier metadata','Audit trail']::text[],ARRAY['Treating an access derivative as a preservation copy, when lossy derivatives discard data and must never replace the master.','Applying heavy processing to the master itself instead of only to the derivative.','Deleting or overwriting the preservation master once a convenient derivative exists.']::text[],ARRAY['Creating MP3 listening copies for an online catalogue.','Supplying a researcher a delivery file while the master stays in secure storage.','Batch-generating derivatives after ingesting newly digitized recordings.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69ae0f64-2e9d-5353-a544-ead5897372fa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Access derivative'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69ae0f64-2e9d-5353-a544-ead5897372fa','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69ae0f64-2e9d-5353-a544-ead5897372fa' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '42a75d9c-912e-5e9f-b032-ef36bf6b1b6b','Archival ingest','In the OAIS reference model (ISO 14721), Ingest is the functional entity that receives Submission Information Packages (SIPs) from producers, performs quality assurance and validation, and generates Archival Information Packages (AIPs) plus descriptive information for storage. In audio archiving it is the controlled process of admitting a preservation file and its metadata into the managed digital repository.','Archival ingest is how a file officially enters the archive''s storage system. The archive checks the file, records its details, and files it away safely. Think of it like checking a book into a library.','It exists to admit content into long-term managed storage under controlled checks, so every object is validated, documented, and trackable from the moment it enters.','A technician runs ingest to validate a new master file''s format and checksum, attach its metadata, and register it into the repository.','Preservation Workflow',ARRAY['Archival transfer chain','Bit-level preservation','Audit trail','Carrier metadata','Access derivative']::text[],ARRAY['Copying files into storage with no validation or metadata and calling it ingest.','Ingesting without generating a checksum, so later integrity checks are impossible.','Confusing ingest (entry into the repository) with the analog-to-digital transfer that precedes it.']::text[],ARRAY['Loading a day''s digitized reels into a preservation repository.','Running format validation during ingest quality assurance.','Registering archival packages and their metadata in a trusted digital repository.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='42a75d9c-912e-5e9f-b032-ef36bf6b1b6b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Archival ingest'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '42a75d9c-912e-5e9f-b032-ef36bf6b1b6b','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='42a75d9c-912e-5e9f-b032-ef36bf6b1b6b' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '28c8c3c8-b6f5-507e-9b0c-0402db75c55a','Archival neutrality','The principle that a preservation transfer should faithfully and impartially capture what is on the original carrier without adding interpretation, correction, or enhancement — no equalization, noise reduction, or level "improvement" applied to the master. Flaws, noise, and artifacts are retained because they are part of the authentic sound document.','Archival neutrality means copying a recording exactly as it is, without fixing it. You do not remove hiss, clicks, or noise. Even the flaws are kept because they are part of the real recording.','It keeps the preservation master honest and trustworthy: because nothing is altered, future users can rely on it and can still apply their own restoration to a derivative later.','During transfer the engineer bypasses corrective EQ and noise reduction, capturing a flat, unprocessed master and leaving any cleanup for access derivatives.','Preservation Principles',ARRAY['Authentic signal representation','Archival transfer chain','Access derivative','Bit-level preservation','AES57 object structure']::text[],ARRAY['Applying noise reduction or corrective EQ to the preservation master, permanently destroying original information.','Assuming a cleaner-sounding capture is automatically a better archival capture.','Confusing neutral capture with doing nothing, when correct playback alignment (speed, azimuth, and the format''s standard replay curve) is still required.']::text[],ARRAY['Deciding not to de-click a noisy 78 rpm disc during preservation transfer.','Justifying an unprocessed flat master to a client who wants it cleaned up.','Keeping tape hiss in the master while removing it only in a listening copy.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='28c8c3c8-b6f5-507e-9b0c-0402db75c55a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Archival neutrality'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '28c8c3c8-b6f5-507e-9b0c-0402db75c55a','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='28c8c3c8-b6f5-507e-9b0c-0402db75c55a' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67c327d7-2979-5854-97c8-dbf60d8c87e1','Archival transfer chain','The complete, controlled signal path used to move a recording from its original carrier into a digital preservation file: the replay machine, any required preamplification and standardized replay equalization, interconnecting cables, a dedicated analog-to-digital converter, and the capture system. Each link must be maintained, aligned, and of quality equal to or exceeding the target digital resolution.','The archival transfer chain is every piece of gear in the path. A sound passes through it when the recording is copied into a digital file. It starts at the player and ends at the computer. Each part must work well or the copy suffers.','It exists so the signal reaches the converter as cleanly and accurately as possible; any weak or misaligned link permanently limits the quality of the preservation master.','Before a session the engineer aligns the playback machine, verifies the A/D converter and levels, and checks cabling so the whole chain is transparent.','Transfer Workflow',ARRAY['Archival neutrality','Authentic signal representation','Archival ingest','AES57 object structure','Carrier preservation']::text[],ARRAY['Using a computer''s built-in sound card instead of a quality standalone analog-to-digital converter.','Leaving the replay machine unaligned in speed, azimuth, or equalization, so its errors are baked into the master.','Ignoring gain staging, so the signal clips or sits too low before the converter.']::text[],ARRAY['Setting up a reel-to-reel deck, preamp, and A/D converter before a transfer session.','Documenting every device in the chain within the transfer metadata.','Tracing added hum back to a faulty cable in the chain.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67c327d7-2979-5854-97c8-dbf60d8c87e1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Archival transfer chain'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
