INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '877862dd-98c6-53b0-8af6-f6092de7e48f','Audit trail','A chronological, tamper-evident record of the actions and events applied to a digital object — who did what, when, and with which equipment or software — that lets the sequence of preservation and transfer events be reconstructed. In audio preservation it documents file creation and every subsequent change, recorded at the time each event occurs.','An audit trail is a dated log of everything done to a file. It records who changed it, when, and how. This lets an archive prove the file''s history and spot tampering.','It supports authenticity and accountability, letting an archive demonstrate provenance, trace errors, and prove a file has changed only in documented ways.','Transfer software and repository systems write audit-trail entries — such as BWF coding history or PREMIS events — each time a file is created, migrated, or fixity-checked.','Preservation Metadata',ARRAY['Carrier metadata','AES57 object structure','Archival ingest','Bit-level preservation','Authentic signal representation']::text[],ARRAY['Writing history notes long after the fact instead of at the moment the event occurs.','Recording only the final file and omitting the intermediate preservation actions.','Confusing an audit trail (a log of actions) with descriptive metadata about the content.']::text[],ARRAY['Logging a format migration in PREMIS event metadata.','Recording coding history in a BWF file''s bext chunk during capture.','Proving chain of custody for a legally sensitive recording.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='877862dd-98c6-53b0-8af6-f6092de7e48f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Audit trail'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '877862dd-98c6-53b0-8af6-f6092de7e48f','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='877862dd-98c6-53b0-8af6-f6092de7e48f' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aa9dccb2-d1fb-5c0c-b233-cccf73bd8fd2','Authentic signal representation','The requirement that a digital transfer faithfully represent the signal actually present on the original carrier — its full frequency content, dynamics, and even its unintended artifacts — without coloration, added noise, or alteration introduced by the replay and conversion chain. It is the authenticity criterion of a preservation master.','Authentic signal representation means the digital copy truly matches the sound on the original. The gear adds no color or noise of its own. What you hear is really what is on the carrier.','It ensures the preservation file can stand in for the original as trustworthy evidence, so researchers and future formats inherit an accurate, unbiased record.','The engineer chooses a transparent converter and aligned playback so the master reflects the carrier, not the equipment, and confirms this by monitoring and metadata.','Preservation Principles',ARRAY['Archival neutrality','Archival transfer chain','AES57 object structure','Bit-level preservation','Access derivative']::text[],ARRAY['Believing a good-sounding transfer is automatically an authentic one.','Letting cheap converters or unaligned machines add coloration that is later mistaken for the original.','Removing ''undesirable'' artifacts that are actually part of the authentic sound document.']::text[],ARRAY['Selecting reference-grade conversion for an irreplaceable master.','Retaining a recording''s original noise floor in the preservation file.','Justifying a transparent, unprocessed master to an archive''s quality reviewer.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aa9dccb2-d1fb-5c0c-b233-cccf73bd8fd2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Authentic signal representation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
