INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '040c3d57-b76e-5801-8a28-1fd1c31b3a40','Belt flattening','A remediation for flexible plastic dictation belts (such as Dictabelt and SoundScriber Memobelt media) that have become permanently creased or curled from flat storage. Careful, gentle warming of the belt, and sometimes the replay machine, can relax the deformation enough for the belt to seat on its playback drums, though success depends on the specific plastic and carries a real risk of further damage.','Belt flattening is a way to relax old dictation belts that got creased in storage. Gently warming the plastic can make it lie flat enough to play. It does not always work and can harm the belt.','It exists to make a deformed belt playable long enough to recover its audio, since a creased belt will not track properly on the replay machine''s drums.','A transfer specialist warms a creased belt slowly and cautiously before mounting it, watching for cracking, to attempt a single recovery transfer.','Carrier Handling',ARRAY['Carrier preservation','Carrier-based obsolescence','Archival transfer chain','Carrier metadata','Celluloid-cylinder delamination']::text[],ARRAY['UNSAFE: Applying direct or high heat — hot air, ovens, or a hair dryer on a high setting — to the plastic, which can melt, warp, or destroy the irreplaceable belt; only gentle, controlled warming suited to the specific plastic is acceptable.','Assuming one method fits every belt, when the correct approach depends on the polymer used.','Forcing a still-creased belt onto the drums, cracking or tearing it.']::text[],ARRAY['Preparing a creased 1950s Dictabelt for a one-time transfer.','Assessing whether gentle warming is safe for an unknown belt plastic.','Recovering dictation belts of legal or historical proceedings.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='040c3d57-b76e-5801-8a28-1fd1c31b3a40' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Belt flattening'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
