INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0742d55f-a2a7-598d-bd9e-bc52e113722a','Bit rot','The gradual, undetected corruption of stored digital data caused by physical or magnetic degradation of storage media, media and hardware faults, or accumulated errors, resulting in changed or lost bits without any deliberate modification. Over time it can render files silently altered or unreadable.','Bit rot is when stored digital files slowly go bad on their own. Tiny errors build up and change or lose bits. The file can end up damaged even though no one touched it.','The term names the silent failure mode that digital preservation must guard against, driving the use of fixity checks, redundancy, and media refreshment to catch and repair loss.','An archivist detects bit rot by comparing stored checksums over time and restores an affected file from a verified backup copy.','Digital Degradation',ARRAY['Bit-level preservation','Audit trail','Archival ingest','Carrier-based obsolescence','Authentic signal representation']::text[],ARRAY['Assuming digital copies last forever because they are ''just data.''','Keeping a single copy with no checksums, so corruption is never noticed until the file fails.','Confusing bit rot (data corruption) with format obsolescence, where the data is intact but the software to read it is gone.']::text[],ARRAY['A stored WAV file fails a routine fixity check years after ingest.','Migrating data off aging hard drives before errors accumulate.','Keeping multiple geographically separated copies to survive silent corruption.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0742d55f-a2a7-598d-bd9e-bc52e113722a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bit rot'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0742d55f-a2a7-598d-bd9e-bc52e113722a','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0742d55f-a2a7-598d-bd9e-bc52e113722a' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b296059-d3d4-512f-8140-0567dccec264','Bit-level preservation','A baseline digital preservation strategy that maintains the exact original bitstream of a digital object unchanged over time, using fixity checks, secure storage, redundancy, and media refreshment. It guarantees the bits survive intact but does not by itself ensure the file stays renderable as software and formats change.','Bit-level preservation means keeping a digital file''s exact bits unchanged over time. The archive checks and copies the data so nothing is lost. It protects the data, but not always the ability to open it later.','It provides the essential foundation of digital preservation — protecting content from loss and corruption — on top of which format and access strategies are built.','An archive stores multiple copies, runs scheduled checksum verification, and refreshes media to keep each preservation master bit-for-bit intact.','Preservation Strategy',ARRAY['Bit rot','Archival ingest','Audit trail','Access derivative','Authentic signal representation']::text[],ARRAY['Assuming bit-level preservation alone keeps files usable, when their formats can still become obsolete.','Skipping fixity checks, so bit-level integrity is claimed but never actually verified.','Keeping all copies on one device or at one site, leaving them exposed to a single failure.']::text[],ARRAY['Running scheduled checksum audits on an audio repository.','Maintaining several copies across two storage types and sites.','Distinguishing bit preservation from a full migration strategy in a preservation plan.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b296059-d3d4-512f-8140-0567dccec264' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bit-level preservation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b296059-d3d4-512f-8140-0567dccec264','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b296059-d3d4-512f-8140-0567dccec264' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '998fcbea-cb2a-5b93-9446-6642c4c89897','Carrier metadata','Metadata that describes the original physical carrier from which a recording is transferred — its format and type, dimensions, base and coating materials, playback speed and equalization, condition, damage, and identifying marks — as distinct from metadata about the resulting digital file. It documents the source object so the transfer can be understood and, if necessary, repeated.','Carrier metadata is written-down facts about the original physical item, like a tape or disc. It notes its type, speed, condition, and any damage. This tells future staff exactly what the sound came from.','It preserves knowledge of the source object after the transfer, supporting authenticity, correct interpretation of the file, and any future re-transfer.','While digitizing, a technician records the carrier''s format, speed, equalization, and condition, often in AES57 or audioObject fields, alongside the file.','Preservation Metadata',ARRAY['AES57 object structure','Carrier preservation','Audit trail','Archival ingest','Carrier-based obsolescence']::text[],ARRAY['Documenting only the digital file and losing the description of the physical source.','Discarding the original carrier''s labels, box notes, or markings instead of capturing them.','Confusing carrier metadata (about the source object) with the digital file''s own technical metadata.']::text[],ARRAY['Logging a reel''s brand, speed, and mold damage before transfer.','Capturing a disc''s diameter, groove type, and playback speed.','Providing source details so a poor transfer can be repeated later.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='998fcbea-cb2a-5b93-9446-6642c4c89897' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Carrier metadata'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '998fcbea-cb2a-5b93-9446-6642c4c89897','f2442389-2379-4010-8b5a-6835773b85c7',true
