INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '09865907-7277-54f7-843b-e3d06d424918','Carrier preservation','Preservation activity aimed at conserving the physical carrier itself — through appropriate storage climate, careful handling, cleaning, and stabilization — to slow its deterioration and keep it playable. In modern audiovisual practice it is subordinate to content preservation: it buys time to transfer the content before the carrier or its playback equipment is lost.','Carrier preservation means caring for the physical item, like a tape or disc, so it lasts longer. You store it well, handle it carefully, and clean it gently. It buys time to copy the sound before the item fails.','It keeps fragile originals stable and playable long enough to extract their content, and protects the object as an artifact where that still matters.','An archivist stores carriers at controlled temperature and humidity, handles them by the edges, and treats problems like mold or sticky tape before transfer.','Preservation Strategy',ARRAY['Carrier metadata','Carrier-based obsolescence','Belt flattening','Celluloid-cylinder delamination','Archival transfer chain']::text[],ARRAY['UNSAFE: Handling mold-affected or biohazardous carriers without gloves and appropriate respiratory protection, risking inhalation of spores; isolate the item and follow conservation health-and-safety guidance.','Believing good storage removes the need to digitize, when carrier care only delays inevitable loss.','Cleaning a carrier with the wrong solvent or method and damaging its surface.']::text[],ARRAY['Setting cold, dry storage for an acetate tape collection.','Stabilizing a moldy reel before transfer.','Prioritizing which fragile carriers to digitize first.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='09865907-7277-54f7-843b-e3d06d424918' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Carrier preservation'),'[^a-z0-9]','','g'));
