WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='09865907-7277-54f7-843b-e3d06d424918' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1bea578f-753a-54b6-a858-9b652a78e967','Carrier-based obsolescence','The form of obsolescence in which content becomes inaccessible not because the carrier has decayed but because the means to play it — the format''s playback machines, spare parts, and technical expertise — are no longer available or maintainable. It makes the window for transferring carrier-based content finite.','Carrier-based obsolescence is when you can no longer play an old format because the machines and parts are gone. The tape or disc may be fine, but nothing can read it. This is why old media must be copied while players still work.','The term highlights an access threat separate from physical decay, driving archives to digitize while working playback equipment and skills still exist.','A manager prioritizes formats whose players are failing or unobtainable, stockpiles machines and parts, and schedules urgent transfers.','Obsolescence',ARRAY['Carrier preservation','Carrier metadata','Bit rot','Archival transfer chain','Belt flattening']::text[],ARRAY['Assuming a carrier in good condition is safe, ignoring that its playback machines are vanishing.','Confusing carrier-based obsolescence (no way to play the media) with media decay (the media itself degrading).','Delaying transfers until the equipment and expertise are already gone.']::text[],ARRAY['Digitizing DAT or U-matic tapes while working decks can still be found.','Stockpiling spare parts and a service technician for aging playback machines.','Planning a digitization deadline before common magnetic-media players disappear.']::text[],'f2442389-2379-4010-8b5a-6835773b85c7'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1bea578f-753a-54b6-a858-9b652a78e967' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Carrier-based obsolescence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1bea578f-753a-54b6-a858-9b652a78e967','f2442389-2379-4010-8b5a-6835773b85c7',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1bea578f-753a-54b6-a858-9b652a78e967' AND gt.achievement_id='f2442389-2379-4010-8b5a-6835773b85c7');
COMMIT;
